const R=[{"id":"moules-marinieres","title":"Moules marinières","lang":"FR","source":"Cookomix","url":"https://www.cookomix.com/recettes/moules-marinieres-thermomix/","cat":"Hauptgerichte","cuisine":"Französisch","tags":["Favorit","Meeresfrüchte","Muscheln","Thermomix","Varoma","einfach"],"servings":"2 Portionen","prep":"10 Min.","total":"36 Min.","ing":[{"h":"","i":["2 échalotes","1 gousse d'ail","20 g de beurre","220 g de vin blanc sec","1 c. à café de jus de citron","50 g d'eau","1 pincée de sel","1 pincée de poivre","1500 g de moules fraîches","100 g de crème fraîche épaisse","15 g de Maïzena","6 brins de ciboulette, ciselés"]}],"steps":[{"h":"","i":["Échalotes et ail : 5 s, vitesse 5.","Ajouter le beurre : 3 min, 100°C.","Ajouter vin blanc, jus de citron, eau, sel et poivre.","Mettre le Varoma en place avec les moules : 20 min, température Varoma. Retirer le Varoma.","Ajouter crème fraîche et Maïzena : 10 s, vitesse 6.","Ajouter la ciboulette : 3 min, 90°C, vitesse 2.","Disposer les moules dans un plat, napper de sauce, servir bien chaud."]}],"notes":["Remuer les moules de temps en temps pendant la cuisson.","Aus den Kommentaren: etwas in die Mitte des Varoma stellen, damit der Dampf besser zirkuliert; Petersilie statt Schnittlauch geht; weniger oder keine Sahne geht auch. Klassisch mit Pommes (moules-frites)."]},{"id":"tomatencremesuppe","title":"Tomatencremesuppe","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 95","cat":"Suppen","cuisine":"International","tags":["Basic","Tomate","vegetarisch (mit Gemüsebrühe)","schnell","Thermomix"],"servings":"4 Portionen","prep":"10 Min.","total":"25 Min.","nutr":"188 kcal pro Portion","ing":[{"h":"","i":["1 Knoblauchzehe","50 g Zwiebeln, halbiert","30 g Butter oder Olivenöl","700 g Tomaten, halbiert","70 g Tomatenmark","1 TL Salz","1 TL Zucker","1 TL Oregano (getrocknet) oder Pizzagewürz","500 g Wasser","1 Brühwürfel (für 0,5 l) oder 1 gehäufter TL Gewürzpaste","100 g Sahne","2–4 Basilikumblätter","1 Stängel Petersilie, abgezupft"]}],"steps":[{"h":"","i":["Knoblauch und Zwiebeln 3 Sek./Stufe 5 zerkleinern, nach unten schieben.","Butter dazu, 3 Min./120°C/Stufe 1 dünsten.","Tomaten, Tomatenmark, Salz, Zucker, Oregano dazu, 5 Sek./Stufe 5.","Wasser und Brühwürfel dazu, 15 Min./100°C/Stufe 2 garen.","Sahne, Basilikum, Petersilie dazu, 1 Min. pürieren, Stufe 4→8 langsam ansteigend. Heiß servieren."]}],"notes":["Statt Pizzagewürz: Thymian, Oregano, Majoran (getrocknet max. 1 TL insgesamt).","Sahne kann durch saure Sahne ersetzt werden."]},{"id":"spargelcremesuppe","title":"Spargelcremesuppe","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 100","cat":"Suppen","cuisine":"Deutsch","tags":["Basic","Spargel","Frühling","vegetarisch","Thermomix"],"servings":"6 Portionen","prep":"20 Min.","total":"40 Min.","nutr":"201 kcal pro Portion","ing":[{"h":"","i":["900 g Wasser","30 g Butter (10 g + 20 g)","1 TL Zucker","500 g weißer Spargel, geschält (Schalen aufheben), 3-cm-Stücke","30 g Speisestärke","1/4 TL Worcestersauce","20 g trockener Weißwein (optional)","1 TL Zitronensaft","1/4 TL Pfeffer","1 1/2 TL Salz","2 Eigelb","200 g Sahne","1 Prise Muskat"]}],"steps":[{"h":"","i":["Wasser, 10 g Butter, Zucker und Spargelschalen in den Mixtopf. Gareinsatz mit Spargel einhängen, 15 Min./100°C/Stufe 1.","Spargel in eine Schüssel. Mixtopfinhalt durch den Gareinsatz abgießen, Spargelwasser auffangen, Schalen beiseite.","Spargel ohne Köpfe, Spargelwasser, 20 g Butter, Stärke: 20 Sek. pürieren, Stufe 4→8.","Worcester, Wein, Zitrone, Pfeffer, Salz dazu, 5 Min./100°C/Stufe 2, dann ca. 5 Min. auf 80°C abkühlen lassen. Inzwischen Eigelb und Sahne verrühren.","Spargelköpfe, Muskat und Eigelb-Sahne dazu, 2 Min./80°C/Linkslauf/Stufe 2. Abschmecken, sofort servieren."]}],"notes":["Bruchspargel reicht völlig; bei wenig Aroma bis 700 g Spargel.","Variante: Hälfte der Sahne durch Milch ersetzen."]},{"id":"rindergulasch","title":"Rindergulasch mit Semmelknödeln","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 116","cat":"Hauptgerichte","cuisine":"Deutsch / Österreichisch","tags":["Basic","Rind","Knödel","Winter","Resteverwertung","Varoma","Thermomix"],"servings":"6 Portionen","prep":"30 Min.","total":"1 Std. 30 Min.","nutr":"554 kcal pro Portion","ing":[{"h":"Semmelknödelteig","i":["6–7 altbackene Brötchen (300 g), 1-cm-Scheiben","5 Stängel Petersilie, abgezupft","80 g Zwiebeln, halbiert","25 g Butter","220 g Milch","3 Eier","1 TL Salz","2 Prisen Pfeffer","2 Prisen Muskat"]},{"h":"Rindergulasch","i":["3 Knoblauchzehen","450 g Zwiebeln, geviertelt","30 g Öl oder Butterschmalz + etwas zum Einfetten","750 g Rindergulasch, gut abgetrocknet","1 TL Zucker","50 g Tomatenmark","350 g Tomaten, kleine Stücke","200 g Rotwein","2 EL Paprika edelsüß","2 TL Salz","1/2 TL schwarzer Pfeffer","1/2 TL Kümmel","1 TL geriebene Zitronenschale","1 EL Majoran","3 Lorbeerblätter","5 Wacholderbeeren","1 Prise Nelkenpulver oder 2 Nelken","300 g Wasser (100 + 50 + 150 g)","30 g Mehl","200 g Paprika rot/grün, dünne Streifen"]}],"steps":[{"h":"Semmelknödelteig","i":["Brötchen mit Spatelhilfe 12 Sek./Stufe 6 zerkleinern, umfüllen.","Petersilie und Zwiebeln 3 Sek./Stufe 6, nach unten schieben.","Butter dazu, 3 Min./120°C/Stufe 1 dünsten.","Milch dazu, 1 Min. 30 Sek./60°C/Stufe 1.","Brötchen, Eier, Salz, Pfeffer, Muskat dazu, 20 Sek./Linkslauf/Stufe 3 mit Spatelhilfe mischen, umfüllen, durchmischen. Mixtopf spülen."]},{"h":"Rindergulasch","i":["Knoblauch, Zwiebeln, Öl 3 Sek./Stufe 5, dann 3 Min./120°C/Stufe 1 dünsten.","Fleisch dazu, 5 Min./120°C/Linkslauf/Sanftrührstufe.","Zucker, Tomatenmark, Tomaten, Rotwein und alle Gewürze dazu, 40 Min./100°C/Linkslauf/Stufe 1. Inzwischen Varoma einfetten, 12 Knödel formen und verteilen.","100 g Wasser dazu, Varoma aufsetzen, 20 Min./Varoma/Linkslauf/Stufe 1. Varoma beiseite.","Mehl mit 50 g Wasser anrühren, mit 150 g Wasser und Paprika in den Mixtopf, Varoma aufsetzen, 8 Min./90°C/Linkslauf/Stufe 1. Abschmecken, mit Knödeln servieren."]}],"notes":["Zu weicher Knödelteig: etwas Paniermehl unterheben. Gut für altes Brot, Toast, Baguette.","Gulasch passt auch zu Nudeln, Salzkartoffeln, Reis oder Brot.","Speck-Semmelknödel: 120 g Schinkenspeck in Schritt 3 mitdünsten.","Hirschgulasch: Hirsch statt Rind, Pilze statt Paprika."]},{"id":"kartoffelpueree","title":"Kartoffelpüree","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 183","cat":"Beilagen","cuisine":"Deutsch","tags":["Basic","Kartoffeln","vegetarisch","einfach","Thermomix"],"servings":"4 Portionen","prep":"15 Min.","total":"45 Min.","nutr":"296 kcal pro Portion","ing":[{"h":"","i":["1000 g mehligkochende Kartoffeln, geschält, 5-mm-Scheiben","1 TL Salz","350 g Milch","30 g Butter, in Stücken","1–2 Prisen Muskat"]}],"steps":[{"h":"","i":["Rühraufsatz einsetzen. Kartoffeln, Salz, Milch ohne Messbecher 25–30 Min./98°C/Stufe 1. Kocht es hoch: auf 95°C reduzieren.","Butter und Muskat dazu, Messbecher einsetzen, 30 Sek./Stufe 3. Heiß servieren."]}],"notes":["Je nach Kartoffelsorte evtl. 5 Min. länger garen.","Cremiger: 100 g Milch extra in Schritt 2.","Italienische Art: nur 1/2 TL Salz, 30 g Parmesan in Schritt 2."]},{"id":"milchreis","title":"Milchreis","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 282","cat":"Desserts","cuisine":"Deutsch","tags":["Basic","süßes Hauptgericht","vegetarisch","einfach","Thermomix"],"servings":"8 Portionen (3–4 als Hauptgericht)","prep":"5 Min.","total":"1 Std.","nutr":"203 kcal pro Portion","ing":[{"h":"","i":["1000 g Milch","50 g Zucker","1 Prise Salz","220 g Milchreis"]}],"steps":[{"h":"","i":["Alles ohne Messbecher 38 Min./90°C/Linkslauf/Stufe 1 garen.","Umfüllen, 15 Min. quellen lassen. Warm oder kalt, mit Zucker oder Zimtzucker."]}],"notes":["Dazu Rote Grütze.","Halbe Menge: 35 Min.; 1,5-fache Menge: 41 Min.","Variante: 1 TL Zitronenschale mitkochen."]},{"id":"germknoedel","title":"Germknödel","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 304","cat":"Desserts","cuisine":"Österreichisch / Bayerisch","tags":["Basic","Hefeteig","Mohn","süßes Hauptgericht","Varoma","Thermomix"],"servings":"4 Stück","prep":"20 Min.","total":"1 Std.","nutr":"623 kcal pro Stück","ing":[{"h":"","i":["40 g Mohn","30 g Zucker (20 + 10 g)","100 g Milch","20 g Hefe (1/2 Würfel)","270 g Mehl","1 Ei","130 g Butter (30 g Teig + 100 g zum Übergießen) + etwas zum Einfetten","1/2 TL Salz","40 g Pflaumenmus","500 g Wasser"]}],"steps":[{"h":"","i":["Mohn und 20 g Zucker 30 Sek./Stufe 10, umfüllen, Mixtopf spülen.","Milch, 10 g Zucker, Hefe 1 Min./37°C/Stufe 3.","Mehl, Ei, 30 g Butter, Salz dazu, 1 Min. 30 Sek./Teigknetstufe.","Varoma fetten. Teig in 4 Teile, flach drücken, Pflaumenmus in die Mitte, zu Knödeln formen.","In den Varoma setzen (Schlitze frei lassen), 30 Min. warm gehen lassen. Mixtopf spülen.","Wasser in den Mixtopf, Varoma aufsetzen, 20 Min./Varoma/Stufe 1. Varoma beiseite, Mixtopf leeren.","100 g Butter 1 Min. 30 Sek./80°C/Stufe 1 schmelzen.","Knödel mit Butter übergießen, Mohnzucker drüber, warm servieren."]}],"notes":["Reicht als süßes Hauptgericht für 2–3 Erwachsene."]},{"id":"bienenstich","title":"Bienenstich","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 332","cat":"Backen","cuisine":"Deutsch","tags":["Basic","Kuchen","Mandeln","Vanillecreme","vorbereiten","Thermomix"],"servings":"12 Stücke · Springform 26 cm","prep":"20 Min.","total":"1 Std. 30 Min. + 4 Std. kühlen","nutr":"376 kcal pro Stück","ing":[{"h":"Teig","i":["50 g Öl + etwas zum Einfetten","1–2 EL Paniermehl","130 g Quark","50 g Milch","1 Ei","300 g Weizenmehl","1 Pck. Backpulver","100 g Zucker"]},{"h":"Belag","i":["50 g Zucker","1 TL Vanillezucker","100 g Butter","30 g Aprikosenkonfitüre","200 g gehobelte Mandeln"]},{"h":"Füllung","i":["5 Blatt weiße Gelatine","500 g Milch","100 g Zucker","1 Pck. Vanillepuddingpulver","200 g Sahne"]}],"steps":[{"h":"Teig","i":["Ofen 180°C. Form fetten, mit Paniermehl ausstreuen.","Quark, Milch, Ei, Mehl, Backpulver, Zucker, Öl 15 Sek./Stufe 5, in die Form. Mixtopf spülen."]},{"h":"Belag","i":["Zucker, Vanillezucker, Butter, Konfitüre 2 Min. 30 Sek./60°C/Stufe 2, dann 5 Sek./Stufe 6.","Mandeln dazu, 8 Sek./Linkslauf/Stufe 1. Auf den Teig streichen, 30 Min. bei 180°C backen, abkühlen lassen."]},{"h":"Füllung","i":["Gelatine einweichen. Mixtopf spülen.","Milch, Zucker, Puddingpulver 6 Min. 30 Sek./100°C/Stufe 3.","Gelatine dazu, 30 Sek./Stufe 3, umfüllen. 25–30 Min. im Wasserbad abkühlen, ab und zu rühren.","Rühraufsatz: Sahne auf Stufe 3 steif schlagen, unter den Pudding heben.","Kuchen halbieren, Creme auf den Boden, kurz anziehen lassen, Mandeldeckel drauf. Mind. 4 Std. (besser über Nacht) kühlen, in 12 Stücke schneiden."]}],"notes":["Mandeldeckel vor dem Füllen schon in 12 Stücke schneiden und dann auf die Creme setzen, sonst schwer zu schneiden."]},{"id":"schwarzwaelder","title":"Kirschtorte Schwarzwälder Art","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 338","cat":"Backen","cuisine":"Deutsch","tags":["Basic","Torte","Kirschen","Schokolade","Sahne","Thermomix"],"servings":"16 Stücke · Springform 26 cm","prep":"20 Min.","total":"1 Std.","nutr":"488 kcal pro Stück","ing":[{"h":"Teig","i":["300 g weiche Butter + etwas zum Einfetten","200 g Zucker","30 g Kakao","5 Eier","300 g Mehl","1 Pck. Backpulver"]},{"h":"Füllung","i":["800 g Sahne","3 TL Vanillezucker","2 Pck. Sahnesteif","50 g Kirschwasser","1 Glas Sauerkirschen, abgetropft (450 g), ein paar für Deko"]},{"h":"Zum Bestreuen","i":["50 g Schokostreusel oder -raspeln"]}],"steps":[{"h":"Teig","i":["Ofen 180°C, Form fetten.","Butter, Zucker, Kakao, Eier 1 Min./37°C/Stufe 5.","Mehl, Backpulver dazu, 30 Sek./Stufe 6 mit Spatelhilfe.","45 Min. bei 180°C backen, auskühlen, zweimal durchschneiden (3 Böden). Mixtopf spülen."]},{"h":"Füllung","i":["Rühraufsatz: Sahne, Vanillezucker, Sahnesteif auf Stufe 3 steif schlagen, umfüllen.","Unterer Boden: halbes Kirschwasser, Kirschen, 1/4 der Sahne.","Zweiter Boden: restliches Kirschwasser, 1/2 der Sahne.","Dritter Boden drauf, Rest Sahne oben und am Rand.","Mit Kirschen und Schokostreuseln verzieren, 16 Stücke."]}],"notes":["Kirschsaft aufheben: für Quarkspeise, Eis oder heiße Kirschsauce.","Für Kinder ohne Kirschwasser."]},{"id":"zupfkuchen","title":"Russischer Zupfkuchen","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 340","cat":"Backen","cuisine":"Deutsch","tags":["Basic","Kuchen","Käsekuchen","Quark","Schokolade","Thermomix"],"servings":"16 Stücke · Springform 26 cm","prep":"20 Min.","total":"1 Std. 30 Min.","nutr":"406 kcal pro Stück","ing":[{"h":"Teig","i":["200 g Butter","150 g Zucker","350 g Mehl","30 g Kakaopulver","1 Pck. Backpulver","1 Ei"]},{"h":"Füllung","i":["180 g weiche Butter","200 g Zucker","4 Eier","500 g Magerquark","1 TL Vanillezucker","1 Pck. Vanillepuddingpulver"]}],"steps":[{"h":"Teig","i":["Ofen 180°C, Form mit Backpapier auslegen.","Alle Teigzutaten 30 Sek./Stufe 6, kurz von Hand kneten. 2/3 in die Form drücken, 3 cm Rand. Rest beiseite."]},{"h":"Füllung","i":["Alle Füllungszutaten 40 Sek./Stufe 5, auf den Boden geben.","Restteig zupfen, auf der Füllung verteilen, 60–70 Min. bei 180°C backen. Abkühlen lassen."]}],"notes":["Aus dem Restteig auch Motive ausstechen (Herzen, Sterne, Häschen)."]},{"id":"zimtsterne","title":"Zimtsterne","lang":"DE","source":"Das Kochbuch – Jeden Tag genießen mit Thermomix, S. 360","cat":"Backen","cuisine":"Deutsch","tags":["Basic","Weihnachten","Plätzchen","Mandeln","glutenfrei","Thermomix"],"servings":"60 Stück","prep":"45 Min.","total":"1 Std. 30 Min.","nutr":"78 kcal pro Stück","ing":[{"h":"","i":["400 g Zucker (100 + 300 g)","2 Zimtstangen (je ca. 5 cm)","500 g Mandeln, ungeschält","2 TL Honig (z. B. Akazie)","3 Eiweiß (2 Teig + 1 Glasur)"]}],"steps":[{"h":"","i":["100 g Zucker 10 Sek./Stufe 10 zu Puderzucker, umfüllen.","300 g Zucker + Zimtstangen 15 Sek./Stufe 10, umfüllen.","Mandeln 15 Sek./Stufe 10.","Zimtzucker dazu, nochmals 15 Sek./Stufe 10.","Honig und 2 Eiweiß dazu, 10 Sek./Stufe 5, von Hand verkneten.","Ofen 150°C, 3 Bleche mit Backpapier. Mixtopf gründlich spülen.","Glasur: Puderzucker + 1 Eiweiß 3 Min./Stufe 3,5, bis weiß und sirupartig.","Zwischen Folie 6–8 mm ausrollen, 60 Sterne ausstechen, glasieren, je Blech 12–14 Min. bei 150°C.","Vorsichtig aufs Gitter (heiß sehr weich), auskühlen, in Dose aufbewahren."]}],"notes":["Statt Zimtstangen: 2 TL gemahlener Zimt.","Statt Folie: aufgeschnittener Gefrierbeutel."]},{"id":"amerikaner","title":"Amerikaner","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 48","cat":"Backen","cuisine":"Deutsch","tags":["Kleingebäck","Zitrone","Kinder","Thermomix"],"servings":"12 Stück","prep":"25 Min.","total":"2 Std.","nutr":"254 kcal pro Stück","ing":[{"h":"Teig","i":["1/4 Bio-Zitrone, Schale dünn abgeschält","100 g Zucker","100 g weiche Butter","10 g Vanillezucker","2 Eier","45 g Milch","200 g Mehl","50 g Speisestärke","2 TL Backpulver"]},{"h":"Guss","i":["200 g Puderzucker","30 g Wasser"]}],"steps":[{"h":"","i":["Ofen 180°C, 2 Bleche mit Backpapier.","Zitronenschale 5 Sek./Stufe 8, nach unten schieben.","Zucker dazu, 15 Sek./Stufe 10, nach unten schieben.","Butter und Vanillezucker dazu, 1 Min./Stufe 3.","Eier, Milch, Mehl, Stärke, Backpulver dazu, 20 Sek./Stufe 4.","Mit zwei Esslöffeln je 6 Häufchen pro Blech setzen (Abstand!). Nacheinander 12–15 Min. bei 180°C backen, ca. 1 Std. abkühlen. Mixtopf spülen.","Puderzucker und Wasser 15 Sek./Stufe 3, die flache Seite bestreichen, trocknen lassen."]}],"notes":["Variante: mit Schokoladenguss oder halb/halb (Rezept im Buch S. 88)."]},{"id":"quark-hefe-taler","title":"Quark-Hefe-Taler","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 50","cat":"Backen","cuisine":"Deutsch","tags":["Kleingebäck","Hefeteig","Quark","Thermomix"],"servings":"10 Stück","prep":"30 Min.","total":"2 Std. 15 Min.","nutr":"363 kcal pro Stück","ing":[{"h":"Teig","i":["2 Eier","50 g Milch","50 g Zucker","1/2 Würfel Hefe (20 g)","350 g Mehl + etwas zum Bearbeiten","120 g weiche Butter","1 Prise Salz"]},{"h":"Belag","i":["1/2 Bio-Zitrone, Schale dünn abgeschält","50 g Zucker","400 g Sahnequark","20 g Sonnenblumenöl","10 g Speisestärke"]}],"steps":[{"h":"Teig","i":["Eier, Milch, Zucker, Hefe 2 Min./37°C/Stufe 2.","Mehl, Butter, Salz dazu, 2 Min./Teigknetstufe. Abgedeckt 1 Std. gehen lassen."]},{"h":"Belag","i":["Ofen 180°C, 2 Bleche mit Backpapier.","Zitronenschale und Zucker 10 Sek./Stufe 10, nach unten schieben.","Quark, Öl, Stärke dazu, 10 Sek./Stufe 3.","Teig zu einer 20-cm-Rolle formen, in 10 Stücke teilen, zu Talern (Ø 8 cm) mit dickerem Rand formen. Je 2 EL Quark in die Mulde, 30 Min. gehen lassen. Nacheinander 15–20 Min. bei 180°C backen."]}],"notes":["Der buttrige Teig geht nicht stark auf, bleibt aber lange frisch.","Mandarinen-Variante (wie auf dem Foto): 2–3 Mandarinenfilets aus der Dose unter den Quark legen.","Oder: abgekühlt mit flüssiger Butter bestreichen und in Zucker wälzen."]},{"id":"franzbroetchen","title":"Franzbrötchen","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 58","cat":"Backen","cuisine":"Deutsch (Hamburg)","tags":["Kleingebäck","Hefeteig","Zimt","Frühstück","Thermomix"],"servings":"18 Stück","prep":"40 Min.","total":"2 Std. 20 Min.","nutr":"212 kcal pro Stück","ing":[{"h":"Teig","i":["220 g Milch","70 g Zucker","1 Würfel Hefe (40 g)","500 g Mehl + etwas zum Ausrollen","50 g weiche Butter","1 Prise Salz"]},{"h":"Füllung","i":["100 g kalte Butter, in sehr dünnen Scheiben","Wasser zum Bestreichen","120 g Zucker","1 1/2 TL Zimt"]}],"steps":[{"h":"Teig","i":["Milch, Zucker, Hefe 2 Min./37°C/Stufe 2.","Mehl, Butter, Salz dazu, 2 Min./Teigknetstufe. Abgedeckt 30 Min. gehen lassen."]},{"h":"Füllung","i":["Teig auf 20 x 30 cm ausrollen, Butterscheiben auf eine Hälfte legen, zuklappen, andrücken. Auf 30 x 50 cm ausrollen, wie einen Brief dritteln. 15 Min. kalt stellen.","Auf 40 x 70 cm ausrollen, mit Wasser bestreichen. Zucker und Zimt mischen, 3 EL beiseite, Rest verteilen. Von der Längsseite aufrollen, Enden begradigen, in 18 Scheiben (ca. 4 cm) schneiden.","Je 9 Scheiben aufrecht mit viel Abstand aufs Blech, mit einem Kochlöffelstiel mittig tief eindrücken. 20 Min. gehen lassen, Ofen auf 200°C.","Mit restlichem Zimtzucker bestreuen, nacheinander 20–25 Min. bei 200°C backen."]}],"notes":[]},{"id":"brownies","title":"Brownies","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 62","cat":"Backen","cuisine":"Amerikanisch","tags":["Kleingebäck","Schokolade","einfach","Party","Thermomix"],"servings":"20 Stück · Form 23 x 23 cm","prep":"20 Min.","total":"1 Std.","nutr":"256 kcal pro Stück","ing":[{"h":"","i":["250 g Zartbitterschokolade","200 g weiche Butter + etwas zum Einfetten","150 g Rohrohrzucker","120 g Zucker","70 g Zuckerrübensirup (z. B. Grafschafter Goldsaft)","4 Eier","200 g Mehl","30 g Kakao"]}],"steps":[{"h":"","i":["Schokolade 8 Sek./Stufe 8, nach unten schieben.","Butter, beide Zucker, Sirup dazu, 6 Min./50°C/Stufe 2, auf 37°C abkühlen lassen (ca. 10 Min.). Ofen 180°C, Formboden mit Backpapier, Rand fetten.","Eier, Mehl, Kakao dazu, 15 Sek./Stufe 4, in die Form, 25–30 Min. bei 180°C backen. In der Form abkühlen, in 20 Stücke schneiden."]}],"notes":["Keine Stäbchenprobe, innen sollen sie feucht bleiben.","In Alufolie ca. 3 Tage frisch. Ohne quadratische Form geht eine Auflaufform."]},{"id":"scones","title":"Scones","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 78","cat":"Backen","cuisine":"Britisch","tags":["Kleingebäck","Teatime","Frühstück","schnell","Thermomix"],"servings":"16 Stück","prep":"25 Min.","total":"40 Min.","nutr":"159 kcal pro Stück","ing":[{"h":"","i":["390 g Mehl (350 g Teig + ca. 40 g zum Ausrollen)","1 Pck. Backpulver","1/4 TL Salz","70 g Zucker","170 g Milch","90 g weiche Butter","1 Ei, verquirlt, zum Bestreichen"]}],"steps":[{"h":"","i":["Ofen 180°C, Blech mit Backpapier.","350 g Mehl, Backpulver, Salz, Zucker, Milch, Butter mit Spatelhilfe 20 Sek./Stufe 6.","Kurz durchkneten, 2 cm dick ausrollen, Kreise (Ø 5 cm) ausstechen, Ausstecher immer wieder in Mehl tauchen. Mit Ei bestreichen, 12–15 Min. bei 180°C backen. Mit Butter und Konfitüre servieren."]}],"notes":["Klassisch mit Clotted Cream (ähnlich Crème double) und Konfitüre."]},{"id":"mud-cake","title":"Chocolate Mud Cake","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 102","cat":"Backen","cuisine":"Australisch","tags":["Kuchen","Schokolade","einfach","Party","Thermomix"],"servings":"12 Stücke · Springform 26 cm","prep":"20 Min.","total":"1 Std. 25 Min.","nutr":"502 kcal pro Stück","ing":[{"h":"","i":["320 g weiche Butter + etwas zum Einfetten","230 g Zucker","1/2 Vanilleschote","260 g Zartbitterschokolade","200 g Buttermilch","3 Eier","260 g Mehl","40 g Kakao + etwas zum Bestäuben","3/4 TL Backpulver","1/4 TL Salz"]}],"steps":[{"h":"","i":["Ofen 150°C, Form fetten.","Zucker und Vanilleschote 30 Sek./Stufe 10, nach unten schieben.","Butter, Schokolade, Buttermilch dazu, 5 Min./50°C/Stufe 2, 5 Min. abkühlen.","Eier, Mehl, Kakao, Backpulver, Salz dazu, 12 Sek./Stufe 5. 50–60 Min. bei 150°C backen, abkühlen, mit Kakao bestäuben."]}],"notes":["Keine Stäbchenprobe, innen soll er feucht sein.","Variante: mit Puderzucker bestäuben."]},{"id":"rhabarber-sahne-kuchen","title":"Rhabarber-Sahne-Kuchen","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 110","cat":"Backen","cuisine":"Deutsch","tags":["Kuchen","Rhabarber","Sahne","Frühling","Thermomix"],"servings":"12 Stücke · Springform 26 cm","prep":"45 Min.","total":"4 Std. 15 Min.","nutr":"336 kcal pro Stück","ing":[{"h":"","i":["100 g weiche Butter + etwas zum Einfetten","2 Eier","220 g Zucker (100 + 100 + 20 g)","50 g Milch","150 g Mehl","2 TL Backpulver","1 Prise Salz","1000 g Rhabarber, in Stücken","100 g Wasser","2 Pck. Vanillepuddingpulver","400 g Sahne","1 Pck. Sahnesteif"]}],"steps":[{"h":"","i":["Ofen 180°C, Formboden mit Backpapier, Rand fetten.","Eier, Butter, 100 g Zucker 30 Sek./Stufe 4.","Milch, Mehl, Backpulver, Salz dazu, 15 Sek./Stufe 5. In die Form, 20 Min. backen, ca. 30 Min. abkühlen. Mixtopf spülen.","Rhabarber, Wasser, 100 g Zucker mit Spatelhilfe 10 Sek./Stufe 5, dann 9 Min./100°C/Stufe 2.","Puddingpulver dazu, 20 Sek./Stufe 5, dann 2 Min./100°C/Stufe 2. Auf den Boden geben, ca. 3 Std. erkalten. Mixtopf spülen.","Rühraufsatz: Sahne, 20 g Zucker, Sahnesteif auf Stufe 3 steif schlagen, auf dem Kuchen verteilen, 30 Min. kühlen."]}],"notes":[]},{"id":"rhabarber-erdbeer-tarte","title":"Rhabarber-Erdbeer-Tarte","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 114","cat":"Backen","cuisine":"International","tags":["Tarte","Rhabarber","Erdbeeren","Frühling","Thermomix"],"servings":"12 Stücke · Tarteform 28 cm","prep":"30 Min.","total":"1 Std.","nutr":"295 kcal pro Stück","ing":[{"h":"Mürbeteig","i":["140 g kalte Butter + etwas zum Einfetten","350 g Mehl + etwas zum Ausrollen","70 g Zucker","90 g Wasser","2 Prisen Salz"]},{"h":"Belag","i":["400 g Rhabarber, 1-cm-Stücke","300 g Erdbeeren, halbiert","120 g Zucker","20 g Vanillezucker","30 g Speisestärke","1 Eigelb","2 EL Milch","Puderzucker zum Bestäuben"]}],"steps":[{"h":"Mürbeteig","i":["Ofen 200°C, Form fetten.","Mehl, Butter, Zucker, Wasser, Salz 15 Sek./Stufe 7. 2/3 in die Form drücken, Boden einstechen."]},{"h":"Belag","i":["Rhabarber, Erdbeeren, Zucker, Vanillezucker, Stärke mit Spatelhilfe 20 Sek./Linkslauf/Stufe 1, auf dem Boden verteilen.","Restteig ca. 23 x 26 cm ausrollen, in 15 Streifen (1,5 cm) schneiden, als Gitter auflegen. Eigelb und Milch verrühren, Gitter bestreichen. 30–35 Min. bei 200°C backen, abkühlen, mit Puderzucker bestäuben."]}],"notes":[]},{"id":"johannisbeer-baiser","title":"Johannisbeer-Baiser-Kuchen","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 122","cat":"Backen","cuisine":"Deutsch","tags":["Kuchen","Johannisbeeren","Baiser","Sommer","Thermomix"],"servings":"12 Stücke · Springform 26 cm","prep":"35 Min.","total":"1 Std. 50 Min.","nutr":"317 kcal pro Stück","ing":[{"h":"Boden","i":["200 g Mehl","1 TL Backpulver","100 g kalte Butter + etwas zum Einfetten","75 g Zucker","1 Ei","400 g rote Johannisbeeren","1 gehäufter EL Speisestärke"]},{"h":"Guss","i":["3 Eier, getrennt","50 g Zucker","200 g Sahne","40 g Speisestärke"]},{"h":"Baiser","i":["150 g Zucker"]}],"steps":[{"h":"Boden","i":["Mehl, Backpulver, Butter, Zucker, Ei 15 Sek./Stufe 5, in Folie 15 Min. kalt stellen. Mixtopf spülen.","Ofen 180°C, Formboden mit Backpapier, Rand fetten.","Teig mit 4 cm Rand in die Form drücken, einstechen. Beeren mit Stärke mischen, verteilen."]},{"h":"Guss","i":["Eigelb, Zucker, Sahne, Stärke 10 Sek./Stufe 5, über die Beeren gießen. 30–35 Min. backen (wackelt es noch, 5 Min. länger). Mixtopf spülen."]},{"h":"Baiser","i":["Zucker 10 Sek./Stufe 10, umfüllen.","Rühraufsatz: Eiweiß 3 Min./Stufe 3,5 steif schlagen.","1 Min./Stufe 3,5 und dabei den Puderzucker nach und nach zugeben.","Auf dem warmen Kuchen verteilen, weitere 12–15 Min. bei 180°C backen."]}],"notes":[]},{"id":"himbeer-quark-streusel","title":"Himbeer-Quark-Streusel","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 130","cat":"Backen","cuisine":"Deutsch","tags":["Kuchen","Käsekuchen","Himbeeren","Streusel","vorbereiten","Thermomix"],"servings":"12 Stücke · Springform 26 cm","prep":"40 Min.","total":"7 Std. 20 Min.","nutr":"563 kcal pro Stück","ing":[{"h":"Mürbeteig","i":["200 g kalte Butter + etwas zum Einfetten","190 g Zucker","330 g Mehl","30 g Vanillezucker"]},{"h":"Füllung","i":["3 Eier, getrennt","1 Prise Salz","120 g weiche Butter","50 g Speisestärke","220 g Zucker","30 g Vanillezucker","750 g Quark (20 %)","300 g Himbeeren, frisch oder TK"]}],"steps":[{"h":"Mürbeteig","i":["Formboden mit Backpapier, Rand fetten, Blech mit Alufolie. Ofen 180°C.","Zucker 30 Sek./Stufe 10, 1 EL Puderzucker zum Dekorieren abnehmen.","Mehl, Butter, Vanillezucker dazu, 15 Sek./Stufe 5. Hälfte als Boden in die Form drücken, Rest kalt stellen. Boden 15 Min. vorbacken."]},{"h":"Füllung","i":["Mixtopf spülen. Rühraufsatz: Eiweiß und Salz 2 Min./Stufe 3,5 steif schlagen, umfüllen.","Eigelb, Butter, Stärke 7 Sek./Stufe 5.","Zucker, Vanillezucker, Quark dazu, 30 Sek./Stufe 4,5, vorsichtig unter den Eischnee heben.","Auf den Boden geben, Himbeeren darauf, Restteig darüberkrümeln. Auf dem Blech ca. 1 Std. 15 Min. bei 180°C backen (nach 30 Min. ggf. abdecken). 10 Min. im ausgeschalteten Ofen ruhen, 2 Std. abkühlen, mind. 3 Std. (besser über Nacht) kühlen. Mit Puderzucker bestäuben."]}],"notes":["Alufolie unter der Form, weil Fett austreten kann.","Variante: Johannisbeeren, Kirschen oder gemischte Beeren."]},{"id":"ny-cheesecake","title":"New York Cheesecake mit Kirschtopping","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 132","cat":"Backen","cuisine":"Amerikanisch","tags":["Käsekuchen","Frischkäse","Kirschen","vorbereiten","Thermomix"],"servings":"12 Stücke · Springform 26 cm","prep":"45 Min.","total":"7 Std.","nutr":"604 kcal pro Stück","ing":[{"h":"Boden","i":["45 g weiche Butter + etwas zum Einfetten","35 g Mehl + etwas zum Bemehlen","4 Eier, getrennt","1 Prise Salz","90 g Zucker","10 g Vanillezucker","1/2 Bio-Zitrone, Schale dünn abgeschält","30 g Speisestärke","1 TL Backpulver"]},{"h":"Frischkäsefüllung","i":["900 g Frischkäse","320 g Zucker","30 g Speisestärke","3 Eier","200 g Sahne"]},{"h":"Kirschtopping","i":["1 Glas Kirschen (680 g), abgetropft, Saft auffangen","30 g Zucker","1 Pck. roter Tortenguss"]}],"steps":[{"h":"Boden","i":["Ofen 180°C, Form fetten und bemehlen.","Rühraufsatz: Eiweiß und Salz 4 Min./Stufe 3,5, umfüllen, Mixtopf spülen.","Zucker, Vanillezucker, Zitronenschale 10 Sek./Stufe 10, nach unten schieben.","Eigelb und Butter 1 Min./Stufe 4.","Mehl, Stärke, Backpulver 5 Sek./Stufe 4.","Eischnee dazu, 5 Sek./Stufe 4, in die Form, 15 Min. backen. 15–20 Min. abkühlen."]},{"h":"Füllung","i":["Ofen wieder 180°C. Form außen dicht mit zwei Bahnen Alufolie umwickeln.","Frischkäse, Zucker, Stärke, Eier, Sahne mit Spatelhilfe 20 Sek./Stufe 4, auf den Boden.","Fettpfanne auf die 2. Schiene von unten, Form hinein, ca. 700 g warmes Wasser angießen (5 mm hoch). 1 Std. 10 Min. backen, Creme darf leicht wackeln. 90 Min. abkühlen."]},{"h":"Topping","i":["Kirschen auf dem Kuchen verteilen.","300 g Kirschsaft, Zucker, Tortenguss 5 Min./100°C/Stufe 1, 30 Sek. abkühlen, von der Mitte über die Kirschen gießen. 3 Std. kalt stellen."]}],"notes":[]},{"id":"kaese-kirsch-kuchen","title":"Käse-Kirsch-Kuchen vom Blech","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 138","cat":"Backen","cuisine":"Deutsch","tags":["Blechkuchen","Käsekuchen","Kirschen","Party","Thermomix"],"servings":"20 Stücke · tiefes Blech","prep":"25 Min.","total":"1 Std.","nutr":"372 kcal pro Stück","ing":[{"h":"Boden","i":["140 g Butter + etwas zum Einfetten","130 g Zucker","3 Eier","300 g Mehl","2 TL Backpulver"]},{"h":"Belag","i":["2 Gläser Sauerkirschen (à 680 g), abgetropft","140 g Zucker","3 Eier","30 g Zitronensaft","600 g Milch","2 Pck. Vanillepuddingpulver","1000 g Quark","150 g Sonnenblumen- oder Rapsöl"]}],"steps":[{"h":"","i":["Ofen 200°C, Fettpfanne einfetten.","Butter, Zucker, Eier, Mehl, Backpulver 30 Sek./Stufe 4, aufs Blech streichen. Mixtopf spülen.","Kirschen verteilen.","Zucker, Eier, Zitronensaft 1 Min./Stufe 4.","Milch, Puddingpulver, Quark 10 Sek./Stufe 4.","Öl dazu, 10 Sek./Stufe 4. Über die Kirschen gießen, 30 Min. bei 200°C backen."]}],"notes":["Variante: Mandarinen oder Pfirsiche statt Kirschen."]},{"id":"frankfurter-kranz","title":"Frankfurter Kranz","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 150","cat":"Backen","cuisine":"Deutsch","tags":["Torte","Buttercreme","Krokant","Feier","Thermomix"],"servings":"16 Stücke · Rodonform 22 cm","prep":"1 Std.","total":"6 Std.","nutr":"317 kcal pro Stück","ing":[{"h":"Biskuit","i":["5 Eier","150 g Zucker","230 g Mehl","1/2 TL Backpulver","1 Prise Salz"]},{"h":"Buttercreme","i":["400 g Milch","80 g Zucker","1 Pck. Vanillepuddingpulver","1 Prise Salz","220 g Butter, zimmerwarm"]},{"h":"Fertigstellung","i":["100 g Sauerkirschkonfitüre","200 g Haselnusskrokant","2 Belegkirschen, in 16 Stücken"]}],"steps":[{"h":"Biskuit","i":["Ofen 180°C.","Rühraufsatz: Eier und Zucker 6 Min./37°C/Stufe 4.","Mehl, Backpulver, Salz neben den Rühraufsatz geben, 4 Sek./Stufe 3, ggf. mit dem Spatel unterheben.","In die ungefettete Form, 20–25 Min. backen, ca. 45 Min. abkühlen. Zweimal waagerecht durchschneiden."]},{"h":"Buttercreme","i":["Milch, Zucker, Puddingpulver, Salz 5 Sek./Stufe 4, dann 6 Min./100°C/Stufe 2,5. Mit Folie direkt auf dem Pudding ca. 2 Std. auf Zimmertemperatur abkühlen.","Butter 1 Min./Stufe 4 aufschlagen.","1 Min. 30 Sek./Stufe 2,5 und den Pudding nach und nach zugeben (nicht glatt: 10 Sek./Stufe 6)."]},{"h":"Fertigstellung","i":["1/3 Creme auf den ersten Boden, Konfitüre aus einem Gefrierbeutel als Kreis daraufspritzen.","Zweiten Boden auflegen, knapp die Hälfte der restlichen Creme und Konfitüre darauf. Deckel aufsetzen, mind. 30 Min. kühlen.","2 EL Creme in einen Spritzbeutel, Torte rundum einstreichen, Krokant andrücken.","16 Tupfen spritzen, mit Belegkirschen verzieren, mind. 1 Std. kühlen."]}],"notes":["Butter und Pudding müssen beide Zimmertemperatur haben, sonst gerinnt die Creme."]},{"id":"erdbeer-pfirsich-torte","title":"Erdbeer-Pfirsich-Torte","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 153","cat":"Backen","cuisine":"Deutsch","tags":["Torte","Erdbeeren","Pfirsiche","Sommer","Feier","Thermomix"],"servings":"12 Stücke · Springform 26 cm","prep":"1 Std.","total":"5 Std.","nutr":"352 kcal pro Stück","ing":[{"h":"Biskuit","i":["4 Eier","120 g Zucker","180 g Mehl","1/2 TL Backpulver","1 Prise Salz"]},{"h":"Füllung und Topping","i":["10 Blatt weiße Gelatine","80 g Zucker","400 g Sahne","500 g Quark (20 %)","40 g Zitronensaft (20 + 20 g)","1 Dose Pfirsiche (450 g abgetropft)","300 g Kirschsaft","1 Pck. roter Tortenguss","500 g Erdbeeren, geviertelt"]}],"steps":[{"h":"Biskuit","i":["Ofen 180°C, Formboden mit Backpapier, Rand nicht fetten.","Rühraufsatz: Eier und Zucker 6 Min./37°C/Stufe 4.","Mehl, Backpulver, Salz 4 Sek./Stufe 3, mit dem Spatel unterheben.","20–25 Min. backen, 45 Min. abkühlen, einmal waagerecht durchschneiden."]},{"h":"Füllung","i":["Gelatine einweichen. Zucker 10 Sek./Stufe 10.","Rühraufsatz: Sahne auf Stufe 3 steif schlagen.","Quark und 20 g Zitronensaft dazu, 8 Sek./Stufe 4, umfüllen.","Pfirsiche und 20 g Zitronensaft 10 Sek./Stufe 10.","Gelatine dazu, 3 Min./50°C/Stufe 3.","1 Min./Stufe 3 und 2/3 der Sahne-Quark-Creme durch die Deckelöffnung zugeben. 15 Min. anziehen lassen.","Unteren Boden mit Springformrand, Pfirsichcreme einfüllen, Deckel auf. Torte und restliche Creme mind. 2 Std. kühlen.","Rand lösen, Torte rundum mit der restlichen Creme einstreichen."]},{"h":"Topping","i":["Kirschsaft und Tortenguss 3 Sek./Stufe 5, dann 3 Min./100°C/Stufe 1.","Erdbeeren unterheben, sofort auf der Torte verteilen. 15 Min. kühlen."]}],"notes":[]},{"id":"pflaumenstrudel","title":"Pflaumenstrudel mit Streuseln","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 166","cat":"Backen","cuisine":"Österreichisch","tags":["Strudel","Pflaumen","Rosmarin","Herbst","Thermomix"],"servings":"12 Stücke (2 Strudel)","prep":"45 Min.","total":"1 Std. 45 Min.","nutr":"420 kcal pro Stück","ing":[{"h":"Strudelteig","i":["370 g Mehl + etwas zum Bearbeiten","1 Ei","40 g Sonnenblumenöl","120 g Wasser","10 g Essig","1/2 TL Salz"]},{"h":"Füllung","i":["1 Stängel Rosmarin, abgezupft","125 g Zucker","100 g Mandeln","150 g Mehl","170 g Butter (120 g Streusel + 50 g zum Bestreichen)","1 Prise Salz","100 g Pflaumenmus","500 g Pflaumen, geviertelt"]}],"steps":[{"h":"","i":["Strudelteig-Zutaten 2 Min./Teigknetstufe, in Folie 30 Min. kalt stellen.","Ofen 230°C, Blech mit Backpapier.","Rosmarin und Zucker 15 Sek./Stufe 10, umfüllen.","Mandeln 10 Sek./Stufe 7.","Mehl, 120 g Butter, Salz, Rosmarinzucker dazu, 10 Sek./Stufe 6 zu Streuseln.","Teig auf einem bemehlten Geschirrtuch dünn ausrollen und mit den Handrücken hauchdünn ausziehen.","50 g Butter 2 Min./80°C/Stufe 2 schmelzen, 2/3 auf den Teig streichen.","Pflaumenmus an einer kurzen Seite verteilen (Rand und Mittelstreifen frei lassen), Streusel und Pflaumen darauf. Mit dem Tuch aufrollen, in der Mitte durchschneiden, Enden verschließen.","Mit restlicher Butter bestreichen, 25–30 Min. bei 230°C backen. Lauwarm servieren."]}],"notes":["Im Buch mit Puderzucker und Vanillesauce serviert."]},{"id":"nussecken","title":"Nussecken","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 190","cat":"Backen","cuisine":"Deutsch","tags":["Plätzchen","Haselnüsse","Weihnachten","Geschenk","Thermomix"],"servings":"30 Stück (1 Blech)","prep":"30 Min.","total":"1 Std. 10 Min.","nutr":"269 kcal pro Stück","ing":[{"h":"Mürbeteig","i":["300 g Mehl","80 g Speisestärke","1 TL Backpulver","20 g Vanillezucker","2 Eier","150 g kalte Butter"]},{"h":"Belag","i":["400 g Haselnüsse","180 g Aprikosenkonfitüre","200 g Butter","200 g Zucker","10 g Vanillezucker","75 g Wasser"]}],"steps":[{"h":"","i":["Teigzutaten 20 Sek./Stufe 5, auf Backpapier auf ca. 30 x 40 cm ausrollen, aufs Blech ziehen.","Ofen 180°C. Mixtopf spülen.","Haselnüsse 10 Sek./Stufe 7, umfüllen.","Konfitüre 4 Min./60°C/Stufe 1, auf dem Teig verteilen.","Butter, Zucker, Vanillezucker 2 Min./60°C/Stufe 1,5.","Nüsse und Wasser dazu, 30 Sek./Stufe 4, verteilen, 30 Min. backen, abkühlen.","In 5 Streifen (8 cm), dann je 3 Rechtecke (10 cm) schneiden, diagonal halbieren."]}],"notes":["Ecken in flüssige Schokolade tauchen (wie auf dem Foto)."]},{"id":"vanillekipferl","title":"Vanillekipferl","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 200","cat":"Backen","cuisine":"Österreichisch","tags":["Plätzchen","Weihnachten","Mandeln","Geschenk","Thermomix"],"servings":"50 Stück","prep":"45 Min.","total":"3 Std. 30 Min.","nutr":"76 kcal pro Stück","ing":[{"h":"","i":["150 g Zucker","20 g Vanillezucker","100 g Mandeln, geschält","280 g Mehl","210 g Butter, in kleinen Stücken"]}],"steps":[{"h":"","i":["Zucker und Vanillezucker 20 Sek./Stufe 10, in eine flache Schale.","Mandeln 5 Sek./Stufe 7.","Mehl, 70 g Vanille-Puderzucker, Butter mit Spatelhilfe 40 Sek./Stufe 5. In Folie 2 Std. kalt stellen.","Ofen 180°C, 2 Bleche mit Backpapier.","Walnussgroße Stücke zu Hörnchen formen, nacheinander 15–20 Min. backen. Warm im restlichen Puderzucker wälzen."]}],"notes":[]},{"id":"sonntagsstuten","title":"Sonntagsstuten","lang":"DE","source":"Das Backbuch – Backen leicht gemacht mit Thermomix TM5, S. 234","cat":"Backen","cuisine":"Deutsch","tags":["Brot","Hefezopf","Frühstück","Brunch","Thermomix"],"servings":"1 Zopf (30 Scheiben)","prep":"25 Min.","total":"2 Std. 25 Min.","nutr":"99 kcal pro Scheibe","ing":[{"h":"","i":["250 g Milch","30 g Hefe (3/4 Würfel)","80 g Zucker","600 g Weizenmehl Type 550","1 TL Salz","50 g Weißwein","1 Eigelb, verquirlt","2 EL Hagelzucker","2 EL Mandelblättchen"]}],"steps":[{"h":"","i":["Milch, Hefe, Zucker 2 Min./37°C/Stufe 2.","Mehl, Salz, Wein dazu, 3 Min./Teigknetstufe. Abgedeckt 1 Std. gehen lassen.","Teig dritteln, zu 45-cm-Strängen rollen, zu einem Zopf flechten. Aufs Blech, mit Eigelb bestreichen, Hagelzucker und Mandeln darauf. 20 Min. gehen lassen, Ofen 180°C.","30–35 Min. bei 180°C backen."]}],"notes":["Im Buch mit Quark/Frischkäse und Konfitüre serviert."]},{"id":"farfalle-salat","title":"Farfalle Salat","lang":"DE","source":"Eigenes Rezeptheft, S. 1","cat":"Salate","cuisine":"Italienisch","tags":["Favorit","Nudelsalat","vegetarisch","Party","Grillen"],"servings":"6–8 Portionen","prep":"","total":"","ing":[{"h":"","i":["500 g Farfalle","1 Glas getrocknete Tomaten (280 g, in Öl)","50 g Olivenöl","50 g heller Balsamico-Essig","1 TL Ajvar","2 EL Oregano","Salz und Pfeffer","1 Bund Lauchzwiebeln","500 g Cocktailtomaten","200 g Pinienkerne","125 g Rucola"]}],"steps":[{"h":"","i":["Alles zusammengeben."]}],"notes":[]},{"id":"mamas-linsensuppe","title":"Mamas Linsensuppe","lang":"DE","source":"Eigenes Rezeptheft, S. 2 – Mamas Rezept","cat":"Suppen","cuisine":"Deutsch","tags":["Favorit","Familienrezept","Linsen","Winter"],"servings":"","prep":"","total":"","ing":[{"h":"","i":["2 Mettwürstchen","2 Tassen Linsen","4 Tassen Kartoffeln (geviertelt)","Suppengemüse","Essig (nach Geschmack)"]}],"steps":[{"h":"","i":["Alles zusammen kochen, mit Essig abschmecken."]}],"notes":[]},{"id":"spinat-spaetzle","title":"Spinat-Spätzle mit Schinken-Sahne-Sauce","lang":"DE","source":"Eigenes Rezeptheft, S. 3","cat":"Hauptgerichte","cuisine":"Schwäbisch","tags":["Favorit","Spätzle","Spinat","Schinken","Thermomix"],"servings":"ca. 4 Portionen","prep":"","total":"","ing":[{"h":"Spätzle","i":["400 g Mehl","250 g TK-Blattspinat","6 Eier","1 TL Salz, Pfeffer, Muskat"]},{"h":"Sauce","i":["1 Zwiebel","30 g Butter","1 TL Mehl","1 Becher Sahne","250 g Milch","Salz, Pfeffer, Muskat","200 g gekochter Schinken"]},{"h":"Zum Servieren","i":["Parmesan"]}],"steps":[{"h":"","i":["Spinat auftauen, Flüssigkeit weggießen.","Spinat und Eier 8 Sek./Stufe 7. Mehl, Salz, Pfeffer, Muskat dazu, 15 Sek./Stufe 5.","Teig 15 Min. ruhen lassen.","Zwiebel 4 Sek./Stufe 5, Butter dazu, 3 Min./100°C/Stufe 1. 1 TL Mehl dazu, 3 Min./100°C/Stufe 1. Sahne, Milch, Gewürze dazu, 6 Min./90°C/Stufe 4, am Ende 10 Sek./Stufe 10.","Spätzleteig ins kochende Salzwasser geben, kurz aufkochen lassen.","Schinken in die Soße, 2 Min./100°C/Linkslauf.","Mit Parmesan bestreut servieren."]}],"notes":[]},{"id":"erdbeer-panna-cotta-torte","title":"Erdbeer-Panna-Cotta-Torte","lang":"DE","source":"Eigenes Rezeptheft, S. 4","cat":"Backen","cuisine":"Deutsch / Italienisch","tags":["Favorit","Torte","ohne Backen","Erdbeeren","Sommer","Thermomix"],"servings":"1 Springform","prep":"","total":"+ mind. 5 Std. kühlen","ing":[{"h":"","i":["200 g Schokoladen-Cookies","50 g Butter","6 Blatt weiße Gelatine","300 g Wasser (zum Einweichen)","250 g Magerquark","500 g Sahne (150 + 100 + 250 g)","100 g Zucker","1 EL Vanillezucker","500 g Erdbeeren"]}],"steps":[{"h":"","i":["Cookies und Butter 15 Sek./Stufe 6, in die Springform drücken, 30 Min. kalt stellen.","Gelatine in Wasser einweichen.","Rühraufsatz: Quark, 150 g Sahne, Zucker, Vanillezucker 30 Sek./Stufe 2,5.","100 g Sahne im Topf erwärmen, Gelatine darin auflösen.","Quarkcreme 50 Sek./Stufe 2,5 rühren, Gelatine zugeben. 30 Min. kalt stellen.","Rühraufsatz: 250 g Sahne auf Stufe 3 steif schlagen.","Quarkcreme zugeben, 8 Sek./Stufe 2,5.","Erdbeeren auf dem Boden verteilen, Creme darübergießen.","Mind. 5 Std. kalt stellen."]}],"notes":[]},{"id":"papas-kirschkuchen","title":"Papas Kirschkuchen","lang":"DE","source":"Eigenes Rezeptheft, S. 5 – Papas Rezept","cat":"Backen","cuisine":"Deutsch","tags":["Favorit","Familienrezept","Kuchen","Kirschen"],"servings":"1 Springform","prep":"","total":"35 Min. Backzeit","ing":[{"h":"Teig","i":["250 g Mehl","150 g Zucker","1 Ei","1 Pck. Vanillezucker","1/2 TL Backpulver","125 g Butter"]},{"h":"Belag","i":["1 Glas Sauerkirschen","1 Pck. Tortenguss","Mandelblättchen","etwas Zucker"]}],"steps":[{"h":"","i":["Die ersten 6 Zutaten mit der Hand verkneten, die Hälfte in der Springform ausrollen, 10 Min. bei 200°C backen.","Etwas Kirschsaft mit Tortenguss andicken, abgetropfte Kirschen und restlichen Saft dazugeben.","Kirschmasse auf den Boden, Restteig in Stückchen darüber, Mandelblättchen und Zucker darüberstreuen.","Noch 25 Min. bei 200°C backen."]}],"notes":[]},{"id":"schmand-torte","title":"Schmand-Torte","lang":"DE","source":"Eigenes Rezeptheft, S. 6","cat":"Backen","cuisine":"Deutsch","tags":["Favorit","Torte","Schmand","Mandarinen","Party"],"servings":"1 Springform","prep":"","total":"20 Min. Backzeit + kühlen","ing":[{"h":"Boden","i":["125 g Butter","100 g Zucker","2 Eier","125 g Mehl","1 TL Backpulver"]},{"h":"Masse","i":["800 g Schmand","2 Dosen Mandarinen","2 Pck. Dr. Oetker Paradies Creme","1 Pck. Sahnesteif","1 Pck. Vanillezucker"]}],"steps":[{"h":"","i":["Boden: Zutaten verrühren, in die Springform, 20 Min. bei 180°C backen, abkühlen.","Mandarinen abtropfen und auf dem Boden verteilen.","Masse: Zutaten verrühren, auf dem Boden verteilen, kalt stellen."]}],"notes":[]},{"id":"dutch-baby","title":"Dutch Baby mit Honig-Himbeeren","lang":"DE","source":"Eigenes Rezeptheft, S. 7","cat":"Frühstück","cuisine":"Amerikanisch","tags":["Favorit","Brunch","Pfannkuchen","Himbeeren"],"servings":"ca. 2 Portionen","prep":"20 Min.","total":"35 Min.","ing":[{"h":"Teig","i":["120 ml Milch","50 g Mehl","2 Eier (verquirlt)","1 EL Rohrzucker","1 TL Vanillezucker","1 Prise Salz"]},{"h":"Honig-Himbeeren","i":["125 g Himbeeren","2 EL Honig","1 Zweig Thymian","1/2 TL Zitronensaft"]},{"h":"Mascarponecreme","i":["3 EL Mascarpone","1 EL Naturjoghurt","1 EL Honig"]},{"h":"Außerdem","i":["2 EL Butter"]}],"steps":[{"h":"","i":["Ofen 220°C mit ofenfester Pfanne vorheizen. Teigzutaten mixen, 20 Min. quellen lassen.","Himbeeren mit Honig, Thymian, Zitronensaft leicht erwärmen.","Mascarponecreme verrühren, kalt stellen.","Pfanne herausnehmen, Butter darin zerlassen. Teig durchrühren, hineingießen, sofort ins obere Drittel, 15 Min. backen.","Mit Himbeeren und Mascarponecreme servieren."]}],"notes":[]},{"id":"clafoutis","title":"Erdbeer-Rhabarber-Clafoutis","lang":"DE","source":"Cookidoo","cat":"Backen","cuisine":"Französisch","tags":["Kuchen","Erdbeeren","Rhabarber","Frühling","Thermomix"],"servings":"12 Stücke · Form 26 cm","prep":"","total":"40–45 Min. Backzeit","ing":[{"h":"Rührteig","i":["20 g weiche Butter + etwas zum Einfetten","100 g Mehl","1 TL Backpulver","110 g Zucker","20 g Vanillezucker","4 Eier","150 g Milch","200 g Sahne","150 g Rhabarber, 2-cm-Stücke","300 g Erdbeeren, halbiert"]},{"h":"Streusel","i":["50 g Macadamianüsse, geröstet, gesalzen","100 g Mehl","50 g Zucker","60 g kalte Butter","Puderzucker zum Bestäuben"]}],"steps":[{"h":"","i":["Ofen 190°C, Form fetten.","Mehl, Backpulver, Zucker, Vanillezucker, Eier 8 Min./37°C/Stufe 5.","Butter, Milch, Sahne dazu, 10 Sek./Stufe 5, nach unten schieben, nochmals 10 Sek./Stufe 5. In die Form, Rhabarber und Erdbeeren darauf. Mixtopf spülen.","Macadamias 3 Sek./Stufe 6.","Mehl, Zucker, Butter dazu, 15 Sek./Stufe 4. Streusel verteilen, auf einem Blech 40–45 Min. bei 190°C backen. Mit Puderzucker bestäuben, z. B. mit Sahne servieren."]}],"notes":[]},{"id":"caesar-salad","title":"Caesar Salad mit Pfeffer-Erdbeeren","lang":"DE","source":"Cookidoo","cat":"Salate","cuisine":"International","tags":["Hähnchen","Spargel","Erdbeeren","Frühling","Varoma","Thermomix"],"servings":"ca. 4 Portionen","prep":"","total":"","ing":[{"h":"","i":["250 g Erdbeeren, geviertelt","1/2 TL grüner Pfeffer, eingelegt, zerdrückt","400 g Hähnchenbrust, 2-cm-Stücke","1/2 TL Salz (1/4 + 1/4)","1/2 TL Pfeffer (1/4 + 1/4)","1/4 TL Paprika edelsüß","60 g Parmesan","500 g Wasser","4 Eier","500 g grüner Spargel, 5-cm-Stücke","100 g Bacon, halbiert","1 Sardellenfilet","1 Knoblauchzehe","1 TL Senf, mittelscharf","40–60 g Zitronensaft","50 g Olivenöl","30 g Rapsöl","1 Römersalatherz, in Streifen"]}],"steps":[{"h":"","i":["Erdbeeren mit grünem Pfeffer mischen. Hähnchen mit 1/4 TL Salz, 1/4 TL Pfeffer und Paprika würzen.","Parmesan 8 Sek./Stufe 6, umfüllen.","Wasser in den Mixtopf, Eier in den Gareinsatz. Varoma mit Hähnchen, Einlegeboden mit Spargel aufsetzen, 14 Min./Varoma/Stufe 1. Bacon in der Pfanne knusprig braten.","Gareinsatz herausnehmen, Varoma wieder aufsetzen, weitere 6 Min./Varoma/Stufe 1. Eier pellen, aus 1 Ei das Eigelb lösen, übrige vierteln.","Mixtopf spülen. Eigelb, Knoblauch, Sardelle, Senf, Zitronensaft, beide Öle, 1/4 TL Salz und Pfeffer 40 Sek./Stufe 6.","Salat, Spargel, Bacon, Hähnchen, Erdbeeren und Eier anrichten, Dressing und Parmesan darüber."]}],"notes":[]},{"id":"auberginen","title":"Gefüllte Auberginen mit Safran und Granatapfel","lang":"DE","source":"Cookidoo","cat":"Hauptgerichte","cuisine":"Orientalisch","tags":["vegetarisch","Bulgur","Granatapfel","Joghurt","Thermomix"],"servings":"6 Auberginenhälften","prep":"","total":"ca. 45 Min.","ing":[{"h":"Auberginen","i":["3 Auberginen","80 g Olivenöl (50 + 30 g)","2 Prisen Salz","100 g Bulgur","250 g Wasser","50 g Frühlingszwiebeln","100 g rote Paprika"]},{"h":"Dressing und Topping","i":["30 g Zitronensaft","50 g Olivenöl","1 TL Safran","1 Knoblauchzehe","180 g griechischer Joghurt (10 %)","30 g Pinienkerne, geröstet","50 g Granatapfelkerne","20 g Basilikum"]}],"steps":[{"h":"","i":["Ofen 200°C, Blech mit Backpapier.","Auberginen längs halbieren, Fruchtfleisch mit 1 cm Rand herauslösen. Mit 50 g Öl bestreichen, salzen, 15 Min. backen.","Bulgur, Wasser, Salz 8 Min./100°C/Linkslauf/Sanftrührstufe, umfüllen.","Auberginenfleisch, Frühlingszwiebeln, Paprika, 30 g Öl 5 Sek./Stufe 5.","Bulgur dazu, Gareinsatz als Spritzschutz, 2 Min./100°C/Linkslauf/Sanftrührstufe. In die Auberginen füllen, 10 Min. backen.","Mixtopf spülen. Zitronensaft, Öl, Safran, Knoblauch, Joghurt 30 Sek./Stufe 5.","Mit Dressing, Granatapfel, Pinienkernen und Basilikum servieren."]}],"notes":[]},{"id":"kaiserschmarrn","title":"Kaiserschmarrn","lang":"DE","source":"Cookidoo","cat":"Desserts","cuisine":"Österreichisch","tags":["süßes Hauptgericht","schnell","Thermomix"],"servings":"2–4 Portionen","prep":"","total":"ca. 15 Min.","ing":[{"h":"","i":["5 Eier (M)","1 Prise Salz","150 g Milch","60 g Zucker","120 g Weizenmehl","1 Pck. Vanillezucker","2 TL Zitronenschale, gerieben","2 EL Butter","2 EL Rosinen","2 EL Puderzucker"]}],"steps":[{"h":"","i":["Ofen 180°C Ober-/Unterhitze. Eier trennen.","Rühraufsatz: Eiweiß und Salz ohne Messbecher 6 Min./Stufe 3,5, umfüllen.","Milch, Zucker, Mehl, Vanillezucker, Zitronenschale ohne Messbecher 30 Sek./Stufe 4, dabei die Eigelbe zugeben.","Eischnee dazu, 30 Sek./Stufe 3.","Butter in einer ofenfesten Pfanne schmelzen, Teig hinein, Rosinen darauf, ca. 3 Min. goldbraun backen. Vierteln, wenden, 5 Min. im Ofen fertigbacken. Mit zwei Gabeln zerreißen, mit Puderzucker bestreuen."]}],"notes":[]},{"id":"blintzes","title":"Blueberry Cheese Blintzes","lang":"DE","source":"Zeitschrift (Ausdruck)","cat":"Desserts","cuisine":"Amerikanisch","tags":["Crêpes","Ricotta","Blaubeeren","Brunch","vegetarisch"],"servings":"4 Portionen","prep":"","total":"","ing":[{"h":"Teig","i":["15 g Butter + mehr zum Braten","3 Eier (M)","1 Prise Meersalz","100 g Weizenmehl Type 550","320 ml Milch"]},{"h":"Ricottafüllung","i":["250 g Ricotta","50 g Zucker","1 Pck. Bourbon-Vanillezucker","2 Eiweiß","1 EL Speisestärke"]},{"h":"Fruchtfüllung","i":["1 EL Butter","250 g Blaubeeren (TK)","40 g Zucker","1 EL Speisestärke"]}],"steps":[{"h":"","i":["Butter schmelzen und abkühlen. Eier und Salz aufschlagen, Mehl und Milch unterrühren, Butter untermischen.","Butter in einer großen Pfanne erhitzen, 1/4 des Teigs 3–4 Min. backen. Abgedeckt stapeln, 4 Blintzes backen.","Ricotta, Zucker, Vanillezucker, Eiweiß im Topf verrühren und aufkochen. Stärke mit kaltem Wasser anrühren, einrühren, andicken lassen.","Butter zerlassen, Blaubeeren und Zucker 5 Min. köcheln, angerührte Stärke einrühren, andicken lassen. Beide Füllungen auf je eine Hälfte geben, aufrollen, halbieren."]}],"notes":[]},{"id":"orange-chicken","title":"Crispy Orange Chicken with Veggie Fried Rice","lang":"EN","source":"US-Zeitschrift (Ausdruck)","cat":"Hauptgerichte","cuisine":"Amerikanisch-Chinesisch","tags":["Hähnchen","Reis","frittiert","Orange"],"servings":"4 Portionen","prep":"","total":"","ing":[{"h":"","i":["4 large egg whites","2 tbsp cornflour","450 g chicken thighs, 2.5 cm pieces","2 tbsp vegetable oil + oil for frying","300 g frozen mixed vegetables, thawed","ca. 650 g cooked rice (ca. 220 g uncooked)","2 3/4 tsp garlic powder, divided","1 1/2 tsp coarse salt, divided","160 g orange marmalade","60 ml chicken stock","1 tbsp Worcestershire sauce","1/2 tsp ground ginger","Spring onion to garnish"]}],"steps":[{"h":"","i":["Whisk egg whites and cornflour, stir in chicken, rest 15 min.","Fry vegetables in 2 tbsp oil 2–4 min. Add rice, 2 tsp garlic powder, 1 tsp salt, stir-fry 2–3 min. Keep warm.","Heat 5 cm oil to 185°C.","Fry chicken in batches 2–3 min until golden, drain. Fry again 1 min.","Boil marmalade, stock, Worcestershire, ginger, rest of garlic powder and salt, cook ca. 5 min. Toss with chicken, serve with rice."]}],"notes":[]},{"id":"turkey-fajita","title":"Turkey Fajita Bake","lang":"EN","source":"US-Zeitschrift (Ausdruck)","cat":"Hauptgerichte","cuisine":"Tex-Mex","tags":["Pute","Paprika","Ofengericht","einfach"],"servings":"4 Portionen","prep":"","total":"20–25 Min. Backzeit","ing":[{"h":"","i":["450 g turkey cutlets, in strips","1 red bell pepper, in strips","1 yellow bell pepper, in strips","1/2 red onion, thinly sliced","100 g grated Cheddar","1 sachet taco seasoning (ca. 35 g)","2 spring onions, chopped","1 packet Spanish/Mexican rice mix (ca. 190 g)","1 can diced tomatoes (400 g)"]}],"steps":[{"h":"","i":["Preheat oven to 190°C, grease a ca. 23 x 23 cm dish.","Toss turkey, peppers, onion, cheese and taco seasoning, spread in the dish.","Bake 20–25 min until the turkey is cooked through.","Cook the rice with the tomatoes according to the packet. Serve together, garnish with spring onion."]}],"notes":[]},{"id":"kraeuterfaltenbrot","title":"Kräuterfaltenbrot","lang":"DE","source":"Thermomix Magazin, Willkommensausgabe, S. 40","cat":"Backen","cuisine":"Deutsch","tags":["Brot","Kräuterbutter","Party","Grillen","Thermomix"],"servings":"20 Portionen · Springform 26 cm","prep":"20 Min.","total":"1 Std. 10 Min.","nutr":"173 kcal pro Portion","ing":[{"h":"Teig","i":["300 g Wasser","1 Würfel Hefe (40 g)","1/2 TL Zucker","600 g Mehl","2 TL Salz","50 g Öl"]},{"h":"Kräuterbutter","i":["120 g weiche Butter + etwas zum Einfetten","1 Knoblauchzehe","1 Zwiebel, halbiert","3 Stängel Petersilie","3 Stängel Basilikum","1 TL Salz"]}],"steps":[{"h":"","i":["Wasser, Hefe, Zucker 2 Min./37°C/Stufe 2.","Mehl, Salz, Öl dazu, 2 Min./Teigknetstufe. Zu einem Rechteck (ca. 30 cm) ausrollen.","Form fetten, Ofen 200°C.","Knoblauch, Zwiebel, Kräuter 8 Sek./Stufe 5.","Butter und Salz dazu, 25 Sek./Stufe 6.","Teig mit Kräuterbutter bestreichen, in 5-cm-Streifen schneiden, wie eine Ziehharmonika falten, dicht in die Form setzen, 15 Min. gehen lassen. Auf einem Blech 25–30 Min. bei 200°C backen."]}],"notes":["Eine quadratische Form eignet sich besonders gut."]},{"id":"tex-mex-potato-salad","title":"Tex-Mex Potato Salad","lang":"EN","source":"Taste of Home","url":"https://www.tasteofhome.com/recipes/tex-mex-potato-salad/","cat":"Salate","cuisine":"Tex-Mex","tags":["Kartoffelsalat","Avocado","vegetarisch","Grillen"],"servings":"12 Portionen","prep":"20 Min.","total":"40 Min. + kühlen","ing":[{"h":"","i":["2 corn cobs","1 large red bell pepper","900 g small red potatoes","1 avocado, cubed","150 g cherry tomatoes, halved","2 spring onions, 1 cm slices","60 g light sour cream or Greek yogurt","60 g light mayonnaise","60 g salsa","2 tbsp lime juice","1 tbsp red wine vinegar","2 tsp chopped pickled jalapeños","1/2 tsp salt","1/4 tsp each garlic powder, onion powder, cumin, pepper","1 pinch cayenne","Fresh coriander"]}],"steps":[{"h":"","i":["Roast corn and pepper at 200°C for 20–25 min, turning once. Peel the pepper, cut into 1 cm pieces, cut corn off the cob.","Boil potatoes 10–12 min until tender, cool, halve. Add pepper, corn, avocado, tomatoes, spring onions.","Blend sour cream, mayo, salsa, lime, vinegar, jalapeños and spices. Toss with the salad, chill. Serve with coriander."]}],"notes":["Optional: a can of black beans for more protein."]},{"id":"frittata","title":"Frittata mit Kartoffeln, Paprika und Feta","lang":"DE","source":"Kochbuch (Ausdruck)","cat":"Frühstück","cuisine":"Mediterran","tags":["Eier","Kartoffeln","Feta","Brunch","vegetarisch"],"servings":"2–4 Portionen","prep":"","total":"ca. 30 Min.","ing":[{"h":"","i":["75 ml Olivenöl (50 + 25 ml)","600 g festkochende Kartoffeln, dünne Scheiben","1 TL Salz (1/2 + 1/2)","1 große Zwiebel, gewürfelt","2 Knoblauchzehen, gehackt","4 Eier","schwarzer Pfeffer","1/2 rote Paprika, grob gewürfelt","10 schwarze Oliven, in Ringen","1 Handvoll Kirschtomaten","100 g Feta, zerbröselt","4 Stängel glatte Petersilie, gehackt"]}],"steps":[{"h":"","i":["Backofengrill vorheizen. Kartoffeln in 50 ml Öl kurz scharf anbraten, 1/2 TL Salz, bei reduzierter Hitze 10–15 Min. bissfest garen. Zwiebel und Knoblauch 5 Min. mitbraten, leicht abkühlen.","Eier mit 1/2 TL Salz und Pfeffer schaumig schlagen, Kartoffeln, Paprika, Oliven unterheben. Restliches Öl in einer ofenfesten Pfanne erhitzen, Masse hinein, Tomaten und Feta darauf, bei geringer Hitze einige Min. stocken lassen.","Ca. 5 Min. unter dem Grill fertig garen, 5 Min. ruhen lassen, mit Petersilie servieren."]}],"notes":["Schmeckt am besten am Vortag gemacht."]},{"id":"chicken-gyros","title":"Chicken Gyros","lang":"EN","source":"Taste of Home","url":"https://www.tasteofhome.com/recipes/chicken-gyros/","cat":"Hauptgerichte","cuisine":"Griechisch","tags":["Hähnchen","Pita","Tzatziki","schnell"],"servings":"2 Portionen","prep":"20 Min. + 1 Std. marinieren","total":"30 Min.","ing":[{"h":"","i":["60 ml lemon juice","2 tbsp olive oil","3/4 tsp minced garlic, divided","1/2 tsp mustard powder","1/2 tsp dried oregano","225 g chicken breast, 1 cm strips","70 g cucumber, peeled and chopped","80 g plain yogurt","1/4 tsp dried dill","2 pita breads","1/2 small red onion, sliced"]}],"steps":[{"h":"","i":["Mix lemon juice, oil, 1/2 tsp garlic, mustard and oregano in a bag, add chicken, refrigerate at least 1 hour. Mix cucumber, yogurt, dill and remaining garlic, chill.","Drain the chicken, fry 7–8 min until cooked. Fill the pitas, top with yogurt sauce and onion, fold."]}],"notes":["Lettuce and diced tomato on top are nice."]},{"id":"pad-kra-pao","title":"Pad Kra Pao","lang":"EN","source":"Takes Two Eggs","url":"https://takestwoeggs.com/pad-kra-pao/","cat":"Hauptgerichte","cuisine":"Thailändisch","tags":["Favorit","Schwein","Basilikum","scharf","schnell"],"servings":"2 Portionen","prep":"5 Min.","total":"15 Min.","ing":[{"h":"","i":["1–3 Thai chillies, sliced","6 cloves garlic, minced","2 shallots, minced","3 tbsp vegetable oil","450 g minced pork","ca. 30 g holy basil (or regular basil)"]},{"h":"Sauce","i":["1 tbsp oyster sauce","1 tbsp fish sauce","2 tsp soy sauce (Golden Mountain)","1 tsp dark soy sauce","1 tbsp sugar","80 ml chicken stock"]},{"h":"To serve","i":["Fried egg","Steamed rice"]}],"steps":[{"h":"","i":["Mix oyster, fish, soy and dark soy sauce with the sugar.","Sauté shallots, garlic and chillies in oil over medium-high heat ca. 45 sec.","High heat: add pork, break up, sear and toss 4–5 min until charred and dry.","Add sauce, deglaze with stock, reduce ca. 1 min.","Toss in basil until just wilted.","Serve with fried egg and rice."]}],"notes":["Less heat: fewer chillies, seeds removed. Works with beef, chicken, turkey or tofu."]},{"id":"chocolate-chip-muffins","title":"Chocolate Chip Muffins","lang":"EN","source":"The First Year Blog","url":"https://thefirstyearblog.com/chocolate-chip-muffins/","cat":"Backen","cuisine":"Amerikanisch","tags":["Favorit","Muffins","Schokolade","Frühstück"],"servings":"12 Muffins","prep":"10 Min. + 15 Min. Ruhe","total":"ca. 50 Min.","ing":[{"h":"","i":["480 g plain flour","300 g sugar","4 tsp baking powder","1 tsp salt","1/4 tsp nutmeg (or cinnamon)","4 eggs","240 ml whole milk (or buttermilk)","100 g vegetable oil","57 g butter, melted and cooled","2 tsp vanilla extract","340 g chocolate chips (255 g batter + 85 g topping)","Coarse sugar"]}],"steps":[{"h":"","i":["Mix flour, sugar, baking powder, salt and nutmeg.","Combine eggs, milk, oil, butter and vanilla.","Fold dry ingredients and 255 g chips into the wet mix until just combined.","Cover, rest 15 min. Preheat oven to 220°C (no fan).","Fill every other hole of the lined tin generously (ca. 120 ml each). Top with chips and sugar.","Bake 7 min at 220°C, then 12–16 min at 175°C. Repeat with the rest, reheating to 220°C."]}],"notes":["Rest and high starting heat give the domed tops. Best warm."]},{"id":"pfirsich-crumble","title":"Pfirsich-Crumble mit Mandeln","lang":"DE","source":"Zucker, Zimt und Liebe","url":"https://www.zuckerzimtundliebe.de/2022/08/pfirsich-crumble-rezept-mit-mandeln-peach-crumble-recipe/","cat":"Desserts","cuisine":"International","tags":["Favorit","Crumble","Pfirsiche","Sommer","schnell"],"servings":"4 Portionen","prep":"15 Min.","total":"50 Min.","ing":[{"h":"Pfirsiche","i":["3 reife Pfirsiche","2 EL Zucker","1 TL Speisestärke"]},{"h":"Streusel","i":["125 g Mehl","1/4 TL Backpulver","3 EL Zucker","1 TL Bourbon-Vanillezucker","2 EL gemahlene Nüsse","90 g kalte Butter, gewürfelt","2 EL gehobelte Mandeln"]},{"h":"Außerdem","i":["Puderzucker, Eis oder Vanillesauce"]}],"steps":[{"h":"","i":["Ofen 180°C Ober-/Unterhitze, kleine Auflaufform (ca. 15 x 25 cm) fetten.","Pfirsiche in Scheiben schneiden, mit Zucker und Stärke ziehen lassen.","Mehl, Backpulver, Zucker, Vanillezucker, Nüsse mischen, eiskalte Butter mit den Fingern zu Streuseln verarbeiten.","Pfirsiche in die Form, Streusel und Mandeln darüber, 30–35 Min. backen.","Warm mit Eis oder Vanillesauce servieren."]}],"notes":["Butter sehr kalt verarbeiten, dann bleiben die Streusel knusprig."]},{"id":"cinnamon-rolls","title":"Cinnamon Rolls","lang":"EN","source":"Broma Bakery (angepasst)","url":"https://bromabakery.com/homemade-cinnamon-rolls-soft-fluffy/","cat":"Backen","cuisine":"Amerikanisch","tags":["Noch nie gemacht","Hefeteig","Zimt","Brunch","Herbst"],"servings":"12 Stück","prep":"30 Min. + 2 Std. gehen","total":"ca. 3 Std. 15 Min.","ing":[{"h":"Dough","i":["585 g bread/high-protein flour (Jumbo Patent Bloem extra fijn)","70 g sugar","7 g instant yeast","1 tsp salt","360 ml milk","85 g unsalted butter","1 egg, room temperature"]},{"h":"Filling","i":["115 g butter, softened","140 g light brown sugar (Van Gilse lichte basterdsuiker)","2 tbsp cinnamon","1 pinch salt"]},{"h":"For baking","i":["120 ml slagroom 35%, warmed"]},{"h":"Frosting","i":["115 g cream cheese (Philadelphia)","115 g butter, softened","335 g powdered sugar","30 ml milk","1 tsp vanilla","1 pinch salt"]}],"steps":[{"h":"","i":["Stand mixer with whisk: mix ca. 250 g flour with sugar, yeast and salt.","Warm milk and butter until the butter mostly melts (not hot).","Add to the flour with the egg, mix on low, then beat 2 min on high (batter-like is normal).","Dough hook: add ca. 200 g flour, knead, then the rest (585 g total).","Knead ca. 10 min on medium-low until smooth and stretchy.","Rise covered in an oiled bowl ca. 1 hour until doubled.","Mix butter, brown sugar, cinnamon and salt into a paste.","Roll dough to ca. 30 x 45 cm, spread the filling to the edges.","Roll up tightly from the long side, cut into 12, place in a lined ca. 23 x 33 cm dish, rise ca. 1 hour.","Preheat to 175°C. Pour the warm cream over the rolls right before baking.","Bake ca. 30 min until golden, cool 15 min.","Beat the frosting ingredients until fluffy, spread over the warm rolls."]}],"notes":["Shorter baking keeps them softer. Can do the second rise overnight in the fridge."]},{"id":"california-onigiri","title":"California Onigiri","lang":"EN","source":"Eatnik","url":"https://eatnik.com.au/california-onigiri/","cat":"Snacks","cuisine":"Japanisch","tags":["Noch nie gemacht","Reis","Surimi","Avocado","Meal Prep"],"servings":"12 Onigiri","prep":"","total":"ca. 45 Min.","ing":[{"h":"Rice","i":["450 g short-grain (sushi) rice","560 ml water","110 g tobiko"]},{"h":"Filling","i":["5 imitation crab sticks","2 tbsp Kewpie mayonnaise","1/2 avocado","1/2 cucumber"]},{"h":"To wrap","i":["6 sheets nori"]}],"steps":[{"h":"","i":["Rinse rice until the water runs clear. Cook in a rice cooker, or bring to a boil with the water, then lowest heat with lid 12–15 min. Cool slightly.","Shred crab sticks, mix with mayo. Dice avocado and seeded cucumber (0.5–0.7 cm).","Stir tobiko into the rice. Wet the mould (or your hands) between onigiri.","Press ca. 60 ml rice into the mould with a well, add 1 tbsp crab and 1 tsp each cucumber and avocado, cover with ca. 60 ml rice, press firmly.","Wrap each in half a nori sheet (keep separate until eating for crisp nori)."]}],"notes":["Spicy version: sriracha or chilli oil in the crab mix."]},{"id":"tarte-tatin","title":"Tarte Tatin","lang":"DE","source":"Einfach Backen","cat":"Backen","cuisine":"Französisch","tags":["Noch nie gemacht","Tarte","Äpfel","Karamell","Herbst"],"servings":"1 Tarte (25–26 cm)","prep":"","total":"1 Std. 45 Min.","ing":[{"h":"Mürbeteig","i":["200 g Weizenmehl (405)","60 g Puderzucker","etwas Zitronenabrieb","1 Prise Salz","100 g kalte Butter","1 Ei (M)"]},{"h":"Äpfel und Karamell","i":["750 g Äpfel (z. B. Boskop)","2 EL Zitronensaft","125 g Puderzucker","4 EL Wasser","125 g Butter"]}],"steps":[{"h":"","i":["Teigzutaten schnell verkneten, in Folie ca. 30 Min. kalt stellen.","Äpfel schälen, vierteln, entkernen, mit Zitronensaft beträufeln.","Puderzucker und Wasser in der Form/Pfanne goldbraun karamellisieren, Butter darin schmelzen.","Äpfel dicht kreisförmig in den Karamell legen, 3–4 Min. dünsten. Ofen 200°C O/U (175°C Umluft).","Teig rund ausrollen, über die Äpfel legen, Rand andrücken. 30–35 Min. backen.","5–8 Min. abkühlen, mit Schwung auf eine Platte stürzen. Lauwarm mit Sahne oder Eis."]}],"notes":["Schritte aus dem Lecker-Schritt-für-Schritt-Rezept ergänzt, beim ersten Mal mit dem Original abgleichen."]},{"id":"apple-fritters","title":"Apple Fritters","lang":"EN","source":"A Bright Moment","url":"https://abrightmoment.com/the-best-apple-fritters-recipe/","cat":"Backen","cuisine":"Amerikanisch","tags":["Noch nie gemacht","Donuts","Äpfel","frittiert","Herbst"],"servings":"12 Stück","prep":"20 Min. + 1,5–2,5 Std. gehen","total":"ca. 2 Std. 20 Min.","ing":[{"h":"Dough","i":["240 ml whole milk, warmed (ca. 43°C)","50 g sugar","7 g dried yeast","80 ml extra virgin olive oil","1 egg","1 tsp vanilla","1/2 tsp salt","ca. 375 g plain flour + more"]},{"h":"Apple filling","i":["ca. 750 g apples, finely chopped","200 g brown sugar","2 tsp cinnamon","1/2 tsp nutmeg","4 tsp cornflour","2 tbsp water","1 1/2 tsp vanilla"]},{"h":"Glaze","i":["360 g powdered sugar","120 ml whole milk","1 tsp vanilla bean paste"]},{"h":"","i":["Frying oil"]}],"steps":[{"h":"","i":["Dough hook: milk, sugar and yeast, rest 3–5 min until foamy.","Add oil, egg, vanilla, salt, then flour; knead 4–5 min. Rise covered 1–2 hours.","Cook apples, brown sugar and spices in a pan ca. 5 min, then covered on low 10 min.","Off the heat stir in vanilla and cornflour mixed with water. Cool.","Roll dough 1.3 cm thick, spread filling on one half, fold and seal.","Cut into 2.5 cm squares, stack, shape ca. 80 ml portions into fritters.","Place on floured baking paper squares, cover, rise 30–45 min.","Heat 8–10 cm oil to 175–185°C. Fry in batches 1–3 min per side, drain on a rack.","Whisk the glaze, dip the tops, let set 5–10 min. Serve warm."]}],"notes":["Doughy centre = oil too hot or fritters too big. Reheat in the air fryer at 150°C."]},{"id":"air-fryer-bagels","title":"Air Fryer Bagels","lang":"EN","source":"A Bright Moment","url":"https://abrightmoment.com/15-minute-air-fryer-bagel-recipe/","cat":"Frühstück","cuisine":"Amerikanisch","tags":["Noch nie gemacht","Bagels","ohne Hefe","Airfryer","schnell"],"servings":"6 Bagels","prep":"5 Min.","total":"15 Min.","ing":[{"h":"","i":["250 g plain flour + up to 30 g","1 tbsp baking powder","1 tsp fine sea salt","480 g plain Greek yogurt","1 egg, beaten","Toppings (everything seasoning, poppy seeds, jalapeño and cheddar)"]}],"steps":[{"h":"","i":["Mix flour, baking powder, salt, add yogurt, mix to a shaggy dough.","Knead until smooth, adding flour as needed.","Divide into 6, roll into 13–15 cm ropes, pinch into rings.","Line the air fryer basket with baking paper, 3–4 bagels at a time.","Brush with egg, add toppings.","Air fry at 190°C 8–10 min; flip for 2–3 min more if you like."]}],"notes":["Chewier: flip after 10 min and cook 5–6 min more."]},{"id":"soup-dumpling-lasagna","title":"Soup Dumpling Lasagna","lang":"EN","source":"daigasikfaan","url":"https://daigasikfaan.co/viral-soup-dumpling-lasagna/","cat":"Hauptgerichte","cuisine":"Chinesisch","tags":["Noch nie gemacht","Dumplings","Schwein","gedämpft"],"servings":"2 Portionen","prep":"10 Min.","total":"30 Min.","ing":[{"h":"Meat mixture","i":["200 g minced pork (ca. 20% fat)","100 g shrimp, chopped (optional)","2 spring onions, chopped","1 tsp garlic","1/2 tsp ginger","1 tbsp cornflour","1 tbsp oyster sauce","1 tbsp light soy sauce","1/2 tbsp Shaoxing wine","1/2 tbsp sesame oil","1 tsp dark soy sauce","1 tsp chicken stock powder","1/2 tsp sugar","1 pinch white pepper","80 ml water"]},{"h":"Assembly","i":["14 dumpling or wonton wrappers","3 Napa cabbage leaves","1 spring onion","Chilli oil, black vinegar (optional)"]}],"steps":[{"h":"","i":["Mix meat, shrimp, seasonings and water in one direction until sticky.","Trim cabbage leaves to fit the bowl.","Layer: 1.3 cm meat, cabbage, 3 wetted wrappers; repeat; finish with 4 wrappers.","Steam in a bamboo steamer over a wok with 5 cm water, 20 min on high.","Garnish with spring onion, chilli oil and black vinegar."]}],"notes":["Wonton wrappers soften better than frozen dumpling wrappers. Use more layers in a deeper bowl."]},{"id":"apple-cider-donuts","title":"Baked Apple Cider Donuts","lang":"EN","source":"Cooking with Cocktail Rings","url":"https://cookingwithcocktailrings.com/2015-10-11-apple-cider-donuts/","cat":"Backen","cuisine":"Amerikanisch","tags":["Noch nie gemacht","Donuts","gebacken","Zimt","Herbst"],"servings":"12 Donuts","prep":"10 Min.","total":"30 Min.","nutr":"265 kcal pro Donut","ing":[{"h":"","i":["240 ml apple cider (cloudy apple juice/most)","250 g plain flour","150 g dark brown sugar","2 tbsp cinnamon, divided","1 1/2 tsp baking powder","1 tsp coarse salt","1/4 tsp bicarbonate of soda","2 eggs, room temperature","115 g butter, melted (30 g + 85 g)","120 ml buttermilk","200 g sugar","Oil spray"]}],"steps":[{"h":"","i":["Preheat oven to 180°C. Simmer the cider until reduced to 120 ml.","Whisk flour, brown sugar, 1 tbsp cinnamon, bicarbonate, salt and baking powder.","Whisk 30 g melted butter with the eggs, then the reduced cider and buttermilk.","Stir wet into dry until just combined.","Grease the donut tin, fill each hole 3/4 full.","Bake 10 min until a knife comes out clean. Repeat with the rest.","Put 85 g melted butter in one bowl, sugar mixed with 1 tbsp cinnamon in another.","Dip both sides of each donut in butter, then cinnamon sugar."]}],"notes":["Keeps 2 days airtight. A mini muffin tin makes donut holes."]},{"id":"gebrannte-mandeln","title":"Gebrannte Mandeln","lang":"DE","source":"Instagram","cat":"Snacks","cuisine":"Deutsch","tags":["Noch nie gemacht","Mandeln","Weihnachten","Geschenk","schnell"],"servings":"200 g Mandeln","prep":"","total":"ca. 20 Min.","ing":[{"h":"","i":["120 g Zucker","60 g Wasser","1 TL Zimt","1 Päckchen Vanillin(zucker)","200 g naturbelassene Mandeln"]}],"steps":[{"h":"","i":["Zucker, Wasser, Vanillin und Zimt in einer Pfanne aufkochen, bis sich der Zucker aufgelöst hat.","Mandeln dazugeben und unter ständigem Rühren weiterkochen.","Weiterrühren, bis der Zucker weiß und trocken wird und kristallisiert (normal!).","Weiterrühren, bis der Zucker wieder schmilzt und die Mandeln glänzend karamellisiert sind.","Auf Backpapier geben, mit einer Gabel trennen, abkühlen lassen."]}],"notes":["Frisch am besten. Schönes Mitbringsel in der Adventszeit."]},{"id":"crispy-rice-salmon","title":"Crispy Rice with Salmon and Avocado","lang":"EN","source":"Cooking with Cocktail Rings","url":"https://cookingwithcocktailrings.com/crispy-rice-with-salmon-and-avocado/","cat":"Snacks","cuisine":"Japanisch","tags":["Noch nie gemacht","Lachs","Avocado","Sushi-Reis","Party"],"servings":"4 Portionen","prep":"1 Std. + 1 Std. kühlen","total":"ca. 2 Std. 45 Min.","ing":[{"h":"","i":["400 g short-grain sushi rice","530 ml water","2 tsp rice vinegar","1/2 tsp sugar","1/4 tsp coarse salt","240 ml vegetable oil, for frying","1 Hass avocado","1 tbsp lemon juice","225 g sushi-grade salmon, thinly sliced","1 tsp toasted sesame seeds"]}],"steps":[{"h":"","i":["Rinse the rice until the water runs clear, put in a pan with the water.","Bring to a boil, cover, cook on low ca. 20 min.","Sprinkle with vinegar, sugar and salt whisked together, fluff and cool.","Press firmly 1.3 cm thick into a tray (22 x 32 cm) lined with cling film. Chill at least 1 hour.","Cut into 12 squares (or 5 cm circles).","Fry in oil at 190°C, a few at a time: 2 min undisturbed, flip, 2–3 min more.","Mash avocado with lemon juice and salt.","Drain the rice on paper towels, halve the squares if you like.","Top with avocado, salmon and sesame. Serve immediately."]}],"notes":["Press firmly so it holds together. Smoked salmon or tuna also work."]},{"id":"chimichurri-shrimp","title":"Chimichurri Shrimp with Coconut Rice","lang":"EN","source":"Cooking with Cocktail Rings","url":"https://cookingwithcocktailrings.com/chimichurri-shrimp-with-coconut-rice/","cat":"Hauptgerichte","cuisine":"Lateinamerikanisch","tags":["Noch nie gemacht","Garnelen","Kokos","Kräuter","schnell"],"servings":"4 Portionen","prep":"15 Min.","total":"35 Min.","nutr":"514 kcal pro Portion","ing":[{"h":"Coconut rice","i":["190 g jasmine rice, rinsed","1 can coconut milk (400 ml)","1 pinch salt"]},{"h":"Chimichurri shrimp","i":["1 small bunch coriander, finely chopped (ca. 15 g)","1 small bunch flat-leaf parsley, finely chopped (ca. 15 g)","1 small red chilli, seeded and chopped","2 tbsp chopped shallot","110 g olive oil + 2 tbsp","2 tbsp red wine vinegar","1/2 tsp dried oregano","Salt and pepper","450 g large prawns, peeled"]}],"steps":[{"h":"","i":["Bring rice, coconut milk and salt to a boil over medium heat.","Cover and simmer on medium-low ca. 15 min, fluff.","Mix coriander, parsley, chilli, shallot, 110 g oil, vinegar and oregano, salt to taste.","Pat prawns dry, season with salt and pepper.","Fry in 2 tbsp oil in batches, ca. 1 1/2 min per side.","Toss with half the chimichurri.","Serve on the rice with the rest of the chimichurri."]}],"notes":["Chimichurri keeps 3 days in the fridge."]},{"id":"shrimp-ceviche-tostadas","title":"Coconut Shrimp Ceviche Tostadas","lang":"EN","source":"Cooking with Cocktail Rings","url":"https://cookingwithcocktailrings.com/coconut-shrimp-ceviche-tostadas/","cat":"Snacks","cuisine":"Mexikanisch / Thai","tags":["Noch nie gemacht","Garnelen","Kokos","scharf","Party"],"servings":"4 Portionen (8 Tostadas)","prep":"10 Min.","total":"ca. 1 Std.","ing":[{"h":"","i":["Vegetable oil, for frying","8 corn tortillas (ca. 15 cm)","2 shallots, thinly sliced","450 g large prawns, peeled","2 tbsp butter","1 tsp grated ginger","2 Thai bird's eye chillies, diced","180 ml coconut milk","1 tsp fish sauce","1 spring onion, whites and greens separated","1 tsp lime zest"]}],"steps":[{"h":"","i":["Fry the tortillas one at a time in 1.3 cm oil, ca. 1 min per side, drain.","Fry the shallots in the same oil ca. 6 min until crispy, drain.","Poach prawns ca. 3 min in salted water just off the boil, drain, cool.","Melt butter, sauté ginger and chillies 30 sec, stir in coconut milk, take off heat, cool.","Stir in fish sauce and spring onion whites.","Chop prawns, mix in, chill 15–30 min.","Spoon onto the tostadas, top with shallots, spring onion greens and lime zest."]}],"notes":["Assemble just before serving so they stay crisp. Milder: jalapeño."]},{"id":"street-corn-pasta","title":"Mexican Street Corn Pasta Salad","lang":"EN","source":"Cooking with Cocktail Rings","url":"https://cookingwithcocktailrings.com/mexican-street-corn-pasta-salad/","cat":"Salate","cuisine":"Mexikanisch","tags":["Noch nie gemacht","Nudelsalat","Mais","vegetarisch","Grillen"],"servings":"4 Portionen","prep":"15 Min.","total":"25 Min.","ing":[{"h":"","i":["225 g short pasta","110 g mayonnaise","60 g sour cream","1 tsp lime zest","2 tbsp lime juice","1 clove garlic, minced","1 tbsp chilli powder","1/2 tsp cayenne","ca. 230 g charred corn kernels","1 small bunch coriander (ca. 15 g)","2 spring onions","60 g cotija or feta"]}],"steps":[{"h":"","i":["Cook pasta al dente (ca. 8 min), keep 60 ml cooking water, drain.","Whisk mayo, sour cream, lime zest and juice, garlic, chilli powder and cayenne; thin with 30 ml pasta water.","Mix the still-warm pasta with the sauce and corn.","Top with coriander, spring onions and cheese. Serve at room temperature or chilled."]}],"notes":["Charred corn: butter and salt the cobs, grill 15–20 min. Tinned or frozen corn also works."]},{"id":"sticky-toffee-pudding","title":"Sticky Toffee Pudding","lang":"EN","source":"Cooking with Cocktail Rings","url":"https://cookingwithcocktailrings.com/sticky-toffee-pudding-with-mascarpone-cream/","cat":"Desserts","cuisine":"Britisch","tags":["Noch nie gemacht","Datteln","Karamell","Mascarpone","Winter"],"servings":"6 Portionen","prep":"30 Min.","total":"ca. 1 Std. 45 Min.","ing":[{"h":"Toffee sauce","i":["180 ml cream","200 g dark brown sugar","120 ml maple syrup","115 g butter, cubed"]},{"h":"Date cake","i":["55 g butter + extra for ramekins","95 g plain flour + extra","1/2 tsp bicarbonate of soda","120 ml boiling water","1/4 tsp salt","1/2 tsp baking powder","200 g dark brown sugar","1/4 tsp vanilla","1 egg","ca. 130 g Medjool dates, chopped (ca. 9)"]},{"h":"Mascarpone cream","i":["225 g mascarpone","120 ml cream"]}],"steps":[{"h":"","i":["Boil cream, brown sugar and maple syrup, whisking; whisk in the butter piece by piece.","Oven 180°C. Butter and flour 6 ramekins (ca. 180 ml). Pour boiling water and bicarbonate over the dates.","Whisk flour, salt and baking powder.","Beat butter, sugar and vanilla, then the egg; mix in flour, then the dates.","Bake 30–35 min, cool 5 min.","Turn out onto a rack, soak with hot toffee sauce, rest 30 min.","Whip mascarpone, slowly adding the cream.","Serve with more sauce and mascarpone cream."]}],"notes":["Sauce keeps 2 weeks, cakes 2 days. Pan version: 23 x 23 cm, 40–45 min."]},{"id":"pork-chive-dumplings","title":"Pork & Chive Dumplings","lang":"EN","source":"Cooking with Cocktail Rings","url":"https://cookingwithcocktailrings.com/pork-chive-pan-fried-dumplings/","cat":"Hauptgerichte","cuisine":"Chinesisch","tags":["Noch nie gemacht","Dumplings","Schwein","einfrieren"],"servings":"28 Stück","prep":"1 Std. + 30 Min. Ruhe","total":"ca. 2 Std.","ing":[{"h":"Dough","i":["250 g plain flour","240 ml boiling water (ca. 180 ml used)","1/2 tsp salt","Cornflour for dusting"]},{"h":"Filling","i":["450 g minced pork","2 tbsp diced chives","ca. 100 g finely shredded cabbage","1 tbsp grated ginger","1 tbsp rice vinegar","Salt"]},{"h":"To cook and serve","i":["60 ml vegetable oil","Chives, sesame seeds, sesame oil","Chilli crisp","Soy sauce or black vinegar"]}],"steps":[{"h":"","i":["Dissolve salt in the boiling water, stir ca. 180 ml into the sifted flour.","Knead 10 min, halve, wrap, rest 30 min.","Roll into 2.5 cm logs, cut each into 14 pieces.","Roll each thin, cut 9 cm rounds, dust with cornflour, keep covered.","Mix filling, rest 15 min.","Fill with 1 tbsp, pleat and seal.","Fry flat side down in 2 tbsp oil 2–3 min until golden.","Add 120 ml water, cover at once, cook ca. 7 min.","Garnish and serve with chilli crisp and soy sauce."]}],"notes":["Freeze in a single layer, keeps 3 months; cook from frozen 1–2 min longer."]},{"id":"waffeln","title":"Waffeln","lang":"DE","source":"Rezeptwelt","url":"https://www.rezeptwelt.de/backen-suess-rezepte/waffeln/zrieprmi-cf70f-075394-cfcd2-rsqzbspk","cat":"Backen","cuisine":"Deutsch","tags":["Noch nie gemacht","Waffeln","schnell","Frühstück","Kinder","Thermomix"],"servings":"12 Waffeln","prep":"15 Min.","total":"15 Min.","ing":[{"h":"","i":["125 g Butter oder Margarine, in Stücken","100 g Zucker","2 EL Vanillezucker","3 Eier","250 g Milch","250 g Mehl","1 TL Backpulver","Puderzucker zum Bestäuben (optional)"]}],"steps":[{"h":"","i":["Waffeleisen vorheizen.","Alle Zutaten 1 Min. 30 Sek./Stufe 5 verrühren.","Teig portionsweise im heißen Waffeleisen backen.","Nach Belieben mit Puderzucker bestäuben."]}],"notes":["Zitronenabrieb, Nüsse oder Beeren passen in den Teig – erst gegen Ende der Rührzeit zugeben."]},{"id":"ratatouille","title":"Ratatouille","lang":"FR","source":"Cookomix","url":"https://www.cookomix.com/recettes/ratatouille-thermomix/","cat":"Hauptgerichte","cuisine":"Französisch","tags":["Noch nie gemacht","Gemüse","vegan","Sommer","Thermomix"],"servings":"4 portions","prep":"10 min","total":"51 min","ing":[{"h":"","i":["1 oignon jaune, coupé en deux","3 gousses d'ail","20 g d'huile d'olive","1 c. à café d'herbes de Provence","1 feuille de laurier","1 c. à soupe de fond de légumes","300 g de tomates, en quartiers","50 g de poivron rouge","50 g de poivron jaune","50 g de poivron vert","1 c. à café de sel","2 pincées de poivre","200 g de courgette, en morceaux (2–3 cm)","300 g d'aubergine, en morceaux (2–3 cm)"]}],"steps":[{"h":"","i":["Oignon et ail : 5 s, vitesse 5. Racler les parois.","Ajouter huile, herbes de Provence et laurier : 5 min, 100°C, vitesse 1.","Ajouter fond de légumes, tomates et poivrons : 14 min, 100°C, panier de cuisson à la place du gobelet.","Ajouter sel, poivre, courgette et aubergine : 22 min, 100°C.","Servir chaud."]}],"notes":["Couper les légumes en morceaux de 2–3 cm de même taille pour éviter la purée.","Vitesse non indiquée aux étapes 3 et 4 : sens inverse, vitesse mijotage conseillé."]},{"id":"puffy-pita","title":"Puffy Pita with Tzatziki","lang":"EN","source":"Instagram @fitgreenmind","cat":"Backen","cuisine":"Griechisch","tags":["Noch nie gemacht","Brot","Pita","Dip","vegan"],"servings":"6 pitas","prep":"15 min + 1.5–2.5 h rising","total":"ca. 2.5 h","nutr":"217 kcal per pita","ing":[{"h":"Pita","i":["335 g flour (wholegrain also works)","1 tbsp salt","205 ml lukewarm water","1 tbsp instant yeast","1 tbsp sugar","1 tbsp olive oil"]},{"h":"Tzatziki","i":["1/2 cucumber, grated and squeezed","1/2 bunch parsley and dill, chopped","2 cloves garlic, minced","150 g (vegan) yogurt","1 glug olive oil","Juice of 1/2 lemon","Salt and pepper"]}],"steps":[{"h":"","i":["Mix water, sugar and yeast.","Knead in flour, salt and oil to a soft dough.","Rest 1–2 hours.","Shape into 6 discs, rest 30 min.","Bake at 250°C for 4–5 min until puffed.","Tzatziki: mix everything."]}],"notes":["1 tbsp salt is a lot for 335 g flour – maybe start with 1–2 tsp."]},{"id":"street-corn-nicki","title":"Street Corn Pasta Salad (Nicki)","lang":"EN","source":"Instagram @tastewithnicki","cat":"Salate","cuisine":"Mexikanisch","tags":["Noch nie gemacht","Nudelsalat","Mais","Grillen","Sommer","vegetarisch"],"servings":"6 servings","prep":"15 min","total":"30 min + chilling","ing":[{"h":"Pasta salad","i":["ca. 250 g dry macaroni","ca. 285 g frozen corn","ca. 60 g cotija (or parmesan)","ca. 75 g red onion, diced","2 jalapeños, chopped","ca. 15 g coriander, chopped","2 cloves garlic, minced","1 tsp chilli powder","1/4 tsp salt","1/4 tsp pepper","1/4 tsp garlic powder","1/8 tsp cayenne"]},{"h":"Dressing","i":["ca. 220 g mayonnaise","ca. 120 g sour cream (or Greek yogurt)","60 ml lime juice","2 tsp lime zest","1/4 tsp salt","1/4 tsp pepper"]}],"steps":[{"h":"","i":["Cook the macaroni, drain and chill.","Cook the corn, or roast in a pan with garlic powder and Tajín 6–8 min over medium heat.","Mix the dressing and set aside.","Combine pasta, corn and the rest, stir in the dressing, season."]}],"notes":["Caption only lists ingredients; steps derived from it."]},{"id":"cauli-pitta","title":"Spiced Cauliflower Pittas with Hummus","lang":"EN","source":"Instagram @deliciouslyella","cat":"Hauptgerichte","cuisine":"Orientalisch","tags":["Noch nie gemacht","Blumenkohl","Hummus","Mittagessen","schnell","vegan"],"servings":"2 servings","prep":"5 min","total":"25 min","ing":[{"h":"","i":["1 small cauliflower","1/2 tsp ground turmeric","1/2 tsp chilli powder","1 tsp ground cumin","2 wholegrain pittas","2 tbsp hummus","1 large handful rocket","Pomegranate seeds","1 pinch chilli flakes","Olive oil","1 pinch sea salt"]}],"steps":[{"h":"","i":["Preheat the oven to 200°C (fan).","Cut cauliflower into small florets, toss with oil, spices and salt on a tray, roast 15–20 min until cooked but with bite.","Toast the opened pittas, add 1 heaped tbsp hummus each, then cauliflower, rocket, pomegranate and chilli flakes."]}],"notes":[]},{"id":"apple-beignets","title":"Apple Beignets","lang":"EN","source":"Instagram @callherchef","cat":"Desserts","cuisine":"Französisch","tags":["Noch nie gemacht","Äpfel","Zimt","Kinder","schnell","Herbst"],"servings":"4 servings","prep":"10 min","total":"25 min","ing":[{"h":"","i":["3 apples","100 g self-raising flour","1 egg","70 ml milk","30 g butter, for frying","1 tbsp olive oil, for frying"]},{"h":"Cinnamon sugar","i":["2 tsp ground cinnamon","3 tbsp caster sugar"]}],"steps":[{"h":"My suggestion (method only in the video)","i":["Whisk flour, egg and milk into a thick batter.","Core the apples and cut into ca. 1 cm rings.","Heat butter and oil in a pan over medium heat.","Dip apple rings in batter, fry 2–3 min per side until golden.","Toss in cinnamon sugar while warm."]}],"notes":[]},{"id":"french-onion-pasta","title":"One Pot French Onion Pasta","lang":"EN","source":"Instagram @recipeincaption","cat":"Hauptgerichte","cuisine":"Französisch","tags":["Noch nie gemacht","Nudeln","Zwiebeln","Käse","Herbst","Winter"],"servings":"4 servings","prep":"10 min","total":"ca. 1 h","ing":[{"h":"","i":["340 g rigatoni","2 tbsp butter","2 tbsp olive oil","3 large onions, sliced","5 cloves garlic, minced","3 tsp fresh thyme + extra","80 ml white wine","1 tsp Worcestershire sauce","1 tsp salt","1 tsp black pepper","720 ml beef stock","240 ml water","80 ml cream","ca. 150 g gruyère, grated (100 g + 50 g)"]}],"steps":[{"h":"","i":["Heat butter and oil in an ovenproof pan, add onions, stir to coat. Switch on the oven grill.","Caramelize the onions low and slow until golden, stirring often; add a splash of water if they catch.","Add garlic and thyme, fry until fragrant.","Deglaze with wine, scraping the bottom, 1–2 min.","Add stock, water, Worcestershire, salt, pepper and pasta; boil, then simmer 6–8 min until al dente.","Off the heat, stir in cream and 100 g cheese.","Top with 50 g cheese, grill ca. 2 min.","Sprinkle with thyme and serve."]}],"notes":["Worcestershire, salt and pepper added with the stock (caption doesn't say when)."]},{"id":"white-lasagna","title":"White Lasagna with Greens & Mushrooms","lang":"EN","source":"Instagram @sara.haven","cat":"Hauptgerichte","cuisine":"Italienisch","tags":["Noch nie gemacht","Lasagne","Hähnchen","Spinat","Pilze","High Protein"],"servings":"6–9 servings","prep":"20 min","total":"ca. 50 min","nutr":"266 kcal per serving","ing":[{"h":"","i":["480 ml whole milk","2 tbsp olive oil","ca. 110 g onion, chopped","3 tbsp minced garlic","ca. 80 g mushrooms, sliced","1 tsp dried basil","1 tsp dried oregano","1/2 tsp chilli flakes","1 1/4 tsp sea salt (1/4 + 1)","170 g fresh spinach","ca. 280 g shredded cooked chicken","480 ml chicken or veg stock (120 + 360 ml)","ca. 30 g flour","1/4 tsp nutmeg","ca. 50 g grated parmesan","170 g no-boil lasagna sheets, broken","ca. 125 g gruyère or mozzarella"]}],"steps":[{"h":"","i":["Preheat the oven to 190°C.","Sauté onion, garlic, mushrooms, herbs, chilli and 1/4 tsp salt in oil 3–4 min.","Add spinach until wilted, take off heat, stir in chicken.","Whisk 120 ml stock with flour. Heat 360 ml stock, milk, nutmeg and 1 tsp salt; once bubbling whisk in the slurry, simmer 6 min, stir in parmesan.","In a cast-iron pan: 120 ml sauce, then 1/3 noodles, 1/3 chicken mix, 240 ml sauce, cheese; repeat 3 times.","Cover with foil, bake 20–25 min until bubbling."]}],"notes":["Take the foil off for the last 5 min for a golden top."]},{"id":"focaccia","title":"Overnight Focaccia","lang":"EN","source":"Alexandra's Kitchen","url":"https://alexandracooks.com/2018/03/02/overnight-refrigerator-focaccia-best-focaccia/","cat":"Backen","cuisine":"Italienisch","tags":["Noch nie gemacht","Brot","ohne Kneten","vorbereiten","Party","vegan"],"servings":"2 round loaves","prep":"15 min + 12 h fridge + 3–4 h","total":"ca. 17 h","ing":[{"h":"","i":["512 g plain or bread flour","10–15 g coarse salt","8 g instant yeast","455 g lukewarm water","Butter, for greasing","4 tbsp olive oil, divided","Flaky sea salt","1–2 tsp rosemary (optional)"]}],"steps":[{"h":"","i":["Whisk flour, salt and yeast, add water, mix to a sticky ball. Rest 30 min (optional: 8–10 stretch-and-folds).","Oil the surface, cover, refrigerate at least 12 h (up to 3 days).","Line or grease two 20–23 cm round tins (or one 23 x 33 cm).","1 tbsp oil per round tin. Deflate dough with forks, halve, roll in oil, place in tins. Rest uncovered 3–4 h.","Preheat to 220°C. Oil the top, dimple deeply with oiled fingers, sprinkle with flaky salt and rosemary.","Bake 25–30 min until golden underneath. Cool 10 min."]}],"notes":["Short on time: rise 1.5–2 h at room temperature, then 30–60 min.","Reheat at 175°C for 15 min."]},{"id":"linsen-moussaka","title":"Linsen-Moussaka","lang":"DE","source":"Rezeptwelt","url":"https://www.rezeptwelt.de/hauptgerichte-mit-gemuese-rezepte/linsen-moussaka/v4sj19y7-e2d56-421089-cfcd2-mwq1rcc6","cat":"Hauptgerichte","cuisine":"Griechisch","tags":["Noch nie gemacht","Linsen","Aubergine","Auflauf","Varoma","Thermomix","vegetarisch"],"servings":"6 Portionen","prep":"25 Min. + 1 Std. einweichen","total":"ca. 1 Std. 15 Min.","ing":[{"h":"Moussaka","i":["200 g rote Linsen","500 g Wasser (zum Einweichen)","120 g Parmesan, in Stücken","2 Auberginen (ca. 400 g)","50 g Olivenöl","1 Zwiebel, geviertelt (200 g)","3 Knoblauchzehen","1 Paprika, in Stücken (150 g)","400 g geschälte Tomaten (Dose)","120 g Rotwein","1 EL Oregano","1 TL gemahlener Ingwer","2 TL Salz","1/2 TL Pfeffer"]},{"h":"Béchamel","i":["40 g Butter + etwas zum Einfetten","500 g Milch","40 g Mehl"]}],"steps":[{"h":"","i":["Linsen 1 Std. einweichen, abgießen.","Parmesan 10 Sek./Stufe 10, umfüllen.","Auberginen längs in 1-cm-Scheiben in den Varoma legen.","Öl, Zwiebel, Knoblauch, Paprika 5 Sek./Stufe 5.","Tomaten dazu, 2 Sek./Stufe 5.","Wein, Oregano, Ingwer, Salz, Pfeffer dazu, Varoma aufsetzen, 20 Min./Varoma/Linkslauf/Stufe 1. Varoma beiseite.","Linsen dazu, 5 Min./100°C/Linkslauf/Stufe 2. Form fetten, Auberginen einschichten, Linsenmasse darauf.","Butter, Milch, Mehl 8 Min./90°C/Stufe 4.","60 g Parmesan dazu, 5 Sek./Stufe 4. Über die Linsen gießen, restlichen Parmesan darauf, 30 Min. bei 200°C backen."]}],"notes":["Rote Linsen müssen nicht eingeweicht werden – dann je ca. 5 Min. länger garen und backen.","Béchamel mit Muskat abschmecken."]},{"id":"fitness-vollkornbrot","title":"Fitness-Vollkornbrot","lang":"DE","source":"Rezeptwelt","url":"https://www.rezeptwelt.de/brot-broetchen-rezepte/fitness-vollkornbrot-super-saftig-saulecker/as6glndn-7eaad-342598-cfcd2-jgyl950m","cat":"Backen","cuisine":"Deutsch","tags":["Noch nie gemacht","Brot","Vollkorn","Karotten","Thermomix"],"servings":"1 Kastenbrot","prep":"5 Min.","total":"ca. 1 Std. 5 Min.","ing":[{"h":"","i":["300 g Dinkelkörner","150 g Weizenkörner","150 g Roggenkörner","200 g Karotten, in 3-cm-Stücken","500 g Buttermilch, zimmerwarm","1 Würfel Hefe (40 g)","2 gestr. TL Salz","2 EL weißer Balsamico","50 g Wasser","100 g Sonnenblumenkerne","50 g Leinsamen, geschrotet","Haferflocken nach Belieben"]}],"steps":[{"h":"","i":["Kastenform fetten, mit Haferflocken ausstreuen. Ofen 220°C. Der Teig muss nicht gehen.","Dinkel 1 Min./Stufe 10 mahlen, umfüllen.","Weizen und Roggen 1 Min./Stufe 10 mahlen, umfüllen.","Karotten 4 Sek./Stufe 5.","Buttermilch und Hefe 3 Min./37°C/Stufe 2.","Übrige Zutaten außer Haferflocken dazu, 4 Min./Teigknetstufe.","In die Form streichen, mit Wasser bestreichen, Haferflocken darauf.","30 Min. bei 220°C, dann 20–30 Min. bei 180°C backen. Stäbchenprobe.","Nach 5 Min. aus der Form lösen, ganz auskühlen lassen."]}],"notes":["Nach 15 Min. längs 1 cm tief einschneiden.","Bleibt innen teigig, wenn zu kurz gebacken – lieber länger."]},{"id":"joghurtbroetchen","title":"Schnelle Joghurtbrötchen","lang":"DE","source":"Rezeptwelt","url":"https://www.rezeptwelt.de/brot-broetchen-rezepte/schnelle-joghurtbroetchen/c3wwfc11-9c7b4-426187-cfcd2-pie1sx5m","cat":"Backen","cuisine":"Deutsch","tags":["Noch nie gemacht","Brötchen","schnell","Frühstück","Thermomix"],"servings":"10–12 Brötchen","prep":"10 Min.","total":"40 Min.","ing":[{"h":"","i":["150 g Milch","150 g Wasser","1 Würfel frische Hefe","150 g Joghurt","600 g Weizenmehl","1 1/2 TL Salz","1 Prise Zucker","Etwas Mehl zum Bestäuben"]}],"steps":[{"h":"","i":["Milch, Wasser, Hefe 2 Min./37°C/Stufe 2.","Joghurt, Mehl, Salz, Zucker dazu, 3 Min./Teigknetstufe.","Mit nassem Esslöffel 10–12 Portionen abstechen, aufs Blech setzen.","Mit Mehl bestäuben, in den kalten Ofen, 240°C O/U ca. 25–30 Min. backen."]}],"notes":["Zu klebrig: etwas mehr Mehl oder weniger Wasser.","Länger gehen lassen (z. B. über Nacht im Kühlschrank) gibt lockerere Brötchen."]}];
const TR={"de":{"moules-marinieres":{"title":"Moules marinières","servings":"2 Portionen","prep":"10 Min.","total":"36 Min.","ing":[["",["2 Schalotten","1 Knoblauchzehe","20 g Butter","220 g trockener Weißwein","1 TL Zitronensaft","50 g Wasser","1 Prise Salz","1 Prise Pfeffer","1500 g frische Miesmuscheln","100 g Crème fraîche","15 g Speisestärke","6 Halme Schnittlauch, in Röllchen"]]],"steps":[["",["Schalotten und Knoblauch 5 Sek./Stufe 5.","Butter dazu, 3 Min./100°C.","Weißwein, Zitronensaft, Wasser, Salz und Pfeffer dazugeben.","Varoma mit den Muscheln aufsetzen, 20 Min./Varoma. Varoma abnehmen.","Crème fraîche und Stärke dazu, 10 Sek./Stufe 6.","Schnittlauch dazu, 3 Min./90°C/Stufe 2.","Muscheln in eine Schüssel geben, Soße darüber, heiß servieren."]]],"notes":["Muscheln zwischendurch umrühren, damit sie gleichmäßig garen.","Aus den Kommentaren: etwas in die Mitte des Varoma stellen, damit der Dampf besser zirkuliert; Petersilie statt Schnittlauch; weniger oder keine Sahne geht auch. Klassisch mit Pommes."]},"ratatouille":{"title":"Ratatouille","servings":"4 Portionen","prep":"10 Min.","total":"51 Min.","ing":[["",["1 gelbe Zwiebel, halbiert","3 Knoblauchzehen","20 g Olivenöl","1 TL Kräuter der Provence","1 Lorbeerblatt","1 EL Gemüsebrühe-Paste","300 g Tomaten, geviertelt","50 g rote Paprika","50 g gelbe Paprika","50 g grüne Paprika","1 TL Salz","2 Prisen Pfeffer","200 g Zucchini, in 2–3-cm-Stücken","300 g Aubergine, in 2–3-cm-Stücken"]]],"steps":[["",["Zwiebel und Knoblauch 5 Sek./Stufe 5, nach unten schieben.","Öl, Kräuter und Lorbeer dazu, 5 Min./100°C/Stufe 1.","Brühe, Tomaten und Paprika dazu, 14 Min./100°C, Gareinsatz statt Messbecher.","Salz, Pfeffer, Zucchini und Aubergine dazu, 22 Min./100°C.","Heiß servieren."]]],"notes":["Gemüse in gleich große 2–3-cm-Stücke schneiden, damit es nicht zu Brei wird.","Für Schritt 3 und 4 ist keine Stufe angegeben: Linkslauf/Sanftrührstufe empfohlen."]},"orange-chicken":{"title":"Knuspriges Orangen-Hähnchen mit Gemüse-Bratreis","servings":"4 Portionen","prep":"","total":"","ing":[["",["4 große Eiweiß","2 EL Speisestärke","450 g Hähnchenschenkel, in 2,5-cm-Stücken","2 EL Pflanzenöl + Öl zum Frittieren","300 g TK-Mischgemüse, aufgetaut","ca. 650 g gekochter Reis (ca. 220 g roh)","2 3/4 TL Knoblauchpulver, aufgeteilt","1 1/2 TL grobes Salz, aufgeteilt","160 g Orangenmarmelade","60 ml Hühnerbrühe","1 EL Worcestersauce","1/2 TL gemahlener Ingwer","Frühlingszwiebel zum Garnieren"]]],"steps":[["",["Eiweiß und Stärke verquirlen, Hähnchen unterrühren, 15 Min. ziehen lassen.","Gemüse in 2 EL Öl 2–4 Min. braten. Reis, 2 TL Knoblauchpulver und 1 TL Salz dazu, 2–3 Min. pfannenrühren. Warm halten.","5 cm Öl auf 185°C erhitzen.","Hähnchen portionsweise 2–3 Min. goldbraun frittieren, abtropfen lassen. Nochmal 1 Min. frittieren.","Marmelade, Brühe, Worcester, Ingwer, restliches Knoblauchpulver und Salz aufkochen, ca. 5 Min. einkochen. Hähnchen darin schwenken, mit dem Reis servieren."]]],"notes":[]},"turkey-fajita":{"title":"Puten-Fajita-Auflauf","servings":"4 Portionen","prep":"","total":"20–25 Min. Backzeit","ing":[["",["450 g Putenschnitzel, in Streifen","1 rote Paprika, in Streifen","1 gelbe Paprika, in Streifen","1/2 rote Zwiebel, in dünnen Ringen","100 g geriebener Cheddar","1 Päckchen Taco-Gewürz (ca. 35 g)","2 Frühlingszwiebeln, gehackt","1 Packung mexikanische Reismischung (ca. 190 g)","1 Dose gehackte Tomaten (400 g)"]]],"steps":[["",["Ofen auf 190°C vorheizen, Form (ca. 23 x 23 cm) fetten.","Pute, Paprika, Zwiebel, Käse und Taco-Gewürz mischen, in der Form verteilen.","20–25 Min. backen, bis die Pute durchgegart ist.","Reis mit den Tomaten nach Packung zubereiten. Zusammen servieren, mit Frühlingszwiebeln garnieren."]]],"notes":[]},"tex-mex-potato-salad":{"title":"Tex-Mex-Kartoffelsalat","servings":"12 Portionen","prep":"20 Min.","total":"40 Min. + kühlen","ing":[["",["2 Maiskolben","1 große rote Paprika","900 g kleine rote Kartoffeln","1 Avocado, gewürfelt","150 g Kirschtomaten, halbiert","2 Frühlingszwiebeln, in 1-cm-Ringen","60 g leichte saure Sahne oder griech. Joghurt","60 g leichte Mayonnaise","60 g Salsa","2 EL Limettensaft","1 EL Rotweinessig","2 TL gehackte eingelegte Jalapeños","1/2 TL Salz","je 1/4 TL Knoblauchpulver, Zwiebelpulver, Kreuzkümmel, Pfeffer","1 Prise Cayenne","Frischer Koriander"]]],"steps":[["",["Mais und Paprika bei 200°C 20–25 Min. rösten, einmal wenden. Paprika häuten, in 1-cm-Stücke schneiden, Mais vom Kolben schneiden.","Kartoffeln 10–12 Min. weich kochen, abkühlen, halbieren. Paprika, Mais, Avocado, Tomaten, Frühlingszwiebeln dazu.","Saure Sahne, Mayo, Salsa, Limette, Essig, Jalapeños und Gewürze pürieren, untermischen, kalt stellen. Mit Koriander servieren."]]],"notes":["Optional: eine Dose schwarze Bohnen für mehr Eiweiß."]},"chicken-gyros":{"title":"Hähnchen-Gyros","servings":"2 Portionen","prep":"20 Min. + 1 Std. marinieren","total":"30 Min.","ing":[["",["60 ml Zitronensaft","2 EL Olivenöl","3/4 TL gehackter Knoblauch, aufgeteilt","1/2 TL Senfpulver","1/2 TL getrockneter Oregano","225 g Hähnchenbrust, in 1-cm-Streifen","70 g Gurke, geschält und gewürfelt","80 g Naturjoghurt","1/4 TL getrockneter Dill","2 Pita-Brote","1/2 kleine rote Zwiebel, in Ringen"]]],"steps":[["",["Zitronensaft, Öl, 1/2 TL Knoblauch, Senf und Oregano in einem Beutel mischen, Hähnchen dazu, mind. 1 Std. kühl marinieren. Gurke, Joghurt, Dill und restlichen Knoblauch mischen, kalt stellen.","Hähnchen abtropfen lassen, 7–8 Min. durchbraten. In die Pitas füllen, Joghurtsoße und Zwiebel darauf, zusammenklappen."]]],"notes":["Salat und gewürfelte Tomate passen gut dazu."]},"pad-kra-pao":{"title":"Pad Kra Pao (Thai-Basilikum-Schwein)","servings":"2 Portionen","prep":"5 Min.","total":"15 Min.","ing":[["",["1–3 Thai-Chilis, in Ringen","6 Knoblauchzehen, gehackt","2 Schalotten, gehackt","3 EL Pflanzenöl","450 g Schweinehack","ca. 30 g Thai-Basilikum (oder normales Basilikum)"]],["Soße",["1 EL Austernsoße","1 EL Fischsoße","2 TL Sojasoße (Golden Mountain)","1 TL dunkle Sojasoße","1 EL Zucker","80 ml Hühnerbrühe"]],["Dazu",["Spiegelei","Gedämpfter Reis"]]],"steps":[["",["Austern-, Fisch-, Soja- und dunkle Sojasoße mit dem Zucker verrühren.","Schalotten, Knoblauch und Chilis im Öl bei mittlerer bis hoher Hitze ca. 45 Sek. anbraten.","Starke Hitze: Hack dazu, zerkleinern, anbraten und 4–5 Min. braten, bis es leicht gebräunt und trocken ist.","Soße dazu, mit der Brühe ablöschen, ca. 1 Min. einkochen.","Basilikum unterschwenken, bis es gerade zusammenfällt.","Mit Spiegelei und Reis servieren."]]],"notes":["Weniger scharf: weniger Chilis, Kerne entfernen. Geht auch mit Rind, Hähnchen, Pute oder Tofu."]},"chocolate-chip-muffins":{"title":"Schokoladen-Muffins","servings":"12 Muffins","prep":"10 Min. + 15 Min. Ruhe","total":"ca. 50 Min.","ing":[["",["480 g Weizenmehl (405)","300 g Zucker","4 TL Backpulver","1 TL Salz","1/4 TL Muskat (oder Zimt)","4 Eier","240 ml Vollmilch (oder Buttermilch)","100 g Pflanzenöl","57 g Butter, geschmolzen und abgekühlt","2 TL Vanilleextrakt","340 g Schokotropfen (255 g Teig + 85 g Deko)","Grober Zucker"]]],"steps":[["",["Mehl, Zucker, Backpulver, Salz und Muskat mischen.","Eier, Milch, Öl, Butter und Vanille verrühren.","Trockene Zutaten und 255 g Schokotropfen nur kurz unterheben.","Abgedeckt 15 Min. ruhen lassen. Ofen auf 220°C (O/U, kein Umluft) vorheizen.","Nur jede zweite Mulde gut füllen (ca. 120 ml). Schokotropfen und Zucker darauf.","7 Min. bei 220°C, dann 12–16 Min. bei 175°C backen. Rest genauso, Ofen vorher wieder auf 220°C."]]],"notes":["Die Ruhezeit und die hohe Anfangshitze geben die hohen Hauben. Warm am besten."]},"cinnamon-rolls":{"title":"Zimtschnecken (Cinnamon Rolls)","servings":"12 Stück","prep":"30 Min. + 2 Std. gehen","total":"ca. 3 Std. 15 Min.","ing":[["Teig",["585 g Weizenmehl mit hohem Eiweiß (Jumbo Patent Bloem extra fijn)","70 g Zucker","7 g Trockenhefe","1 TL Salz","360 ml Milch","85 g ungesalzene Butter","1 Ei, zimmerwarm"]],["Füllung",["115 g weiche Butter","140 g heller brauner Zucker (Van Gilse lichte basterdsuiker)","2 EL Zimt","1 Prise Salz"]],["Zum Backen",["120 ml Schlagsahne 35 %, erwärmt"]],["Frosting",["115 g Frischkäse (Philadelphia)","115 g weiche Butter","335 g Puderzucker","30 ml Milch","1 TL Vanille","1 Prise Salz"]]],"steps":[["",["Küchenmaschine mit Schneebesen: ca. 250 g Mehl mit Zucker, Hefe und Salz mischen.","Milch und Butter erwärmen, bis die Butter fast geschmolzen ist (nicht heiß).","Mit dem Ei zum Mehl, langsam mischen, dann 2 Min. auf hoher Stufe schlagen (flüssig ist normal).","Knethaken: ca. 200 g Mehl dazu, kneten, dann den Rest (insgesamt 585 g).","Ca. 10 Min. auf mittlerer Stufe kneten, bis der Teig glatt und elastisch ist.","In einer geölten Schüssel abgedeckt ca. 1 Std. gehen lassen.","Butter, braunen Zucker, Zimt und Salz zu einer Paste verrühren.","Teig auf ca. 30 x 45 cm ausrollen, Füllung bis zum Rand streichen.","Von der Längsseite fest aufrollen, in 12 Stücke schneiden, in eine ausgelegte Form (ca. 23 x 33 cm) setzen, ca. 1 Std. gehen lassen.","Ofen 175°C. Direkt vor dem Backen die warme Sahne über die Schnecken gießen.","Ca. 30 Min. goldbraun backen, 15 Min. abkühlen.","Frosting-Zutaten fluffig schlagen, auf die warmen Schnecken streichen."]]],"notes":["Kürzer gebacken bleiben sie weicher. Die zweite Gehzeit kann über Nacht im Kühlschrank sein."]},"california-onigiri":{"title":"California Onigiri","servings":"12 Onigiri","prep":"","total":"ca. 45 Min.","ing":[["Reis",["450 g Sushi-Reis (Rundkorn)","560 ml Wasser","110 g Tobiko (Fliegenfischrogen)"]],["Füllung",["5 Surimi-Sticks","2 EL Kewpie-Mayonnaise","1/2 Avocado","1/2 Gurke"]],["Zum Einwickeln",["6 Noriblätter"]]],"steps":[["",["Reis waschen, bis das Wasser klar ist. Im Reiskocher garen, oder mit dem Wasser aufkochen und zugedeckt auf kleinster Stufe 12–15 Min. quellen lassen. Etwas abkühlen.","Surimi zerzupfen, mit Mayo mischen. Avocado und entkernte Gurke würfeln (0,5–0,7 cm).","Tobiko unter den Reis mischen. Form (oder Hände) zwischendurch anfeuchten.","Ca. 60 ml Reis mit einer Mulde in die Form drücken, 1 EL Surimi und je 1 TL Gurke und Avocado hinein, mit ca. 60 ml Reis bedecken, fest andrücken.","Jedes Onigiri in ein halbes Noriblatt wickeln (getrennt aufbewahren, damit es knusprig bleibt)."]]],"notes":["Scharfe Variante: Sriracha oder Chiliöl in die Surimi-Mischung."]},"apple-fritters":{"title":"Apfel-Fritters","servings":"12 Stück","prep":"20 Min. + 1,5–2,5 Std. gehen","total":"ca. 2 Std. 20 Min.","ing":[["Teig",["240 ml Vollmilch, warm (ca. 43°C)","50 g Zucker","7 g Trockenhefe","80 ml Olivenöl","1 Ei","1 TL Vanille","1/2 TL Salz","ca. 375 g Mehl + mehr"]],["Apfelfüllung",["ca. 750 g Äpfel, fein gewürfelt","200 g brauner Zucker","2 TL Zimt","1/2 TL Muskat","4 TL Speisestärke","2 EL Wasser","1 1/2 TL Vanille"]],["Glasur",["360 g Puderzucker","120 ml Vollmilch","1 TL Vanillepaste"]],["",["Frittieröl"]]],"steps":[["",["Knethaken: Milch, Zucker und Hefe 3–5 Min. schäumen lassen.","Öl, Ei, Vanille, Salz, dann Mehl dazu, 4–5 Min. kneten. Abgedeckt 1–2 Std. gehen lassen.","Äpfel, braunen Zucker und Gewürze ca. 5 Min. köcheln, dann zugedeckt 10 Min. auf kleiner Stufe.","Vom Herd nehmen, Vanille und in Wasser angerührte Stärke einrühren. Abkühlen.","Teig 1,3 cm dick ausrollen, Füllung auf eine Hälfte, zuklappen, andrücken.","In 2,5-cm-Quadrate schneiden, stapeln, Portionen à ca. 80 ml zu Fritters formen.","Auf bemehlte Backpapier-Quadrate setzen, abdecken, 30–45 Min. gehen lassen.","8–10 cm Öl auf 175–185°C erhitzen. Portionsweise 1–3 Min. pro Seite frittieren, auf einem Gitter abtropfen.","Glasur verrühren, Oberseite eintauchen, 5–10 Min. fest werden lassen. Warm servieren."]]],"notes":["Innen teigig = Öl zu heiß oder Fritters zu groß. Im Airfryer bei 150°C aufwärmen."]},"air-fryer-bagels":{"title":"Airfryer-Bagels","servings":"6 Bagels","prep":"5 Min.","total":"15 Min.","ing":[["",["250 g Weizenmehl + bis zu 30 g","1 EL Backpulver","1 TL feines Meersalz","480 g griechischer Joghurt","1 Ei, verquirlt","Toppings (Everything-Gewürz, Mohn, Jalapeño und Cheddar)"]]],"steps":[["",["Mehl, Backpulver und Salz mischen, Joghurt dazu, zu einem groben Teig mischen.","Glatt kneten, bei Bedarf Mehl zugeben.","In 6 Stücke teilen, zu 13–15 cm langen Rollen formen, zu Ringen zusammendrücken.","Airfryer-Korb mit Backpapier auslegen, 3–4 Bagels pro Durchgang.","Mit Ei bestreichen, Toppings darauf.","Bei 190°C 8–10 Min. backen; nach Wunsch wenden und 2–3 Min. weiter."]]],"notes":["Zäher wie in New York: nach 10 Min. wenden und 5–6 Min. weiterbacken."]},"soup-dumpling-lasagna":{"title":"Suppen-Dumpling-Lasagne","servings":"2 Portionen","prep":"10 Min.","total":"30 Min.","ing":[["Fleischmischung",["200 g Schweinehack (ca. 20 % Fett)","100 g Garnelen, gehackt (optional)","2 Frühlingszwiebeln, gehackt","1 TL Knoblauch","1/2 TL Ingwer","1 EL Speisestärke","1 EL Austernsoße","1 EL helle Sojasoße","1/2 EL Shaoxing-Wein","1/2 EL Sesamöl","1 TL dunkle Sojasoße","1 TL Hühnerbrühe-Pulver","1/2 TL Zucker","1 Prise weißer Pfeffer","80 ml Wasser"]],["Schichten",["14 Dumpling- oder Wonton-Blätter","3 Chinakohlblätter","1 Frühlingszwiebel","Chiliöl, schwarzer Essig (optional)"]]],"steps":[["",["Fleisch, Garnelen, Gewürze und Wasser in eine Richtung rühren, bis es klebrig ist.","Chinakohl passend zur Schüssel zuschneiden.","Schichten: 1,3 cm Fleisch, Kohl, 3 angefeuchtete Teigblätter; wiederholen; mit 4 Blättern abschließen.","Im Bambuskorb über einem Wok mit 5 cm Wasser 20 Min. bei starker Hitze dämpfen.","Mit Frühlingszwiebel, Chiliöl und schwarzem Essig garnieren."]]],"notes":["Wonton-Blätter werden weicher als TK-Dumplingblätter. In einer tieferen Schüssel mehr Schichten machen."]},"apple-cider-donuts":{"title":"Gebackene Apfelmost-Donuts","servings":"12 Donuts","prep":"10 Min.","total":"30 Min.","nutr":"265 kcal pro Donut","ing":[["",["240 ml Apfelmost (naturtrüber Apfelsaft)","250 g Weizenmehl","150 g dunkler brauner Zucker","2 EL Zimt, aufgeteilt","1 1/2 TL Backpulver","1 TL grobes Salz","1/4 TL Natron","2 Eier, zimmerwarm","115 g Butter, geschmolzen (30 g + 85 g)","120 ml Buttermilch","200 g Zucker","Backtrennspray"]]],"steps":[["",["Ofen 180°C. Most auf 120 ml einkochen.","Mehl, braunen Zucker, 1 EL Zimt, Natron, Salz und Backpulver mischen.","30 g Butter mit den Eiern verquirlen, dann eingekochten Most und Buttermilch.","Flüssiges kurz unter das Trockene rühren.","Donutform fetten, jede Mulde zu 3/4 füllen.","10 Min. backen (Stäbchenprobe). Rest genauso.","85 g Butter in eine Schale, Zucker mit 1 EL Zimt in eine zweite.","Donuts beidseitig in Butter, dann in Zimtzucker tauchen."]]],"notes":["Luftdicht 2 Tage haltbar. Mit einer Mini-Muffinform werden es Donut-Bällchen."]},"crispy-rice-salmon":{"title":"Knuspriger Reis mit Lachs und Avocado","servings":"4 Portionen","prep":"1 Std. + 1 Std. kühlen","total":"ca. 2 Std. 45 Min.","ing":[["",["400 g Sushi-Reis","530 ml Wasser","2 TL Reisessig","1/2 TL Zucker","1/4 TL grobes Salz","240 ml Pflanzenöl zum Frittieren","1 Hass-Avocado","1 EL Zitronensaft","225 g Lachs in Sushi-Qualität, dünn geschnitten","1 TL geröstete Sesamsamen"]]],"steps":[["",["Reis waschen, bis das Wasser klar ist, mit dem Wasser in einen Topf.","Aufkochen, zudecken, ca. 20 Min. auf kleiner Stufe garen.","Essig, Zucker und Salz verrühren, darüberträufeln, auflockern, abkühlen.","1,3 cm dick fest in eine mit Folie ausgelegte Form (22 x 32 cm) drücken. Mind. 1 Std. kühlen.","In 12 Quadrate (oder 5-cm-Kreise) schneiden.","Portionsweise bei 190°C frittieren: 2 Min. ohne Wenden, dann 2–3 Min. von der anderen Seite.","Avocado mit Zitronensaft und Salz zerdrücken.","Reis auf Küchenpapier abtropfen, Quadrate nach Wunsch halbieren.","Mit Avocado, Lachs und Sesam belegen. Sofort servieren."]]],"notes":["Fest andrücken, damit er zusammenhält. Räucherlachs oder Thunfisch gehen auch."]},"chimichurri-shrimp":{"title":"Chimichurri-Garnelen mit Kokosreis","servings":"4 Portionen","prep":"15 Min.","total":"35 Min.","nutr":"514 kcal pro Portion","ing":[["Kokosreis",["190 g Jasminreis, gewaschen","1 Dose Kokosmilch (400 ml)","1 Prise Salz"]],["Chimichurri-Garnelen",["1 kleiner Bund Koriander, fein gehackt (ca. 15 g)","1 kleiner Bund glatte Petersilie, fein gehackt (ca. 15 g)","1 kleine rote Chili, entkernt, gehackt","2 EL gehackte Schalotte","110 g Olivenöl + 2 EL","2 EL Rotweinessig","1/2 TL getrockneter Oregano","Salz und Pfeffer","450 g große Garnelen, geschält"]]],"steps":[["",["Reis, Kokosmilch und Salz bei mittlerer Hitze aufkochen.","Zudecken, ca. 15 Min. bei mittlerer bis kleiner Hitze köcheln, auflockern.","Koriander, Petersilie, Chili, Schalotte, 110 g Öl, Essig und Oregano mischen, salzen.","Garnelen trocken tupfen, salzen und pfeffern.","Portionsweise in 2 EL Öl ca. 1 1/2 Min. pro Seite braten.","Mit der Hälfte der Chimichurri mischen.","Auf dem Reis mit der restlichen Chimichurri servieren."]]],"notes":["Chimichurri hält 3 Tage im Kühlschrank."]},"shrimp-ceviche-tostadas":{"title":"Kokos-Garnelen-Ceviche-Tostadas","servings":"4 Portionen (8 Tostadas)","prep":"10 Min.","total":"ca. 1 Std.","ing":[["",["Pflanzenöl zum Frittieren","8 Maistortillas (ca. 15 cm)","2 Schalotten, in dünnen Ringen","450 g große Garnelen, geschält","2 EL Butter","1 TL geriebener Ingwer","2 Thai-Chilis, gewürfelt","180 ml Kokosmilch","1 TL Fischsoße","1 Frühlingszwiebel, Weißes und Grünes getrennt","1 TL Limettenabrieb"]]],"steps":[["",["Tortillas einzeln in 1,3 cm Öl je ca. 1 Min. pro Seite knusprig frittieren, abtropfen.","Schalotten im selben Öl ca. 6 Min. knusprig braten, abtropfen.","Garnelen ca. 3 Min. in gerade nicht mehr kochendem Salzwasser garen, abgießen, abkühlen.","Butter schmelzen, Ingwer und Chilis 30 Sek. anschwitzen, Kokosmilch einrühren, vom Herd nehmen, abkühlen.","Fischsoße und das Weiße der Frühlingszwiebel einrühren.","Garnelen hacken, untermischen, 15–30 Min. kühlen.","Auf die Tostadas geben, mit Schalotten, Frühlingszwiebelgrün und Limettenabrieb toppen."]]],"notes":["Erst kurz vor dem Servieren belegen, damit sie knusprig bleiben. Milder: Jalapeño."]},"street-corn-pasta":{"title":"Mexikanischer Mais-Nudelsalat (Esquites)","servings":"4 Portionen","prep":"15 Min.","total":"25 Min.","ing":[["",["225 g kurze Nudeln","110 g Mayonnaise","60 g saure Sahne","1 TL Limettenabrieb","2 EL Limettensaft","1 Knoblauchzehe, gehackt","1 EL Chilipulver","1/2 TL Cayenne","ca. 230 g gegrillte Maiskörner","1 kleiner Bund Koriander (ca. 15 g)","2 Frühlingszwiebeln","60 g Cotija oder Feta"]]],"steps":[["",["Nudeln al dente kochen (ca. 8 Min.), 60 ml Kochwasser aufheben, abgießen.","Mayo, saure Sahne, Limettenabrieb und -saft, Knoblauch, Chili und Cayenne verrühren; mit 30 ml Nudelwasser verdünnen.","Noch warme Nudeln mit Soße und Mais mischen.","Mit Koriander, Frühlingszwiebeln und Käse toppen. Zimmerwarm oder kalt servieren."]]],"notes":["Gegrillter Mais: Kolben mit Butter und Salz 15–20 Min. grillen. Dosen- oder TK-Mais geht auch."]},"sticky-toffee-pudding":{"title":"Sticky Toffee Pudding","servings":"6 Portionen","prep":"30 Min.","total":"ca. 1 Std. 45 Min.","ing":[["Toffeesoße",["180 ml Sahne","200 g dunkler brauner Zucker","120 ml Ahornsirup","115 g Butter, gewürfelt"]],["Dattelkuchen",["55 g Butter + etwas für die Förmchen","95 g Mehl + etwas","1/2 TL Natron","120 ml kochendes Wasser","1/4 TL Salz","1/2 TL Backpulver","200 g dunkler brauner Zucker","1/4 TL Vanille","1 Ei","ca. 130 g Medjool-Datteln, gehackt (ca. 9)"]],["Mascarponecreme",["225 g Mascarpone","120 ml Sahne"]]],"steps":[["",["Sahne, braunen Zucker und Ahornsirup unter Rühren aufkochen, Butter Stück für Stück einrühren.","Ofen 180°C. 6 Förmchen (ca. 180 ml) fetten und bemehlen. Kochendes Wasser und Natron über die Datteln gießen.","Mehl, Salz und Backpulver mischen.","Butter, Zucker und Vanille schlagen, dann das Ei; Mehl und anschließend Datteln unterrühren.","30–35 Min. backen, 5 Min. abkühlen.","Auf ein Gitter stürzen, mit heißer Toffeesoße tränken, 30 Min. ruhen lassen.","Mascarpone aufschlagen, dabei langsam die Sahne zugeben.","Mit mehr Soße und Mascarponecreme servieren."]]],"notes":["Soße hält 2 Wochen, Küchlein 2 Tage. Als Blechkuchen: 23 x 23 cm, 40–45 Min."]},"pork-chive-dumplings":{"title":"Schweine-Schnittlauch-Dumplings","servings":"28 Stück","prep":"1 Std. + 30 Min. Ruhe","total":"ca. 2 Std.","ing":[["Teig",["250 g Weizenmehl","240 ml kochendes Wasser (ca. 180 ml werden gebraucht)","1/2 TL Salz","Speisestärke zum Bestäuben"]],["Füllung",["450 g Schweinehack","2 EL Schnittlauch, gehackt","ca. 100 g Kohl, fein gehobelt","1 EL geriebener Ingwer","1 EL Reisessig","Salz"]],["Zum Braten und Servieren",["60 ml Pflanzenöl","Schnittlauch, Sesam, Sesamöl","Chili Crisp","Sojasoße oder schwarzer Essig"]]],"steps":[["",["Salz im kochenden Wasser lösen, ca. 180 ml unter das gesiebte Mehl rühren.","10 Min. kneten, halbieren, einwickeln, 30 Min. ruhen lassen.","Zu 2,5 cm dicken Rollen formen, jede in 14 Stücke schneiden.","Jedes dünn ausrollen, 9-cm-Kreise ausstechen, mit Stärke bestäuben, abdecken.","Füllung mischen, 15 Min. ruhen lassen.","Mit 1 EL füllen, falten und verschließen.","Mit der flachen Seite in 2 EL Öl 2–3 Min. goldbraun braten.","120 ml Wasser angießen, sofort zudecken, ca. 7 Min. garen.","Garnieren, mit Chili Crisp und Sojasoße servieren."]]],"notes":["Einzeln einfrieren, 3 Monate haltbar; gefroren 1–2 Min. länger garen."]},"puffy-pita":{"title":"Fluffige Pita mit Tzatziki","servings":"6 Pitas","prep":"15 Min. + 1,5–2,5 Std. gehen","total":"ca. 2,5 Std.","nutr":"217 kcal pro Pita","ing":[["Pita",["335 g Mehl (Vollkorn geht auch)","1 EL Salz","205 ml lauwarmes Wasser","1 EL Trockenhefe","1 EL Zucker","1 EL Olivenöl"]],["Tzatziki",["1/2 Gurke, gerieben und ausgedrückt","1/2 Bund Petersilie und Dill, gehackt","2 Knoblauchzehen, gehackt","150 g (veganer) Joghurt","1 Schuss Olivenöl","Saft von 1/2 Zitrone","Salz und Pfeffer"]]],"steps":[["",["Wasser, Zucker und Hefe verrühren.","Mehl, Salz und Öl dazu, zu einem weichen Teig kneten.","1–2 Std. ruhen lassen.","Zu 6 Fladen formen, 30 Min. ruhen lassen.","Bei 250°C 4–5 Min. backen, bis sie aufgehen.","Tzatziki: alles verrühren."]]],"notes":["1 EL Salz ist viel für 335 g Mehl – vielleicht mit 1–2 TL anfangen."]},"street-corn-nicki":{"title":"Mexikanischer Mais-Nudelsalat (Nicki)","servings":"6 Portionen","prep":"15 Min.","total":"30 Min. + kühlen","ing":[["Nudelsalat",["ca. 250 g Makkaroni (roh)","ca. 285 g TK-Mais","ca. 60 g Cotija (oder Parmesan)","ca. 75 g rote Zwiebel, gewürfelt","2 Jalapeños, gehackt","ca. 15 g Koriander, gehackt","2 Knoblauchzehen, gehackt","1 TL Chilipulver","1/4 TL Salz","1/4 TL Pfeffer","1/4 TL Knoblauchpulver","1/8 TL Cayenne"]],["Dressing",["ca. 220 g Mayonnaise","ca. 120 g saure Sahne (oder griech. Joghurt)","60 ml Limettensaft","2 TL Limettenabrieb","1/4 TL Salz","1/4 TL Pfeffer"]]],"steps":[["",["Makkaroni kochen, abgießen, kalt stellen.","Mais garen oder in der Pfanne mit Knoblauchpulver und Tajín 6–8 Min. bei mittlerer Hitze rösten.","Dressing verrühren, beiseitestellen.","Nudeln, Mais und Rest mischen, Dressing unterheben, abschmecken."]]],"notes":["In der Caption stehen nur die Zutaten; Schritte daraus abgeleitet."]},"cauli-pitta":{"title":"Gewürz-Blumenkohl in Pita mit Hummus","servings":"2 Portionen","prep":"5 Min.","total":"25 Min.","ing":[["",["1 kleiner Blumenkohl","1/2 TL Kurkuma","1/2 TL Chilipulver","1 TL Kreuzkümmel","2 Vollkorn-Pitas","2 EL Hummus","1 große Handvoll Rucola","Granatapfelkerne","1 Prise Chiliflocken","Olivenöl","1 Prise Meersalz"]]],"steps":[["",["Ofen auf 200°C Umluft vorheizen.","Blumenkohl in kleine Röschen teilen, auf dem Blech mit Öl, Gewürzen und Salz mischen, 15–20 Min. rösten (noch mit Biss).","Pitas aufschneiden und toasten, je 1 gehäuften EL Hummus hinein, dann Blumenkohl, Rucola, Granatapfel und Chiliflocken."]]],"notes":[]},"apple-beignets":{"title":"Apfel-Beignets (Apfelküchle)","servings":"4 Portionen","prep":"10 Min.","total":"25 Min.","ing":[["",["3 Äpfel","100 g Mehl mit Backpulver (oder 100 g Mehl + 1 TL Backpulver)","1 Ei","70 ml Milch","30 g Butter zum Braten","1 EL Olivenöl zum Braten"]],["Zimtzucker",["2 TL Zimt","3 EL feiner Zucker"]]],"steps":[["Mein Vorschlag (Anleitung nur im Video)",["Mehl, Ei und Milch zu einem dicken Teig verrühren.","Äpfel entkernen, in ca. 1 cm dicke Ringe schneiden.","Butter und Öl in einer Pfanne bei mittlerer Hitze erhitzen.","Apfelringe durch den Teig ziehen, 2–3 Min. pro Seite goldbraun braten.","Noch warm in Zimtzucker wälzen."]]],"notes":[]},"french-onion-pasta":{"title":"One-Pot Zwiebelsuppen-Pasta","servings":"4 Portionen","prep":"10 Min.","total":"ca. 1 Std.","ing":[["",["340 g Rigatoni","2 EL Butter","2 EL Olivenöl","3 große Zwiebeln, in Ringen","5 Knoblauchzehen, gehackt","3 TL frischer Thymian + etwas mehr","80 ml Weißwein","1 TL Worcestersauce","1 TL Salz","1 TL schwarzer Pfeffer","720 ml Rinderbrühe","240 ml Wasser","80 ml Sahne","ca. 150 g Gruyère, gerieben (100 g + 50 g)"]]],"steps":[["",["Butter und Öl in einer ofenfesten Pfanne erhitzen, Zwiebeln dazu und mischen. Backofengrill einschalten.","Zwiebeln bei niedriger Hitze langsam goldbraun karamellisieren, oft rühren; bei Bedarf einen Schuss Wasser.","Knoblauch und Thymian dazu, kurz anbraten.","Mit Wein ablöschen, Bratsatz lösen, 1–2 Min. einkochen.","Brühe, Wasser, Worcester, Salz, Pfeffer und Nudeln dazu; aufkochen, 6–8 Min. köcheln, bis sie al dente sind.","Vom Herd nehmen, Sahne und 100 g Käse einrühren.","50 g Käse darüber, ca. 2 Min. grillen.","Mit Thymian bestreuen und servieren."]]],"notes":["Worcester, Salz und Pfeffer mit der Brühe zugeben (in der Caption steht nicht wann)."]},"white-lasagna":{"title":"Weiße Lasagne mit Spinat und Pilzen","servings":"6–9 Portionen","prep":"20 Min.","total":"ca. 50 Min.","nutr":"266 kcal pro Portion","ing":[["",["480 ml Vollmilch","2 EL Olivenöl","ca. 110 g Zwiebel, gehackt","3 EL gehackter Knoblauch","ca. 80 g Champignons, in Scheiben","1 TL getrocknetes Basilikum","1 TL getrockneter Oregano","1/2 TL Chiliflocken","1 1/4 TL Meersalz (1/4 + 1)","170 g frischer Spinat","ca. 280 g gegartes Hähnchen, zerzupft","480 ml Hühner- oder Gemüsebrühe (120 + 360 ml)","ca. 30 g Mehl","1/4 TL Muskat","ca. 50 g geriebener Parmesan","170 g Lasagneblätter (ohne Vorkochen), gebrochen","ca. 125 g Gruyère oder Mozzarella"]]],"steps":[["",["Ofen auf 190°C vorheizen.","Zwiebel, Knoblauch, Pilze, Kräuter, Chili und 1/4 TL Salz im Öl 3–4 Min. anbraten.","Spinat zusammenfallen lassen, vom Herd nehmen, Hähnchen unterrühren.","120 ml Brühe mit dem Mehl verquirlen. 360 ml Brühe, Milch, Muskat und 1 TL Salz erhitzen; wenn es blubbert, Mehlmischung einrühren, 6 Min. köcheln, Parmesan einrühren.","In einer Gusseisenpfanne: 120 ml Soße, dann 1/3 Nudeln, 1/3 Hähnchenmischung, 240 ml Soße, Käse; 3-mal schichten.","Mit Alufolie abdecken, 20–25 Min. backen, bis es blubbert."]]],"notes":["Für die letzten 5 Min. die Folie abnehmen, dann wird es goldbraun."]},"focaccia":{"title":"Focaccia über Nacht","servings":"2 runde Fladen","prep":"15 Min. + 12 Std. Kühlschrank + 3–4 Std.","total":"ca. 17 Std.","ing":[["",["512 g Weizenmehl (oder Brotmehl)","10–15 g grobes Salz","8 g Trockenhefe","455 g lauwarmes Wasser","Butter zum Einfetten","4 EL Olivenöl, aufgeteilt","Flockiges Meersalz","1–2 TL Rosmarin (optional)"]]],"steps":[["",["Mehl, Salz und Hefe mischen, Wasser dazu, zu einer klebrigen Kugel rühren. 30 Min. ruhen lassen (optional: 8–10-mal dehnen und falten).","Oberfläche ölen, abdecken, mind. 12 Std. (bis 3 Tage) in den Kühlschrank.","Zwei runde Formen (20–23 cm) oder eine Form 23 x 33 cm auslegen oder fetten.","1 EL Öl pro runde Form. Teig mit Gabeln zusammenfallen lassen, halbieren, im Öl wenden, in die Formen legen. 3–4 Std. offen ruhen lassen.","Ofen 220°C. Oben ölen, mit geölten Fingern tiefe Mulden drücken, mit Meersalz und Rosmarin bestreuen.","25–30 Min. backen, bis die Unterseite goldbraun ist. 10 Min. abkühlen."]]],"notes":["Wenig Zeit: 1,5–2 Std. bei Zimmertemperatur gehen lassen, dann 30–60 Min.","Bei 175°C 15 Min. aufbacken."]}},"en":{"moules-marinieres":{"title":"Moules Marinières","servings":"2 servings","prep":"10 min","total":"36 min","ing":[["",["2 shallots","1 clove garlic","20 g butter","220 g dry white wine","1 tsp lemon juice","50 g water","1 pinch salt","1 pinch pepper","1500 g fresh mussels","100 g thick crème fraîche","15 g cornflour","6 chives, snipped"]]],"steps":[["",["Shallots and garlic: 5 sec/speed 5.","Add butter: 3 min/100°C.","Add white wine, lemon juice, water, salt and pepper.","Place the Varoma with the mussels on top: 20 min/Varoma. Remove the Varoma.","Add crème fraîche and cornflour: 10 sec/speed 6.","Add chives: 3 min/90°C/speed 2.","Put the mussels in a dish, pour over the sauce and serve hot."]]],"notes":["Stir the mussels now and then while steaming.","From the comments: put something in the middle of the Varoma for better steam flow; parsley works instead of chives; less or no cream is fine. Classic with fries (moules-frites)."]},"ratatouille":{"title":"Ratatouille","servings":"4 servings","prep":"10 min","total":"51 min","ing":[["",["1 yellow onion, halved","3 cloves garlic","20 g olive oil","1 tsp herbes de Provence","1 bay leaf","1 tbsp vegetable stock paste","300 g tomatoes, quartered","50 g red pepper","50 g yellow pepper","50 g green pepper","1 tsp salt","2 pinches pepper","200 g courgette, in 2–3 cm pieces","300 g aubergine, in 2–3 cm pieces"]]],"steps":[["",["Onion and garlic: 5 sec/speed 5. Scrape down.","Add oil, herbs and bay leaf: 5 min/100°C/speed 1.","Add stock, tomatoes and peppers: 14 min/100°C, simmering basket instead of the measuring cup.","Add salt, pepper, courgette and aubergine: 22 min/100°C.","Serve hot."]]],"notes":["Cut vegetables into even 2–3 cm pieces so they don't turn to mush.","No speed given for steps 3 and 4: reverse, gentle stir recommended."]},"tomatencremesuppe":{"title":"Cream of Tomato Soup","servings":"4 servings","prep":"10 min","total":"25 min","nutr":"188 kcal per serving","ing":[["",["1 clove garlic","50 g onion, halved","30 g butter or olive oil","700 g tomatoes, halved","70 g tomato paste","1 tsp salt","1 tsp sugar","1 tsp dried oregano or pizza seasoning","500 g water","1 stock cube (for 0.5 l) or 1 heaped tsp stock paste","100 g cream","2–4 basil leaves","1 sprig parsley, leaves only"]]],"steps":[["",["Garlic and onion 3 sec/speed 5, scrape down.","Add butter, sauté 3 min/120°C/speed 1.","Add tomatoes, tomato paste, salt, sugar and oregano, 5 sec/speed 5.","Add water and stock cube, cook 15 min/100°C/speed 2.","Add cream, basil and parsley, blend 1 min, slowly increasing from speed 4 to 8. Serve hot."]]],"notes":["Instead of pizza seasoning: thyme, oregano, marjoram (max. 1 tsp dried in total).","Sour cream can replace the cream."]},"spargelcremesuppe":{"title":"Cream of Asparagus Soup","servings":"6 servings","prep":"20 min","total":"40 min","nutr":"201 kcal per serving","ing":[["",["900 g water","30 g butter (10 g + 20 g)","1 tsp sugar","500 g white asparagus, peeled (keep peel), in 3 cm pieces","30 g cornflour","1/4 tsp Worcestershire sauce","20 g dry white wine (optional)","1 tsp lemon juice","1/4 tsp pepper","1 1/2 tsp salt","2 egg yolks","200 g cream","1 pinch nutmeg"]]],"steps":[["",["Water, 10 g butter, sugar and asparagus peel in the bowl. Insert simmering basket with the asparagus, 15 min/100°C/speed 1.","Put asparagus in a bowl. Strain the bowl contents through the basket, keep the asparagus water, discard peel.","Asparagus without tips, asparagus water, 20 g butter, cornflour: blend 20 sec, speed 4→8.","Add Worcestershire, wine, lemon, pepper, salt, 5 min/100°C/speed 2, then cool to 80°C (ca. 5 min). Meanwhile whisk yolks and cream.","Add tips, nutmeg and yolk-cream, 2 min/80°C/reverse/speed 2. Season, serve at once."]]],"notes":["Broken asparagus is perfectly fine; use up to 700 g if it's not very aromatic.","Variation: replace half the cream with milk."]},"rindergulasch":{"title":"Beef Goulash with Bread Dumplings","servings":"6 servings","prep":"30 min","total":"1 h 30 min","nutr":"554 kcal per serving","ing":[["Bread dumpling dough",["6–7 stale rolls (300 g), in 1 cm slices","5 sprigs parsley, leaves only","80 g onion, halved","25 g butter","220 g milk","3 eggs","1 tsp salt","2 pinches pepper","2 pinches nutmeg"]],["Beef goulash",["3 cloves garlic","450 g onions, quartered","30 g oil or clarified butter + extra for greasing","750 g goulash beef, patted dry","1 tsp sugar","50 g tomato paste","350 g tomatoes, small pieces","200 g red wine","2 tbsp sweet paprika","2 tsp salt","1/2 tsp black pepper","1/2 tsp caraway","1 tsp grated lemon zest","1 tbsp marjoram","3 bay leaves","5 juniper berries","1 pinch ground cloves or 2 cloves","300 g water (100 + 50 + 150 g)","30 g flour","200 g red/green pepper, thin strips"]]],"steps":[["Bread dumpling dough",["Chop rolls with spatula 12 sec/speed 6, transfer.","Parsley and onion 3 sec/speed 6, scrape down.","Add butter, sauté 3 min/120°C/speed 1.","Add milk, 1 min 30 sec/60°C/speed 1.","Add rolls, eggs, salt, pepper, nutmeg, mix with spatula 20 sec/reverse/speed 3, transfer, mix again. Rinse bowl."]],["Beef goulash",["Garlic, onions, oil 3 sec/speed 5, then sauté 3 min/120°C/speed 1.","Add meat, 5 min/120°C/reverse/gentle stir.","Add sugar, tomato paste, tomatoes, wine and all spices, 40 min/100°C/reverse/speed 1. Meanwhile grease the Varoma, shape 12 dumplings and place them in it.","Add 100 g water, place Varoma, 20 min/Varoma/reverse/speed 1. Set Varoma aside.","Mix flour with 50 g water, add with 150 g water and peppers, place Varoma, 8 min/90°C/reverse/speed 1. Season, serve with dumplings."]]],"notes":["Dumpling dough too soft: add some breadcrumbs. Good for old bread, toast, baguette.","Goulash also goes with pasta, boiled potatoes, rice or bread.","Bacon dumplings: sauté 120 g diced bacon in step 3.","Venison goulash: venison instead of beef, mushrooms instead of peppers."]},"kartoffelpueree":{"title":"Mashed Potatoes","servings":"4 servings","prep":"15 min","total":"45 min","nutr":"296 kcal per serving","ing":[["",["1000 g floury potatoes, peeled, 5 mm slices","1 tsp salt","350 g milk","30 g butter, in pieces","1–2 pinches nutmeg"]]],"steps":[["",["Insert butterfly whisk. Potatoes, salt, milk without measuring cup 25–30 min/98°C/speed 1. If it boils over: reduce to 95°C.","Add butter and nutmeg, insert measuring cup, 30 sec/speed 3. Serve hot."]]],"notes":["Depending on potato variety, maybe cook 5 min longer.","Creamier: 100 g extra milk in step 2.","Italian style: only 1/2 tsp salt, 30 g parmesan in step 2."]},"milchreis":{"title":"Rice Pudding","servings":"8 servings (3–4 as a main)","prep":"5 min","total":"1 h","nutr":"203 kcal per serving","ing":[["",["1000 g milk","50 g sugar","1 pinch salt","220 g pudding rice"]]],"steps":[["",["Everything without measuring cup 38 min/90°C/reverse/speed 1.","Transfer, let swell 15 min. Warm or cold, with sugar or cinnamon sugar."]]],"notes":["Great with Rote Grütze (red berry compote).","Half quantity: 35 min; 1.5× quantity: 41 min.","Variation: cook 1 tsp lemon zest with it."]},"germknoedel":{"title":"Germknödel (Yeast Dumplings)","servings":"4 pieces","prep":"20 min","total":"1 h","nutr":"623 kcal per piece","ing":[["",["40 g poppy seeds","30 g sugar (20 + 10 g)","100 g milk","20 g fresh yeast (1/2 cube)","270 g flour","1 egg","130 g butter (30 g dough + 100 g to pour over) + extra for greasing","1/2 tsp salt","40 g plum butter (Pflaumenmus)","500 g water"]]],"steps":[["",["Poppy seeds and 20 g sugar 30 sec/speed 10, transfer, rinse bowl.","Milk, 10 g sugar, yeast 1 min/37°C/speed 3.","Add flour, egg, 30 g butter, salt, 1 min 30 sec/dough mode.","Grease the Varoma. Divide dough into 4, flatten, put plum butter in the middle, shape into dumplings.","Place in the Varoma (keep vents free), rise 30 min somewhere warm. Rinse bowl.","Water in the bowl, place Varoma, 20 min/Varoma/speed 1. Set Varoma aside, empty bowl.","Melt 100 g butter 1 min 30 sec/80°C/speed 1.","Pour butter over the dumplings, sprinkle with poppy sugar, serve warm."]]],"notes":["Enough as a sweet main for 2–3 adults."]},"bienenstich":{"title":"Bee Sting Cake (Bienenstich)","servings":"12 pieces · 26 cm springform","prep":"20 min","total":"1 h 30 min + 4 h chilling","nutr":"376 kcal per piece","ing":[["Dough",["50 g oil + extra for greasing","1–2 tbsp breadcrumbs","130 g quark","50 g milk","1 egg","300 g flour","1 sachet baking powder","100 g sugar"]],["Topping",["50 g sugar","1 tsp vanilla sugar","100 g butter","30 g apricot jam","200 g flaked almonds"]],["Filling",["5 sheets white gelatine","500 g milk","100 g sugar","1 sachet vanilla pudding powder","200 g cream"]]],"steps":[["Dough",["Oven 180°C. Grease tin, dust with breadcrumbs.","Quark, milk, egg, flour, baking powder, sugar, oil 15 sec/speed 5, into the tin. Rinse bowl."]],["Topping",["Sugar, vanilla sugar, butter, jam 2 min 30 sec/60°C/speed 2, then 5 sec/speed 6.","Add almonds, 8 sec/reverse/speed 1. Spread on the dough, bake 30 min at 180°C, let cool."]],["Filling",["Soak gelatine. Rinse bowl.","Milk, sugar, pudding powder 6 min 30 sec/100°C/speed 3.","Add gelatine, 30 sec/speed 3, transfer. Cool 25–30 min in a water bath, stirring now and then.","Butterfly whisk: whip cream on speed 3, fold into the pudding.","Halve the cake, spread cream on the base, let set briefly, add almond top. Chill at least 4 h (better overnight), cut into 12."]]],"notes":["Cut the almond top into 12 pieces before placing it on the cream, otherwise it's hard to cut."]},"schwarzwaelder":{"title":"Black Forest Cherry Cake","servings":"16 pieces · 26 cm springform","prep":"20 min","total":"1 h","nutr":"488 kcal per piece","ing":[["Dough",["300 g soft butter + extra for greasing","200 g sugar","30 g cocoa","5 eggs","300 g flour","1 sachet baking powder"]],["Filling",["800 g cream","3 tsp vanilla sugar","2 sachets cream stabiliser (Sahnesteif)","50 g kirsch","1 jar sour cherries, drained (450 g), a few for decoration"]],["To sprinkle",["50 g chocolate sprinkles or shavings"]]],"steps":[["Dough",["Oven 180°C, grease tin.","Butter, sugar, cocoa, eggs 1 min/37°C/speed 5.","Add flour, baking powder, 30 sec/speed 6 with spatula.","Bake 45 min at 180°C, cool, cut twice horizontally (3 layers). Rinse bowl."]],["Filling",["Butterfly whisk: cream, vanilla sugar, stabiliser on speed 3 until stiff, transfer.","Bottom layer: half the kirsch, cherries, 1/4 of the cream.","Second layer: remaining kirsch, 1/2 of the cream.","Top layer on, rest of the cream on top and sides.","Decorate with cherries and chocolate, cut into 16."]]],"notes":["Keep the cherry juice: for quark dessert, ice lollies or hot cherry sauce.","For kids, leave out the kirsch."]},"zupfkuchen":{"title":"Russian Pluck Cake (Zupfkuchen)","servings":"16 pieces · 26 cm springform","prep":"20 min","total":"1 h 30 min","nutr":"406 kcal per piece","ing":[["Dough",["200 g butter","150 g sugar","350 g flour","30 g cocoa powder","1 sachet baking powder","1 egg"]],["Filling",["180 g soft butter","200 g sugar","4 eggs","500 g low-fat quark","1 tsp vanilla sugar","1 sachet vanilla pudding powder"]]],"steps":[["Dough",["Oven 180°C, line tin with baking paper.","All dough ingredients 30 sec/speed 6, knead briefly by hand. Press 2/3 into the tin with a 3 cm rim. Keep the rest."]],["Filling",["All filling ingredients 40 sec/speed 5, pour onto the base.","Pluck the rest of the dough into pieces, scatter over, bake 60–70 min at 180°C. Let cool."]]],"notes":["You can also cut shapes from the leftover dough (hearts, stars, bunnies)."]},"zimtsterne":{"title":"Cinnamon Stars (Zimtsterne)","servings":"60 pieces","prep":"45 min","total":"1 h 30 min","nutr":"78 kcal per piece","ing":[["",["400 g sugar (100 + 300 g)","2 cinnamon sticks (ca. 5 cm each)","500 g almonds, unpeeled","2 tsp honey (e.g. acacia)","3 egg whites (2 dough + 1 glaze)"]]],"steps":[["",["100 g sugar 10 sec/speed 10 to icing sugar, transfer.","300 g sugar + cinnamon sticks 15 sec/speed 10, transfer.","Almonds 15 sec/speed 10.","Add cinnamon sugar, again 15 sec/speed 10.","Add honey and 2 egg whites, 10 sec/speed 5, knead by hand.","Oven 150°C, 3 trays with baking paper. Rinse bowl thoroughly.","Glaze: icing sugar + 1 egg white 3 min/speed 3.5 until white and syrupy.","Roll out 6–8 mm thick between cling film, cut 60 stars, glaze, bake each tray 12–14 min at 150°C.","Carefully move onto a rack (very soft when hot), cool, store in a tin."]]],"notes":["Instead of cinnamon sticks: 2 tsp ground cinnamon.","Instead of cling film: a cut-open freezer bag."]},"amerikaner":{"title":"Amerikaner (Iced Soft Cookies)","servings":"12 pieces","prep":"25 min","total":"2 h","nutr":"254 kcal per piece","ing":[["Dough",["1/4 organic lemon, zest thinly peeled","100 g sugar","100 g soft butter","10 g vanilla sugar","2 eggs","45 g milk","200 g flour","50 g cornflour","2 tsp baking powder"]],["Icing",["200 g icing sugar","30 g water"]]],"steps":[["",["Oven 180°C, 2 trays with baking paper.","Lemon zest 5 sec/speed 8, scrape down.","Add sugar, 15 sec/speed 10, scrape down.","Add butter and vanilla sugar, 1 min/speed 3.","Add eggs, milk, flour, cornflour, baking powder, 20 sec/speed 4.","Use two tablespoons to place 6 mounds per tray (leave space!). Bake one tray at a time 12–15 min at 180°C, cool ca. 1 h. Rinse bowl.","Icing sugar and water 15 sec/speed 3, spread on the flat side, let dry."]]],"notes":["Variation: chocolate glaze or half/half (recipe in the book p. 88)."]},"quark-hefe-taler":{"title":"Quark Yeast Buns","servings":"10 pieces","prep":"30 min","total":"2 h 15 min","nutr":"363 kcal per piece","ing":[["Dough",["2 eggs","50 g milk","50 g sugar","1/2 cube fresh yeast (20 g)","350 g flour + extra for shaping","120 g soft butter","1 pinch salt"]],["Topping",["1/2 organic lemon, zest thinly peeled","50 g sugar","400 g full-fat quark","20 g sunflower oil","10 g cornflour"]]],"steps":[["Dough",["Eggs, milk, sugar, yeast 2 min/37°C/speed 2.","Add flour, butter, salt, 2 min/dough mode. Cover and rise 1 h."]],["Topping",["Oven 180°C, 2 trays with baking paper.","Lemon zest and sugar 10 sec/speed 10, scrape down.","Add quark, oil, cornflour, 10 sec/speed 3.","Shape dough into a 20 cm log, cut into 10, shape into 8 cm discs with a thicker rim. 2 tbsp quark in each hollow, rise 30 min. Bake one tray at a time 15–20 min at 180°C."]]],"notes":["The buttery dough doesn't rise much but stays fresh for a long time.","Mandarin version (as in the photo): put 2–3 tinned mandarin segments under the quark.","Or: brush cooled buns with melted butter and roll in sugar."]},"franzbroetchen":{"title":"Franzbrötchen (Hamburg Cinnamon Pastries)","servings":"18 pieces","prep":"40 min","total":"2 h 20 min","nutr":"212 kcal per piece","ing":[["Dough",["220 g milk","70 g sugar","1 cube fresh yeast (40 g)","500 g flour + extra for rolling","50 g soft butter","1 pinch salt"]],["Filling",["100 g cold butter, very thinly sliced","Water for brushing","120 g sugar","1 1/2 tsp cinnamon"]]],"steps":[["Dough",["Milk, sugar, yeast 2 min/37°C/speed 2.","Add flour, butter, salt, 2 min/dough mode. Cover and rise 30 min."]],["Filling",["Roll dough to 20 x 30 cm, lay butter slices on one half, fold over, press. Roll to 30 x 50 cm, fold in thirds like a letter. Chill 15 min.","Roll to 40 x 70 cm, brush with water. Mix sugar and cinnamon, keep 3 tbsp, spread the rest. Roll up from the long side, trim ends, cut into 18 slices (ca. 4 cm).","Stand 9 slices upright per tray with plenty of space, press deeply in the middle with a wooden spoon handle. Rise 20 min, oven to 200°C.","Sprinkle with remaining cinnamon sugar, bake one tray at a time 20–25 min at 200°C."]]],"notes":[]},"brownies":{"title":"Brownies","servings":"20 pieces · 23 x 23 cm tin","prep":"20 min","total":"1 h","nutr":"256 kcal per piece","ing":[["",["250 g dark chocolate","200 g soft butter + extra for greasing","150 g raw cane sugar","120 g sugar","70 g sugar beet syrup (e.g. Grafschafter Goldsaft)","4 eggs","200 g flour","30 g cocoa"]]],"steps":[["",["Chocolate 8 sec/speed 8, scrape down.","Add butter, both sugars, syrup, 6 min/50°C/speed 2, cool to 37°C (ca. 10 min). Oven 180°C, line tin base, grease sides.","Add eggs, flour, cocoa, 15 sec/speed 4, into the tin, bake 25–30 min at 180°C. Cool in the tin, cut into 20."]]],"notes":["No skewer test – they should stay moist inside.","Wrapped in foil they keep ca. 3 days. A baking dish works instead of a square tin."]},"scones":{"title":"Scones","servings":"16 pieces","prep":"25 min","total":"40 min","nutr":"159 kcal per piece","ing":[["",["390 g flour (350 g dough + ca. 40 g for rolling)","1 sachet baking powder","1/4 tsp salt","70 g sugar","170 g milk","90 g soft butter","1 egg, beaten, for brushing"]]],"steps":[["",["Oven 180°C, tray with baking paper.","350 g flour, baking powder, salt, sugar, milk, butter with spatula 20 sec/speed 6.","Knead briefly, roll out 2 cm thick, cut 5 cm circles, dipping the cutter in flour. Brush with egg, bake 12–15 min at 180°C. Serve with butter and jam."]]],"notes":["Classic with clotted cream and jam."]},"mud-cake":{"title":"Chocolate Mud Cake","servings":"12 pieces · 26 cm springform","prep":"20 min","total":"1 h 25 min","nutr":"502 kcal per piece","ing":[["",["320 g soft butter + extra for greasing","230 g sugar","1/2 vanilla pod","260 g dark chocolate","200 g buttermilk","3 eggs","260 g flour","40 g cocoa + extra for dusting","3/4 tsp baking powder","1/4 tsp salt"]]],"steps":[["",["Oven 150°C, grease tin.","Sugar and vanilla pod 30 sec/speed 10, scrape down.","Add butter, chocolate, buttermilk, 5 min/50°C/speed 2, cool 5 min.","Add eggs, flour, cocoa, baking powder, salt, 12 sec/speed 5. Bake 50–60 min at 150°C, cool, dust with cocoa."]]],"notes":["No skewer test – it should be moist inside.","Variation: dust with icing sugar."]},"rhabarber-sahne-kuchen":{"title":"Rhubarb Cream Cake","servings":"12 pieces · 26 cm springform","prep":"45 min","total":"4 h 15 min","nutr":"336 kcal per piece","ing":[["",["100 g soft butter + extra for greasing","2 eggs","220 g sugar (100 + 100 + 20 g)","50 g milk","150 g flour","2 tsp baking powder","1 pinch salt","1000 g rhubarb, in pieces","100 g water","2 sachets vanilla pudding powder","400 g cream","1 sachet cream stabiliser"]]],"steps":[["",["Oven 180°C, line tin base, grease sides.","Eggs, butter, 100 g sugar 30 sec/speed 4.","Add milk, flour, baking powder, salt, 15 sec/speed 5. Into the tin, bake 20 min, cool ca. 30 min. Rinse bowl.","Rhubarb, water, 100 g sugar with spatula 10 sec/speed 5, then 9 min/100°C/speed 2.","Add pudding powder, 20 sec/speed 5, then 2 min/100°C/speed 2. Spread on the base, cool ca. 3 h. Rinse bowl.","Butterfly whisk: cream, 20 g sugar, stabiliser on speed 3 until stiff, spread on the cake, chill 30 min."]]],"notes":[]},"rhabarber-erdbeer-tarte":{"title":"Rhubarb Strawberry Tart","servings":"12 pieces · 28 cm tart tin","prep":"30 min","total":"1 h","nutr":"295 kcal per piece","ing":[["Shortcrust",["140 g cold butter + extra for greasing","350 g flour + extra for rolling","70 g sugar","90 g water","2 pinches salt"]],["Topping",["400 g rhubarb, 1 cm pieces","300 g strawberries, halved","120 g sugar","20 g vanilla sugar","30 g cornflour","1 egg yolk","2 tbsp milk","Icing sugar for dusting"]]],"steps":[["Shortcrust",["Oven 200°C, grease tin.","Flour, butter, sugar, water, salt 15 sec/speed 7. Press 2/3 into the tin, prick the base."]],["Topping",["Rhubarb, strawberries, sugar, vanilla sugar, cornflour with spatula 20 sec/reverse/speed 1, spread on the base.","Roll the rest to ca. 23 x 26 cm, cut 15 strips (1.5 cm), lay as a lattice. Brush with yolk and milk. Bake 30–35 min at 200°C, cool, dust with icing sugar."]]],"notes":[]},"johannisbeer-baiser":{"title":"Redcurrant Meringue Cake","servings":"12 pieces · 26 cm springform","prep":"35 min","total":"1 h 50 min","nutr":"317 kcal per piece","ing":[["Base",["200 g flour","1 tsp baking powder","100 g cold butter + extra for greasing","75 g sugar","1 egg","400 g redcurrants","1 heaped tbsp cornflour"]],["Custard",["3 eggs, separated","50 g sugar","200 g cream","40 g cornflour"]],["Meringue",["150 g sugar"]]],"steps":[["Base",["Flour, baking powder, butter, sugar, egg 15 sec/speed 5, wrap and chill 15 min. Rinse bowl.","Oven 180°C, line tin base, grease sides.","Press dough into the tin with a 4 cm rim, prick. Toss currants with cornflour, spread."]],["Custard",["Yolks, sugar, cream, cornflour 10 sec/speed 5, pour over the berries. Bake 30–35 min (5 min longer if still wobbly). Rinse bowl."]],["Meringue",["Sugar 10 sec/speed 10, transfer.","Butterfly whisk: egg whites 3 min/speed 3.5 until stiff.","1 min/speed 3.5, adding the icing sugar gradually.","Spread on the warm cake, bake another 12–15 min at 180°C."]]],"notes":[]},"himbeer-quark-streusel":{"title":"Raspberry Quark Crumble Cake","servings":"12 pieces · 26 cm springform","prep":"40 min","total":"7 h 20 min","nutr":"563 kcal per piece","ing":[["Shortcrust",["200 g cold butter + extra for greasing","190 g sugar","330 g flour","30 g vanilla sugar"]],["Filling",["3 eggs, separated","1 pinch salt","120 g soft butter","50 g cornflour","220 g sugar","30 g vanilla sugar","750 g quark (20% fat)","300 g raspberries, fresh or frozen"]]],"steps":[["Shortcrust",["Line tin base, grease sides, line a tray with foil. Oven 180°C.","Sugar 30 sec/speed 10, take out 1 tbsp icing sugar for decoration.","Add flour, butter, vanilla sugar, 15 sec/speed 5. Press half as a base, chill the rest. Pre-bake the base 15 min."]],["Filling",["Rinse bowl. Butterfly whisk: egg whites and salt 2 min/speed 3.5 until stiff, transfer.","Yolks, butter, cornflour 7 sec/speed 5.","Add sugar, vanilla sugar, quark, 30 sec/speed 4.5, gently fold into the egg whites.","Spread on the base, top with raspberries, crumble the rest of the dough over. Bake on the tray ca. 1 h 15 min at 180°C (cover after 30 min if needed). Rest 10 min in the switched-off oven, cool 2 h, chill at least 3 h (better overnight). Dust with icing sugar."]]],"notes":["Foil under the tin because butter can leak.","Variation: redcurrants, cherries or mixed berries."]},"ny-cheesecake":{"title":"New York Cheesecake with Cherry Topping","servings":"12 pieces · 26 cm springform","prep":"45 min","total":"7 h","nutr":"604 kcal per piece","ing":[["Base",["45 g soft butter + extra for greasing","35 g flour + extra for dusting","4 eggs, separated","1 pinch salt","90 g sugar","10 g vanilla sugar","1/2 organic lemon, zest thinly peeled","30 g cornflour","1 tsp baking powder"]],["Cream cheese filling",["900 g cream cheese","320 g sugar","30 g cornflour","3 eggs","200 g cream"]],["Cherry topping",["1 jar cherries (680 g), drained, juice kept","30 g sugar","1 sachet red cake glaze"]]],"steps":[["Base",["Oven 180°C, grease and flour tin.","Butterfly whisk: egg whites and salt 4 min/speed 3.5, transfer, rinse bowl.","Sugar, vanilla sugar, lemon zest 10 sec/speed 10, scrape down.","Yolks and butter 1 min/speed 4.","Flour, cornflour, baking powder 5 sec/speed 4.","Add egg whites, 5 sec/speed 4, into the tin, bake 15 min. Cool 15–20 min."]],["Filling",["Oven again 180°C. Wrap the tin tightly with two layers of foil.","Cream cheese, sugar, cornflour, eggs, cream with spatula 20 sec/speed 4, onto the base.","Deep tray on the 2nd shelf from the bottom, tin in it, add ca. 700 g warm water (5 mm deep). Bake 1 h 10 min; it may still wobble slightly. Cool 90 min."]],["Topping",["Spread cherries on the cake.","300 g cherry juice, sugar, glaze 5 min/100°C/speed 1, cool 30 sec, pour over the cherries from the centre. Chill 3 h."]]],"notes":[]},"kaese-kirsch-kuchen":{"title":"Cherry Cheesecake Traybake","servings":"20 pieces · deep tray","prep":"25 min","total":"1 h","nutr":"372 kcal per piece","ing":[["Base",["140 g butter + extra for greasing","130 g sugar","3 eggs","300 g flour","2 tsp baking powder"]],["Topping",["2 jars sour cherries (680 g each), drained","140 g sugar","3 eggs","30 g lemon juice","600 g milk","2 sachets vanilla pudding powder","1000 g quark","150 g sunflower or rapeseed oil"]]],"steps":[["",["Oven 200°C, grease deep tray.","Butter, sugar, eggs, flour, baking powder 30 sec/speed 4, spread on the tray. Rinse bowl.","Spread cherries.","Sugar, eggs, lemon juice 1 min/speed 4.","Milk, pudding powder, quark 10 sec/speed 4.","Add oil, 10 sec/speed 4. Pour over the cherries, bake 30 min at 200°C."]]],"notes":["Variation: mandarins or peaches instead of cherries."]},"frankfurter-kranz":{"title":"Frankfurter Kranz (Buttercream Crown Cake)","servings":"16 pieces · 22 cm ring tin","prep":"1 h","total":"6 h","nutr":"317 kcal per piece","ing":[["Sponge",["5 eggs","150 g sugar","230 g flour","1/2 tsp baking powder","1 pinch salt"]],["Buttercream",["400 g milk","80 g sugar","1 sachet vanilla pudding powder","1 pinch salt","220 g butter, room temperature"]],["Finishing",["100 g sour cherry jam","200 g hazelnut brittle","2 glacé cherries, in 16 pieces"]]],"steps":[["Sponge",["Oven 180°C.","Butterfly whisk: eggs and sugar 6 min/37°C/speed 4.","Add flour, baking powder, salt around the whisk, 4 sec/speed 3, fold in with spatula if needed.","Into the ungreased tin, bake 20–25 min, cool ca. 45 min. Cut twice horizontally."]],["Buttercream",["Milk, sugar, pudding powder, salt 5 sec/speed 4, then 6 min/100°C/speed 2.5. Cover directly with cling film, cool to room temperature ca. 2 h.","Butter 1 min/speed 4.","1 min 30 sec/speed 2.5, adding the pudding gradually (not smooth: 10 sec/speed 6)."]],["Finishing",["1/3 cream on the first layer, pipe a ring of jam from a freezer bag.","Second layer on, just under half the remaining cream and jam. Top on, chill at least 30 min.","2 tbsp cream into a piping bag, cover the cake with the rest, press on the brittle.","Pipe 16 dots, decorate with glacé cherries, chill at least 1 h."]]],"notes":["Butter and pudding must both be at room temperature, otherwise the cream curdles."]},"erdbeer-pfirsich-torte":{"title":"Strawberry Peach Cake","servings":"12 pieces · 26 cm springform","prep":"1 h","total":"5 h","nutr":"352 kcal per piece","ing":[["Sponge",["4 eggs","120 g sugar","180 g flour","1/2 tsp baking powder","1 pinch salt"]],["Filling and topping",["10 sheets white gelatine","80 g sugar","400 g cream","500 g quark (20%)","40 g lemon juice (20 + 20 g)","1 tin peaches (450 g drained)","300 g cherry juice","1 sachet red cake glaze","500 g strawberries, quartered"]]],"steps":[["Sponge",["Oven 180°C, line tin base, don't grease sides.","Butterfly whisk: eggs and sugar 6 min/37°C/speed 4.","Flour, baking powder, salt 4 sec/speed 3, fold in with spatula.","Bake 20–25 min, cool 45 min, cut once horizontally."]],["Filling",["Soak gelatine. Sugar 10 sec/speed 10.","Butterfly whisk: whip cream on speed 3.","Add quark and 20 g lemon juice, 8 sec/speed 4, transfer.","Peaches and 20 g lemon juice 10 sec/speed 10.","Add gelatine, 3 min/50°C/speed 3.","1 min/speed 3, adding 2/3 of the cream mixture through the lid. Let set 15 min.","Bottom layer in the springform ring, fill with peach cream, top layer on. Chill cake and remaining cream at least 2 h.","Remove ring, cover the cake with the remaining cream."]],["Topping",["Cherry juice and glaze 3 sec/speed 5, then 3 min/100°C/speed 1.","Fold in strawberries, spread on the cake immediately. Chill 15 min."]]],"notes":[]},"pflaumenstrudel":{"title":"Plum Strudel with Crumble","servings":"12 pieces (2 strudels)","prep":"45 min","total":"1 h 45 min","nutr":"420 kcal per piece","ing":[["Strudel dough",["370 g flour + extra","1 egg","40 g sunflower oil","120 g water","10 g vinegar","1/2 tsp salt"]],["Filling",["1 sprig rosemary, leaves only","125 g sugar","100 g almonds","150 g flour","170 g butter (120 g crumble + 50 g for brushing)","1 pinch salt","100 g plum butter (Pflaumenmus)","500 g plums, quartered"]]],"steps":[["",["Strudel dough 2 min/dough mode, wrap and chill 30 min.","Oven 230°C, tray with baking paper.","Rosemary and sugar 15 sec/speed 10, transfer.","Almonds 10 sec/speed 7.","Add flour, 120 g butter, salt, rosemary sugar, 10 sec/speed 6 to crumbs.","Roll the dough thin on a floured tea towel and stretch paper-thin with the backs of your hands.","Melt 50 g butter 2 min/80°C/speed 2, brush 2/3 on the dough.","Spread plum butter along one short side (leave edges and a middle strip free), add crumble and plums. Roll up with the towel, cut in the middle, seal the ends.","Brush with remaining butter, bake 25–30 min at 230°C. Serve lukewarm."]]],"notes":["In the book served with icing sugar and vanilla sauce."]},"nussecken":{"title":"Nut Corners (Nussecken)","servings":"30 pieces (1 tray)","prep":"30 min","total":"1 h 10 min","nutr":"269 kcal per piece","ing":[["Shortcrust",["300 g flour","80 g cornflour","1 tsp baking powder","20 g vanilla sugar","2 eggs","150 g cold butter"]],["Topping",["400 g hazelnuts","180 g apricot jam","200 g butter","200 g sugar","10 g vanilla sugar","75 g water"]]],"steps":[["",["Dough ingredients 20 sec/speed 5, roll out on baking paper to ca. 30 x 40 cm, slide onto the tray.","Oven 180°C. Rinse bowl.","Hazelnuts 10 sec/speed 7, transfer.","Jam 4 min/60°C/speed 1, spread on the dough.","Butter, sugar, vanilla sugar 2 min/60°C/speed 1.5.","Add nuts and water, 30 sec/speed 4, spread, bake 30 min, cool.","Cut into 5 strips (8 cm), then 3 rectangles each (10 cm), halve diagonally."]]],"notes":["Dip the corners in melted chocolate (as in the photo)."]},"vanillekipferl":{"title":"Vanilla Crescents (Vanillekipferl)","servings":"50 pieces","prep":"45 min","total":"3 h 30 min","nutr":"76 kcal per piece","ing":[["",["150 g sugar","20 g vanilla sugar","100 g blanched almonds","280 g flour","210 g butter, in small pieces"]]],"steps":[["",["Sugar and vanilla sugar 20 sec/speed 10, into a shallow dish.","Almonds 5 sec/speed 7.","Add flour, 70 g vanilla icing sugar, butter, with spatula 40 sec/speed 5. Wrap and chill 2 h.","Oven 180°C, 2 trays with baking paper.","Shape walnut-sized pieces into crescents, bake one tray at a time 15–20 min. Roll in the remaining icing sugar while warm."]]],"notes":[]},"sonntagsstuten":{"title":"Sunday Braided Loaf (Sonntagsstuten)","servings":"1 loaf (30 slices)","prep":"25 min","total":"2 h 25 min","nutr":"99 kcal per slice","ing":[["",["250 g milk","30 g fresh yeast (3/4 cube)","80 g sugar","600 g wheat flour type 550","1 tsp salt","50 g white wine","1 egg yolk, beaten","2 tbsp pearl sugar","2 tbsp flaked almonds"]]],"steps":[["",["Milk, yeast, sugar 2 min/37°C/speed 2.","Add flour, salt, wine, 3 min/dough mode. Cover and rise 1 h.","Divide dough into 3, roll into 45 cm strands, braid. On the tray, brush with yolk, sprinkle with pearl sugar and almonds. Rise 20 min, oven 180°C.","Bake 30–35 min at 180°C."]]],"notes":["In the book served with quark/cream cheese and jam."]},"farfalle-salat":{"title":"Farfalle Pasta Salad","servings":"6–8 servings","prep":"","total":"","ing":[["",["500 g farfalle","1 jar sun-dried tomatoes (280 g, in oil)","50 g olive oil","50 g white balsamic vinegar","1 tsp ajvar","2 tbsp oregano","Salt and pepper","1 bunch spring onions","500 g cherry tomatoes","200 g pine nuts","125 g rocket"]]],"steps":[["",["Mix everything together."]]],"notes":[]},"mamas-linsensuppe":{"title":"Mum's Lentil Soup","servings":"","prep":"","total":"","ing":[["",["2 Mettwürstchen (smoked pork sausages)","2 cups lentils","4 cups potatoes (quartered)","Soup vegetables (carrot, celeriac, leek)","Vinegar (to taste)"]]],"steps":[["",["Cook everything together, season with vinegar."]]],"notes":[]},"spinat-spaetzle":{"title":"Spinach Spätzle with Ham Cream Sauce","servings":"ca. 4 servings","prep":"","total":"","ing":[["Spätzle",["400 g flour","250 g frozen leaf spinach","6 eggs","1 tsp salt, pepper, nutmeg"]],["Sauce",["1 onion","30 g butter","1 tsp flour","1 tub cream (200 g)","250 g milk","Salt, pepper, nutmeg","200 g cooked ham"]],["To serve",["Parmesan"]]],"steps":[["",["Thaw the spinach and pour off the liquid.","Spinach and eggs 8 sec/speed 7. Add flour, salt, pepper, nutmeg, 15 sec/speed 5.","Rest the dough 15 min.","Onion 4 sec/speed 5, add butter, 3 min/100°C/speed 1. Add 1 tsp flour, 3 min/100°C/speed 1. Add cream, milk, spices, 6 min/90°C/speed 4, at the end 10 sec/speed 10.","Press the spätzle dough into boiling salted water, bring back to the boil briefly.","Add ham to the sauce, 2 min/100°C/reverse.","Serve sprinkled with parmesan."]]],"notes":[]},"erdbeer-panna-cotta-torte":{"title":"Strawberry Panna Cotta Cake","servings":"1 springform","prep":"","total":"+ min. 5 h chilling","ing":[["",["200 g chocolate cookies","50 g butter","6 sheets white gelatine","300 g water (for soaking)","250 g low-fat quark","500 g cream (150 + 100 + 250 g)","100 g sugar","1 tbsp vanilla sugar","500 g strawberries"]]],"steps":[["",["Cookies and butter 15 sec/speed 6, press into the springform, chill 30 min.","Soak gelatine in water.","Butterfly whisk: quark, 150 g cream, sugar, vanilla sugar 30 sec/speed 2.5.","Warm 100 g cream in a pan, dissolve the gelatine in it.","Stir the quark cream 50 sec/speed 2.5 while adding the gelatine. Chill 30 min.","Butterfly whisk: whip 250 g cream on speed 3.","Add the quark cream, 8 sec/speed 2.5.","Spread strawberries on the base, pour the cream over.","Chill at least 5 h."]]],"notes":[]},"papas-kirschkuchen":{"title":"Dad's Cherry Cake","servings":"1 springform","prep":"","total":"35 min baking","ing":[["Dough",["250 g flour","150 g sugar","1 egg","1 sachet vanilla sugar","1/2 tsp baking powder","125 g butter"]],["Topping",["1 jar sour cherries","1 sachet cake glaze (Tortenguss)","Flaked almonds","A little sugar"]]],"steps":[["",["Knead the first 6 ingredients by hand, roll out half in the springform, bake 10 min at 200°C.","Thicken some cherry juice with the glaze, add drained cherries and the remaining juice.","Spread the cherries on the base, scatter the rest of the dough in small pieces on top, sprinkle with almonds and sugar.","Bake another 25 min at 200°C."]]],"notes":[]},"schmand-torte":{"title":"Schmand Cake with Mandarins","servings":"1 springform","prep":"","total":"20 min baking + chilling","ing":[["Base",["125 g butter","100 g sugar","2 eggs","125 g flour","1 tsp baking powder"]],["Filling",["800 g schmand (or soured cream)","2 tins mandarins","2 sachets Dr. Oetker Paradies Creme","1 sachet cream stabiliser","1 sachet vanilla sugar"]]],"steps":[["",["Base: mix ingredients, into the springform, bake 20 min at 180°C, cool.","Drain mandarins and spread on the base.","Filling: mix ingredients, spread over, chill."]]],"notes":[]},"dutch-baby":{"title":"Dutch Baby with Honey Raspberries","servings":"ca. 2 servings","prep":"20 min","total":"35 min","ing":[["Batter",["120 ml milk","50 g flour","2 eggs (beaten)","1 tbsp raw cane sugar","1 tsp vanilla sugar","1 pinch salt"]],["Honey raspberries",["125 g raspberries","2 tbsp honey","1 sprig thyme","1/2 tsp lemon juice"]],["Mascarpone cream",["3 tbsp mascarpone","1 tbsp plain yogurt","1 tbsp honey"]],["Also",["2 tbsp butter"]]],"steps":[["",["Preheat oven to 220°C with the ovenproof pan inside. Mix the batter, rest 20 min.","Gently warm raspberries with honey, thyme and lemon juice.","Mix the mascarpone cream, chill.","Take out the pan, melt the butter in it. Stir the batter, pour in, immediately into the top third of the oven, bake 15 min.","Serve with raspberries and mascarpone cream."]]],"notes":[]},"clafoutis":{"title":"Strawberry Rhubarb Clafoutis","servings":"12 pieces · 26 cm tin","prep":"","total":"40–45 min baking","ing":[["Batter",["20 g soft butter + extra for greasing","100 g flour","1 tsp baking powder","110 g sugar","20 g vanilla sugar","4 eggs","150 g milk","200 g cream","150 g rhubarb, 2 cm pieces","300 g strawberries, halved"]],["Crumble",["50 g macadamias, roasted, salted","100 g flour","50 g sugar","60 g cold butter","Icing sugar for dusting"]]],"steps":[["",["Oven 190°C, grease tin.","Flour, baking powder, sugar, vanilla sugar, eggs 8 min/37°C/speed 5.","Add butter, milk, cream, 10 sec/speed 5, scrape down, again 10 sec/speed 5. Into the tin, top with rhubarb and strawberries. Rinse bowl.","Macadamias 3 sec/speed 6.","Add flour, sugar, butter, 15 sec/speed 4. Scatter the crumble, bake on a tray 40–45 min at 190°C. Dust with icing sugar, serve e.g. with whipped cream."]]],"notes":[]},"caesar-salad":{"title":"Caesar Salad with Pepper Strawberries","servings":"ca. 4 servings","prep":"","total":"","ing":[["",["250 g strawberries, quartered","1/2 tsp pickled green pepper, crushed","400 g chicken breast, 2 cm pieces","1/2 tsp salt (1/4 + 1/4)","1/2 tsp pepper (1/4 + 1/4)","1/4 tsp sweet paprika","60 g parmesan","500 g water","4 eggs","500 g green asparagus, 5 cm pieces","100 g bacon, halved","1 anchovy fillet","1 clove garlic","1 tsp medium mustard","40–60 g lemon juice","50 g olive oil","30 g rapeseed oil","1 romaine heart, in strips"]]],"steps":[["",["Mix strawberries with green pepper. Season chicken with 1/4 tsp salt, 1/4 tsp pepper and paprika.","Parmesan 8 sec/speed 6, transfer.","Water in the bowl, eggs in the simmering basket. Varoma with chicken, tray with asparagus on top, 14 min/Varoma/speed 1. Fry bacon crisp in a pan.","Remove the basket, put the Varoma back, another 6 min/Varoma/speed 1. Peel eggs; take the yolk out of 1 egg, quarter the rest.","Rinse bowl. Yolk, garlic, anchovy, mustard, lemon juice, both oils, 1/4 tsp salt and pepper 40 sec/speed 6.","Arrange lettuce, asparagus, bacon, chicken, strawberries and eggs, drizzle with dressing, sprinkle with parmesan."]]],"notes":[]},"auberginen":{"title":"Stuffed Aubergines with Saffron and Pomegranate","servings":"6 aubergine halves","prep":"","total":"ca. 45 min","ing":[["Aubergines",["3 aubergines","80 g olive oil (50 + 30 g)","2 pinches salt","100 g bulgur","250 g water","50 g spring onions","100 g red pepper"]],["Dressing and topping",["30 g lemon juice","50 g olive oil","1 tsp saffron","1 clove garlic","180 g Greek yogurt (10%)","30 g pine nuts, toasted","50 g pomegranate seeds","20 g basil"]]],"steps":[["",["Oven 200°C, tray with baking paper.","Halve aubergines lengthwise, scoop out the flesh leaving a 1 cm rim. Brush with 50 g oil, salt, bake 15 min.","Bulgur, water, salt 8 min/100°C/reverse/gentle stir, transfer.","Aubergine flesh, spring onions, pepper, 30 g oil 5 sec/speed 5.","Add bulgur, simmering basket as splash guard, 2 min/100°C/reverse/gentle stir. Fill the aubergines, bake 10 min.","Rinse bowl. Lemon juice, oil, saffron, garlic, yogurt 30 sec/speed 5.","Serve with dressing, pomegranate, pine nuts and basil."]]],"notes":[]},"kaiserschmarrn":{"title":"Kaiserschmarrn (Shredded Pancake)","servings":"2–4 servings","prep":"","total":"ca. 15 min","ing":[["",["5 eggs (M)","1 pinch salt","150 g milk","60 g sugar","120 g plain flour","1 sachet vanilla sugar","2 tsp grated lemon zest","2 tbsp butter","2 tbsp raisins","2 tbsp icing sugar"]]],"steps":[["",["Oven 180°C top/bottom heat. Separate the eggs.","Butterfly whisk: egg whites and salt without measuring cup 6 min/speed 3.5, transfer.","Milk, sugar, flour, vanilla sugar, lemon zest without measuring cup 30 sec/speed 4, adding the yolks.","Add egg whites, 30 sec/speed 3.","Melt butter in an ovenproof pan, pour in batter, sprinkle with raisins, cook ca. 3 min until golden. Quarter, turn, finish 5 min in the oven. Tear into pieces with two forks, dust with icing sugar."]]],"notes":[]},"blintzes":{"title":"Blueberry Cheese Blintzes","servings":"4 servings","prep":"","total":"","ing":[["Batter",["15 g butter + more for frying","3 eggs (M)","1 pinch sea salt","100 g wheat flour type 550","320 ml milk"]],["Ricotta filling",["250 g ricotta","50 g sugar","1 sachet bourbon vanilla sugar","2 egg whites","1 tbsp cornflour"]],["Fruit filling",["1 tbsp butter","250 g blueberries (frozen)","40 g sugar","1 tbsp cornflour"]]],"steps":[["",["Melt butter and cool. Whisk eggs and salt, stir in flour and milk, mix in the butter.","Heat butter in a large pan, cook 1/4 of the batter 3–4 min. Stack covered, make 4 blintzes.","Heat ricotta, sugar, vanilla sugar and egg whites in a pan, bring to the boil. Stir in cornflour mixed with cold water until thick.","Melt butter, simmer blueberries and sugar 5 min, stir in cornflour mixed with water until thick. Spread both fillings on one half of each blintz, roll up, halve."]]],"notes":[]},"kraeuterfaltenbrot":{"title":"Herb Pull-Apart Bread","servings":"20 portions · 26 cm springform","prep":"20 min","total":"1 h 10 min","nutr":"173 kcal per portion","ing":[["Dough",["300 g water","1 cube fresh yeast (40 g)","1/2 tsp sugar","600 g flour","2 tsp salt","50 g oil"]],["Herb butter",["120 g soft butter + extra for greasing","1 clove garlic","1 onion, halved","3 sprigs parsley","3 sprigs basil","1 tsp salt"]]],"steps":[["",["Water, yeast, sugar 2 min/37°C/speed 2.","Add flour, salt, oil, 2 min/dough mode. Roll out to a ca. 30 cm rectangle.","Grease tin, oven 200°C.","Garlic, onion, herbs 8 sec/speed 5.","Add butter and salt, 25 sec/speed 6.","Spread herb butter on the dough, cut into 5 cm strips, fold like an accordion, set tightly in the tin, rise 15 min. Bake on a tray 25–30 min at 200°C."]]],"notes":["A square tin works especially well."]},"frittata":{"title":"Frittata with Potatoes, Pepper and Feta","servings":"2–4 servings","prep":"","total":"ca. 30 min","ing":[["",["75 ml olive oil (50 + 25 ml)","600 g waxy potatoes, thin slices","1 tsp salt (1/2 + 1/2)","1 large onion, diced","2 cloves garlic, chopped","4 eggs","Black pepper","1/2 red pepper, roughly diced","10 black olives, sliced","1 handful cherry tomatoes","100 g feta, crumbled","4 sprigs flat-leaf parsley, chopped"]]],"steps":[["",["Preheat the oven grill. Fry potatoes in 50 ml oil briefly over high heat, add 1/2 tsp salt, cook 10–15 min over lower heat until tender. Add onion and garlic for 5 min, cool slightly.","Beat eggs with 1/2 tsp salt and pepper until frothy, fold in potatoes, pepper and olives. Heat the rest of the oil in an ovenproof pan, add the mixture, top with tomatoes and feta, let set a few minutes over low heat.","Finish ca. 5 min under the grill, rest 5 min, serve with parsley."]]],"notes":["Best made the day before."]},"pfirsich-crumble":{"title":"Peach Crumble with Almonds","servings":"4 servings","prep":"15 min","total":"50 min","ing":[["Peaches",["3 ripe peaches","2 tbsp sugar","1 tsp cornflour"]],["Crumble",["125 g flour","1/4 tsp baking powder","3 tbsp sugar","1 tsp bourbon vanilla sugar","2 tbsp ground nuts","90 g cold butter, diced","2 tbsp flaked almonds"]],["Also",["Icing sugar, ice cream or vanilla sauce"]]],"steps":[["",["Oven 180°C top/bottom heat, grease a small baking dish (ca. 15 x 25 cm).","Slice peaches, toss with sugar and cornflour.","Mix flour, baking powder, sugar, vanilla sugar, nuts; rub in the ice-cold butter to crumbs.","Peaches into the dish, crumble and almonds on top, bake 30–35 min.","Serve warm with ice cream or vanilla sauce."]]],"notes":["Work with very cold butter so the crumble stays crisp."]},"tarte-tatin":{"title":"Tarte Tatin","servings":"1 tart (25–26 cm)","prep":"","total":"1 h 45 min","ing":[["Shortcrust",["200 g plain flour (type 405)","60 g icing sugar","A little lemon zest","1 pinch salt","100 g cold butter","1 egg (M)"]],["Apples and caramel",["750 g apples (e.g. Boskoop)","2 tbsp lemon juice","125 g icing sugar","4 tbsp water","125 g butter"]]],"steps":[["",["Knead the dough ingredients quickly, wrap and chill ca. 30 min.","Peel, quarter and core apples, drizzle with lemon juice.","Caramelize icing sugar and water in the tin/pan until golden, melt the butter in it.","Lay apples tightly in circles in the caramel, cook 3–4 min. Oven 200°C top/bottom (175°C fan).","Roll the dough round, lay over the apples, press the edge down. Bake 30–35 min.","Cool 5–8 min, turn out swiftly onto a plate. Serve lukewarm with cream or ice cream."]]],"notes":["Steps completed from the Lecker step-by-step recipe – compare with the original the first time."]},"gebrannte-mandeln":{"title":"Candied Cinnamon Almonds","servings":"200 g almonds","prep":"","total":"ca. 20 min","ing":[["",["120 g sugar","60 g water","1 tsp cinnamon","1 sachet vanilla sugar","200 g natural almonds"]]],"steps":[["",["Bring sugar, water, vanilla sugar and cinnamon to the boil in a pan until the sugar dissolves.","Add almonds and keep cooking, stirring constantly.","Keep stirring until the sugar turns white, dry and crystallizes (normal!).","Keep stirring until the sugar melts again and the almonds are glossy and caramelized.","Spread on baking paper, separate with a fork, let cool."]]],"notes":["Best fresh. Lovely little gift at Christmas."]},"waffeln":{"title":"Waffles","servings":"12 waffles","prep":"15 min","total":"15 min","ing":[["",["125 g butter or margarine, in pieces","100 g sugar","2 tbsp vanilla sugar","3 eggs","250 g milk","250 g flour","1 tsp baking powder","Icing sugar for dusting (optional)"]]],"steps":[["",["Preheat the waffle iron.","Mix all ingredients 1 min 30 sec/speed 5.","Bake the batter in portions in the hot waffle iron.","Dust with icing sugar if you like."]]],"notes":["Lemon zest, nuts or berries go well in the batter – add them near the end of mixing."]},"linsen-moussaka":{"title":"Lentil Moussaka","servings":"6 servings","prep":"25 min + 1 h soaking","total":"ca. 1 h 15 min","ing":[["Moussaka",["200 g red lentils","500 g water (for soaking)","120 g parmesan, in pieces","2 aubergines (ca. 400 g)","50 g olive oil","1 onion, quartered (200 g)","3 cloves garlic","1 pepper, in pieces (150 g)","400 g tinned peeled tomatoes","120 g red wine","1 tbsp oregano","1 tsp ground ginger","2 tsp salt","1/2 tsp pepper"]],["Béchamel",["40 g butter + extra for greasing","500 g milk","40 g flour"]]],"steps":[["",["Soak lentils 1 h, drain.","Parmesan 10 sec/speed 10, transfer.","Slice aubergines lengthwise 1 cm thick, place in the Varoma.","Oil, onion, garlic, pepper 5 sec/speed 5.","Add tomatoes, 2 sec/speed 5.","Add wine, oregano, ginger, salt, pepper, place Varoma, 20 min/Varoma/reverse/speed 1. Set Varoma aside.","Add lentils, 5 min/100°C/reverse/speed 2. Grease a dish, layer aubergines, spread lentils on top.","Butter, milk, flour 8 min/90°C/speed 4.","Add 60 g parmesan, 5 sec/speed 4. Pour over the lentils, sprinkle with remaining parmesan, bake 30 min at 200°C."]]],"notes":["Red lentils don't need soaking – then cook and bake ca. 5 min longer each.","Season the béchamel with nutmeg."]},"fitness-vollkornbrot":{"title":"Wholegrain Fitness Bread","servings":"1 loaf","prep":"5 min","total":"ca. 1 h 5 min","ing":[["",["300 g spelt grains","150 g wheat grains","150 g rye grains","200 g carrots, in 3 cm pieces","500 g buttermilk, room temperature","1 cube fresh yeast (40 g)","2 level tsp salt","2 tbsp white balsamic vinegar","50 g water","100 g sunflower seeds","50 g linseed, coarsely ground","Rolled oats as you like"]]],"steps":[["",["Grease a loaf tin, sprinkle with oats. Oven 220°C. The dough needs no rising.","Mill spelt 1 min/speed 10, transfer.","Mill wheat and rye 1 min/speed 10, transfer.","Carrots 4 sec/speed 5.","Buttermilk and yeast 3 min/37°C/speed 2.","Add everything except oats, 4 min/dough mode.","Spread in the tin, brush with water, sprinkle with oats.","Bake 30 min at 220°C, then 20–30 min at 180°C. Skewer test.","After 5 min loosen from the tin, cool completely."]]],"notes":["After 15 min cut 1 cm deep lengthwise.","Stays doughy inside if underbaked – better bake longer."]},"joghurtbroetchen":{"title":"Quick Yogurt Rolls","servings":"10–12 rolls","prep":"10 min","total":"40 min","ing":[["",["150 g milk","150 g water","1 cube fresh yeast","150 g yogurt","600 g wheat flour","1 1/2 tsp salt","1 pinch sugar","A little flour for dusting"]]],"steps":[["",["Milk, water, yeast 2 min/37°C/speed 2.","Add yogurt, flour, salt, sugar, 3 min/dough mode.","Scoop 10–12 portions with a wet tablespoon onto a tray.","Dust with flour, put in the cold oven, 240°C top/bottom ca. 25–30 min."]]],"notes":["Too sticky: a bit more flour or less water.","A longer rise (e.g. overnight in the fridge) gives fluffier rolls."]}}};
